/*
===============================================================================
SHAHID ERP — JAVASCRIPT FUNCTION MAP / TAB-WISE SEQUENCE
===============================================================================
This is an index only. Existing function order is intentionally preserved to
avoid changing runtime dependencies or breaking legacy functions.

01. APP / INITIALIZATION
    init, checkLogin, restoreNavState, switchToTab, refreshCurrentTab

02. SEA QUOTE
    getSeaComparisonMode, updateSeaComparisonUI, getSeaComparisonContainers,
    getCarrierNames, setCarrierNames, onMultiCarrierChange, onCarrierChange,
    onPolChange, onContainerChange, onCarrierPolChangeInternal,
    buildChargesGrid, recalcAllCarrierCharges, collectMultiCarrierGridData,
    getFormData, saveRecord, editRecord, clearForm

03. AIR QUOTE
    AIR form handlers, AIR freight/currency calculations, surcharge calculations,
    AIR multi-carrier grid, AIR totals, AIR preview/PDF/email/copy flows

04. LCL QUOTE
    LCL form handlers, LCL grid, LCL calculations, totals, preview/PDF/email/copy

05. COMMON QUOTE PREVIEW / OUTPUT
    previewQuote, previewSavedRecord, buildPreviewHTML,
    buildMultiCarrierChargeHTML, mcBuildSectionHTML, mcBuildGrandTotalHTML,
    copyPreviewTables, copyPreviewText, emailFromPreview, downloadPDF

06. SEA MULTI-CARRIER CALCULATION
    mcOutputCarriers, mcOutputRowData, mcBasisValue, mcHasOutputSell,
    mcCalculateGrandTotals, mcBuildSectionHTML, mcBuildGrandTotalHTML

07. RATE SHEET
    renderRateSheet, openRateSheetModal, saveRateSheet, editRateSheet,
    duplicateRateSheet, previewRateSheet, renewRateSheet, deleteRateSheet,
    processBulkRateImport, ratesheetBulkAction, pagination/sorting handlers

08. RATE REQUEST / DRAFTS
    getRateRequestData, sendRateRequestEmail, renderRecords, draft/quote conversion

09. RATE QUOTES
    renderRecords('rates'), quote filters, quote actions, edit/preview/email/PDF

10. DATABASE / BACKUP / AUTH
    saveDB, autoBackup, loadBackupPath, startAutoBackup, auth/login/watchdog

11. REPORTING / OPERATIONS / OTHER TABS
    Reporting, DSR, BL Drafts, Follow-up, Measurement, Database, Invoice, etc.

12. FINAL TOTAL RULE
    Rendered section Subtotals are the single source for the displayed Grand Total.
    AIR Freight = INR; SEA Freight = USD; LCL Freight = USD.
    Existing data and legacy functions are preserved.
===============================================================================
*/


// ==================== DEFAULT DATA ====================
// Factory/default data is loaded from JS/default-data.js before this file.

// ==================== MAIN DB OBJECT ====================
// Initialize defaultDB from the embedded backup (deep clone to avoid mutation)
const defaultDB = JSON.parse(JSON.stringify(EMBEDDED_BACKUP));

// ---------- Global Variables ----------
let plannerCurrentDate = new Date();
let plannerSelectedDate = new Date();
let plannerEditingNote = null;
let plannerSummaryFromDate = '';
let plannerSummaryToDate = '';
let plannerSummaryRangeActive = false;
let currentRateRequestFormat = 'seaWithShipper';
let _previewRRData = null;


// ---------- Helper Functions ----------
function formatDateKey(date) {
    const d = new Date(date);
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
}

function getDayOfWeek(dateKey) {
    return new Date(dateKey + 'T00:00:00').getDay(); // 0=Sun
}

function getDayOfMonth(dateKey) {
    return parseInt(dateKey.split('-')[2]);
}

function isDateInRange(dateKey, start, end) {
    const d = new Date(dateKey + 'T00:00:00');
    const s = new Date(start + 'T00:00:00');
    const e = new Date(end + 'T00:00:00');
    return d >= s && d <= e;
}

// ---------- Planner Date-Wise Summary ----------
function plannerNormalizeDateKey(value) {
    if (!value) return '';
    const raw = String(value).trim();
    if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) return raw;
    const dmy = raw.match(/^(\d{2})[\/-](\d{2})[\/-](\d{4})$/);
    if (dmy) return `${dmy[3]}-${dmy[2]}-${dmy[1]}`;
    const d = new Date(value);
    return isNaN(d.getTime()) ? '' : formatDateKey(d);
}

function plannerDateKeysInRange(start, end) {
    const keys = [];
    if (!start || !end || start > end) return keys;
    const d = new Date(start + 'T00:00:00');
    const e = new Date(end + 'T00:00:00');
    while (d <= e) {
        keys.push(formatDateKey(d));
        d.setDate(d.getDate() + 1);
    }
    return keys;
}

function getPlannerDateWiseCounts(start, end) {
    const allNotes = Array.isArray(db.plannerNotes) ? db.plannerNotes : [];
    const allTasks = Array.isArray(db.plannerTasks) ? db.plannerTasks : [];
    const allShipments = Array.isArray(db.shipments) ? db.shipments : [];
    const allRates = Array.isArray(db.rateSheet) ? db.rateSheet : [];
    const keys = plannerDateKeysInRange(start, end);
    const keySet = new Set(keys);

    if (!start && !end) {
        let notes = allNotes.length, tasks = allTasks.filter(t => !!t).length, milestones = 0;
        let quotes = 0, expiringQuotes = 0, expiringRates = 0, shipments = 0;
        ['sea','air','lcl'].forEach(mode => {
            (db.rates?.[mode] || []).forEach(q => {
                quotes++;
                if (q.validityDate) expiringQuotes++;
            });
        });
        allShipments.forEach(s => {
            if (s.etd) milestones++;
            if (s.eta) milestones++;
            if (['Booked','Confirmed','In Transit','Ready'].includes(s.cargoStatus)) shipments++;
        });
        expiringRates = allRates.filter(r => !!r.validTo).length;
        return {notes, milestones, quotes, expiringQuotes, expiringRates, tasks, shipments};
    }

    const counts = {notes:0, milestones:0, quotes:0, expiringQuotes:0, expiringRates:0, tasks:0, shipments:0};
    keys.forEach(key => {
        counts.notes += getNotesForDate(key).length;
        counts.milestones += getShipmentMilestonesForDate(key).length;
        counts.quotes += getQuotesForDate(key).length;
        counts.expiringQuotes += getExpiringQuotesForDate(key).length;
        counts.expiringRates += getRatesExpiringOnDate(key).length;
        counts.tasks += getTasksForDate(key).length;
        counts.shipments += getShipmentsUnderProcessForDate(key).length;
    });
    return counts;
}

function updatePlannerDateWiseSummary() {
    const fromEl = document.getElementById('planner-summary-from');
    const toEl = document.getElementById('planner-summary-to');

    const selectedKey = formatDateKey(plannerSelectedDate || new Date());
    const rangeActive = plannerSummaryRangeActive && plannerSummaryFromDate && plannerSummaryToDate;
    const from = rangeActive ? plannerSummaryFromDate : selectedKey;
    const to = rangeActive ? plannerSummaryToDate : selectedKey;

    if (fromEl) fromEl.value = rangeActive ? plannerSummaryFromDate : '';
    if (toEl) toEl.value = rangeActive ? plannerSummaryToDate : '';

    if (from && to && from > to) return false;

    const counts = getPlannerDateWiseCounts(from, to);
    const set = (id, value) => {
        const el = document.getElementById(id);
        if (el) el.textContent = String(Number(value) || 0);
    };
    set('planner-summary-notes', counts.notes);
    set('planner-summary-milestones', counts.milestones);
    set('planner-summary-quotes', counts.quotes);
    set('planner-summary-expiring-quotes', counts.expiringQuotes);
    set('planner-summary-expiring-rates', counts.expiringRates);
    set('planner-summary-tasks', counts.tasks);
    set('planner-summary-shipments', counts.shipments);

    const rangeEl = document.getElementById('planner-summary-range');
    if (rangeEl) {
        rangeEl.textContent = rangeActive
            ? `(Showing data from ${from} to ${to})`
            : `(Showing data for ${selectedKey})`;
    }
    return true;
}

function applyPlannerDateFilter() {
    const from = document.getElementById('planner-summary-from')?.value || '';
    const to = document.getElementById('planner-summary-to')?.value || '';
    if ((from && !to) || (!from && to)) { alert('Please select both From Date and To Date.'); return; }
    if (from && to && from > to) { alert('From Date cannot be later than To Date.'); return; }
    plannerSummaryFromDate = from;
    plannerSummaryToDate = to;
    plannerSummaryRangeActive = !!(from && to);
    updatePlannerDateWiseSummary();
}

function resetPlannerDateFilter() {
    plannerSummaryFromDate = '';
    plannerSummaryToDate = '';
    plannerSummaryRangeActive = false;
    updatePlannerDateWiseSummary();
}

function plannerSetDefaultSummaryRange() {
    // Planner cards default to the currently selected calendar date (today on startup).
    plannerSummaryFromDate = '';
    plannerSummaryToDate = '';
    plannerSummaryRangeActive = false;
    updatePlannerDateWiseSummary();
}

// ---------- Get Notes for a Date (including recurring) ----------
function getNotesForDate(dateKey) {
    const all = [];
    const dayOfWeek = getDayOfWeek(dateKey);
    const dayOfMonth = getDayOfMonth(dateKey);
    const currentDate = new Date(dateKey + 'T00:00:00');

    db.plannerNotes.forEach(n => {
        if (n.recurrence === 'none' || !n.recurrence) {
            if (n.date === dateKey) all.push(n);
        } else if (n.recurrence === 'weekly') {
            if (n.dayOfWeek === dayOfWeek) all.push({ ...n, _recurring: true });
        } else if (n.recurrence === 'monthly') {
            if (n.dayOfMonth === dayOfMonth) all.push({ ...n, _recurring: true });
        } else if (n.recurrence === 'thisweek') {
            // Check if the date falls within the same week as n.date
            const weekStart = getWeekStart(new Date(n.date + 'T00:00:00'));
            const weekEnd = getWeekEnd(weekStart);
            if (currentDate >= weekStart && currentDate <= weekEnd) {
                all.push({ ...n, _recurring: true });
            }
        } else if (n.recurrence === 'thismonth') {
            // Check if the date falls within the same month as n.date
            const noteDate = new Date(n.date + 'T00:00:00');
            if (noteDate.getFullYear() === currentDate.getFullYear() &&
                noteDate.getMonth() === currentDate.getMonth()) {
                all.push({ ...n, _recurring: true });
            }
        }
    });
    return all;
}

// Helper to get week start (Monday)
function getWeekStart(date) {
    const d = new Date(date);
    const day = d.getDay();
    const diff = d.getDate() - day + (day === 0 ? -6 : 1); // adjust when day is Sunday
    return new Date(d.setDate(diff));
}

function getWeekEnd(weekStart) {
    const d = new Date(weekStart);
    d.setDate(d.getDate() + 6);
    return d;
}

function getNotesForDate_Original(dateKey) {
    return (db.plannerNotes || []).filter(n => n.date === dateKey);
}

function plannerUpsertAutoTask(sourceKey, title, dueDate, details, openAction) {
    if (!dueDate) return;
    db.plannerTasks = Array.isArray(db.plannerTasks) ? db.plannerTasks : [];
    const existing = db.plannerTasks.find(t => t.autoSourceKey === sourceKey);
    const payload = {
        id: existing?.id || ('auto_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2,7)),
        srNo: existing?.srNo || '',
        title, dueDate, priority: existing?.priority || 'Medium', status: existing?.status || 'Pending',
        description: details || '', autoGenerated: true, autoSourceKey: sourceKey,
        openAction: openAction || '', updatedAt: new Date().toISOString(), createdAt: existing?.createdAt || new Date().toISOString()
    };
    if (existing) Object.assign(existing, payload); else db.plannerTasks.push(payload);
}

function syncPlannerAutoTasksForShipment(s) {
    if (!s || !s.jobNo) return;
    const job = s.jobNo || s.code || '-';
    // Planner task display should use Booking No. instead of JOB NO.
    // Keep the source key based on JOB NO./code so changing Booking No. updates
    // the existing task instead of creating a duplicate task.
    const bookingDisplay = String(s.bookingNo || s.jobBkg || '').trim() || job;
    const route = `${s.pol || '-'} → ${s.pod || '-'}`;
    const common = `${bookingDisplay} • ${s.shipper || '-'} • ${route}`;
    // ETD / ETA are displayed exclusively in the dedicated Shipment Milestones
    // section. Do not create Planner Tasks for them. All other shipment
    // operational milestones remain under Tasks.
    const taskMilestones = [
        ['SI', s.siCutoff], ['GATE', s.gateCutoff], ['SB', s.sbCutoff], ['GATE OPENING', s.gateOpening],
        ['VGM', s.vgmCutoff || s.vgmDeadline || s.vgmDate], ['CY', s.cyCutoff || s.cyDeadline || s.cyDate],
        ['PICKUP', s.pickupDate], ['CLEARANCE', s.clearanceDate],
        ['DOCS HANDOVER', s.docsHandDate], ['DGD INDEXING', s.dgdIndexingDate], ['BL RELEASE', s.blReleaseDate]
    ];
    taskMilestones.forEach(([type, date]) => plannerUpsertAutoTask(`shipment:${s.mode || s.type || 'SEA'}:${job}:${type}`, `${type} — ${bookingDisplay}`, dateOnly(date), common, `shipment:${s.code || job}`));
}

function syncPlannerAutoTasksFromInvoices() {
    db.invoices = Array.isArray(db.invoices) ? db.invoices : [];
    db.invoices.forEach(inv => {
        const due = inv.dueDate || inv.due || inv.invoiceDueDate || '';
        if (!due || String(inv.status || '').toUpperCase() === 'PAID') return;
        let job = inv.jobNo || inv.shipmentCode || '';
        if (!job && inv.quoteRef) {
            const linked = (db.shipments || []).find(s => String(s.quoteRef || s.quoteNumber || s.rateQuoteRef || '').trim() === String(inv.quoteRef).trim());
            job = linked?.jobNo || linked?.code || '';
        }
        job = job || inv.quoteRef || inv.invoiceNo || inv.id || '-';
        plannerUpsertAutoTask(`invoice:${inv.id || inv.invoiceNo || job}`, `INVOICE DUE — ${job}`, dateOnly(due), `${inv.customer || inv.client || '-'} • ${inv.pol || '-'} → ${inv.pod || '-'}`, `invoice:${inv.id || inv.invoiceNo || ''}`);
    });
}

function syncPlannerAutoTasks() {
    (db.shipments || []).forEach(syncPlannerAutoTasksForShipment);
    syncPlannerAutoTasksFromInvoices();
}

function plannerEnsureSrNumbers() {
    db.plannerTasks = Array.isArray(db.plannerTasks) ? db.plannerTasks : [];

    // Preserve all existing valid SR numbers. Only missing SR numbers receive
    // a new number, so existing records are never renumbered.
    const used = new Set();
    let max = 0;

    db.plannerTasks.forEach(task => {
        const n = Number(String(task?.srNo || '').match(/\d+/)?.[0] || 0);
        if (n > 0 && !used.has(n)) {
            used.add(n);
            max = Math.max(max, n);
            task.srNo = String(n);
        }
    });

    let changed = false;
    db.plannerTasks.forEach(task => {
        if (!task.srNo) {
            do { max += 1; } while (used.has(max));
            task.srNo = String(max);
            used.add(max);
            changed = true;
        }
    });

    if (changed) saveDB();
    return changed;
}

function plannerTaskDisplayKey(task) {
    if (!task) return '';
    // Auto-generated shipment tasks are grouped by the shipment identity, not
    // by milestone title. This prevents ETD/ETA/etc. for the same shipment from
    // appearing as separate duplicate rows in the Planner.
    if (task.autoGenerated && String(task.openAction || '').toLowerCase().startsWith('shipment:')) {
        const shipmentRef = String(task.openAction).slice('shipment:'.length).trim();
        if (shipmentRef) return 'shipment:' + shipmentRef.toLowerCase();
    }
    if (task.id) return 'id:' + String(task.id);
    return [
        task.dueDate || '',
        task.title || '',
        task.description || '',
        task.priority || '',
        task.status || ''
    ].map(v => String(v).trim().toLowerCase()).join('|');
}

function plannerShipmentGroupKey(task) {
    if (!task || !task.autoGenerated) return '';
    const action = String(task.openAction || '').trim();
    if (!action.toLowerCase().startsWith('shipment:')) return '';
    const ref = action.slice('shipment:'.length).trim();
    return ref ? 'shipment:' + ref.toLowerCase() : '';
}

function getTasksForDate(dateKey) {
    plannerEnsureSrNumbers();
    const seen = new Set();
    const tasks = [];

    (db.plannerTasks || []).forEach(task => {
        if (!task || task.dueDate !== dateKey) return;

        // ETD / ETA belong ONLY to Shipment Milestones. Hide any legacy
        // auto-generated ETD/ETA task records without deleting them from the DB.
        if (task.autoGenerated && String(task.openAction || '').toLowerCase().startsWith('shipment:')) {
            const title = String(task.title || '').trim().toUpperCase();
            if (/^(ETD|ETA)\s*[—-]/.test(title)) return;
        }

        const shipmentKey = plannerShipmentGroupKey(task);
        const key = shipmentKey || plannerTaskDisplayKey(task);
        if (seen.has(key)) {
            // Keep duplicate records in the database for data safety, but do not
            // render another row for the same shipment in the Planner.
            const existing = tasks.find(x => x._plannerGroupKey === key);
            if (existing && shipmentKey) {
                existing._groupedTaskIds = Array.from(new Set([
                    ...(existing._groupedTaskIds || []), task.id
                ].filter(Boolean)));
                existing._groupedMilestones = Array.from(new Set([
                    ...(existing._groupedMilestones || []),
                    String(task.title || '').trim()
                ].filter(Boolean)));
                if (!existing.description && task.description) existing.description = task.description;
            }
            return;
        }

        seen.add(key);
        const copy = { ...task, _plannerGroupKey: key };

        // Shipment Tasks must display BOOKING NO. (never Quote No.) as the
        // shipment reference. Older auto-generated task records may still
        // contain a Quote No. in their stored title, so resolve the current
        // shipment by the openAction reference and rebuild only the visible
        // title. The stored task record is intentionally left unchanged.
        if (shipmentKey) {
            const shipmentRef = String(task.openAction || '').slice('shipment:'.length).trim();
            const shipment = (db.shipments || []).find(s => {
                const refs = [s.code, s.jobNo, s.id, s.shipmentNo, s.bookingNo, s.jobBkg]
                    .map(v => String(v || '').trim().toLowerCase()).filter(Boolean);
                return refs.includes(shipmentRef.toLowerCase());
            });
            const bookingDisplay = String(shipment?.bookingNo || shipment?.jobBkg || '').trim();
            const titleMatch = String(task.title || '').match(/^\s*([^—-]+?)\s*[—-]\s*.*$/);
            const milestoneName = titleMatch ? titleMatch[1].trim() : String(task.title || '').trim();
            if (bookingDisplay && milestoneName) {
                copy.title = `${milestoneName} — ${bookingDisplay}`;
            }

            copy._groupedTaskIds = task.id ? [task.id] : [];
            copy._groupedMilestones = copy.title ? [String(copy.title).trim()] : [];
        }
        tasks.push(copy);
    });

    // Display Sr. No. is a table/list row number, not the persistent task number.
    // Keep stored srNo values untouched while numbering the final visible rows 1..N.
    return tasks.map((task, index) => ({
        ...task,
        displaySrNo: String(index + 1)
    }));
}

function getQuotesForDate(dateKey) {
    const all = [];
    ['sea', 'air', 'lcl', 'sea-import'].forEach(mode => {
        (Array.isArray(db.rates?.[mode]) ? db.rates[mode] : []).forEach(q => {
            const qDate = new Date(q.timestamp);
            if (formatDateKey(qDate) === dateKey) {
                all.push({ ...q, mode });
            }
        });
    });
    return all;
}

function getExpiringQuotesForDate(dateKey) {
    const all = [];
    ['sea', 'air', 'lcl', 'sea-import'].forEach(mode => {
        (Array.isArray(db.rates?.[mode]) ? db.rates[mode] : []).forEach(q => {
            if (q.validityDate === dateKey) {
                all.push({ ...q, mode });
            }
        });
    });
    return all;
}

function getShipmentsUnderProcessForDate(dateKey) {
    const statuses = ['Booked', 'Confirmed', 'In Transit', 'Ready'];
    return (db.shipments || []).filter(s => {
        const sDate = new Date(s.createdAt || s.date);
        if (formatDateKey(sDate) !== dateKey) return false;
        return statuses.includes(s.cargoStatus);
    });
}

function getShipmentMilestonesForDate(dateKey) {
    const grouped = new Map();
    const normalizeMilestoneDate = value => {
        if (!value) return '';
        const raw = String(value).trim();
        if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) return raw;
        const dmy = raw.match(/^(\d{2})[\/-](\d{2})[\/-](\d{4})$/);
        if (dmy) return `${dmy[3]}-${dmy[2]}-${dmy[1]}`;
        const parsed = new Date(raw);
        if (isNaN(parsed.getTime())) return '';
        return formatDateKey(parsed);
    };
    const shipmentIdentity = s => {
        const values = [s.id, s.code, s.jobNo, s.shipmentNo, s.bookingNo, s.jobBkg]
            .map(v => String(v || '').trim().toLowerCase()).filter(Boolean);
        return values[0] || '';
    };

    (db.shipments || []).forEach(s => {
        const etd = normalizeMilestoneDate(s.etd || s.etdDate || s.ETD);
        const eta = normalizeMilestoneDate(s.eta || s.etaDate || s.ETA);
        const etdMatch = etd === dateKey;
        const etaMatch = eta === dateKey;
        if (!etdMatch && !etaMatch) return;

        // One shipment = one visible Shipment Milestones detail for a date.
        // Prefer stable shipment identity; fall back to the first available
        // business reference for legacy records.
        const key = shipmentIdentity(s) || [s.mode || s.type || 'SEA', s.jobNo || s.bookingNo || s.shipmentNo || ''].join(':').toLowerCase();
        const existing = grouped.get(key);
        if (existing) {
            existing._hasETD = existing._hasETD || etdMatch;
            existing._hasETA = existing._hasETA || etaMatch;
            if (etdMatch && !existing.etd) existing.etd = s.etd || s.etdDate || s.ETD;
            if (etaMatch && !existing.eta) existing.eta = s.eta || s.etaDate || s.ETA;
            return;
        }

        grouped.set(key, {
            ...s,
            milestoneType: etdMatch && etaMatch ? 'ETD / ETA' : (etdMatch ? 'ETD' : 'ETA'),
            milestoneDate: etdMatch && etaMatch ? `${s.etd || s.etdDate || s.ETD || '-'} / ${s.eta || s.etaDate || s.ETA || '-'}` : (etdMatch ? (s.etd || s.etdDate || s.ETD) : (s.eta || s.etaDate || s.ETA)),
            _hasETD: etdMatch,
            _hasETA: etaMatch
        });
    });

    return Array.from(grouped.values()).map(s => ({
        ...s,
        milestoneType: s._hasETD && s._hasETA ? 'ETD / ETA' : (s._hasETD ? 'ETD' : 'ETA'),
        milestoneDate: s._hasETD && s._hasETA
            ? `${s.etd || '-'} / ${s.eta || '-'}`
            : (s._hasETD ? (s.etd || '-') : (s.eta || '-'))
    }));
}

function getRatesExpiringToday() {
    const today = new Date();
    const year = today.getFullYear();
    const month = String(today.getMonth() + 1).padStart(2, '0');
    const day = String(today.getDate()).padStart(2, '0');
    const todayStr = `${year}-${month}-${day}`; // YYYY-MM-DD

    return (db.rateSheet || []).filter(r => {
        if (!r.validTo) return false;
        // Normalize the date from the rate (it might be a string or Date)
        const rateDate = new Date(r.validTo);
        const rYear = rateDate.getFullYear();
        const rMonth = String(rateDate.getMonth() + 1).padStart(2, '0');
        const rDay = String(rateDate.getDate()).padStart(2, '0');
        const rateStr = `${rYear}-${rMonth}-${rDay}`;
        return rateStr === todayStr;
    });
}

// ---------- Render Calendar (with dots) ----------
function renderPlannerCalendar() {
    const year = plannerCurrentDate.getFullYear();
    const month = plannerCurrentDate.getMonth();
    const firstDay = new Date(year, month, 1).getDay();
    const daysInMonth = new Date(year, month + 1, 0).getDate();

    const grid = document.getElementById('planner-calendar-grid');
    grid.innerHTML = '';
    // Headers
    ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].forEach(d => {
        const div = document.createElement('div');
        div.style.fontWeight = '600';
        div.style.color = 'var(--text-light)';
        div.textContent = d;
        grid.appendChild(div);
    });

    const today = new Date();
    const todayKey = formatDateKey(today);
    const selectedKey = formatDateKey(plannerSelectedDate);

    // Precompute data for dots
    const hasData = {
        notes: {}, quotes: {}, expiring: {}, tasks: {}, shipments: {}, milestones: {}
    };

    // Notes (including recurring)
    const allDates = [];
    for (let d = 1; d <= daysInMonth; d++) {
        const dateObj = new Date(year, month, d);
        allDates.push(formatDateKey(dateObj));
    }
    allDates.forEach(dateKey => {
        // Notes (including recurring)
        const notes = getNotesForDate(dateKey);
        if (notes.length > 0) hasData.notes[dateKey] = true;
        // Quotes
        const quotes = getQuotesForDate(dateKey);
        if (quotes.length > 0) hasData.quotes[dateKey] = true;
        // Expiring
        const exp = getExpiringQuotesForDate(dateKey);
        if (exp.length > 0) hasData.expiring[dateKey] = true;
        // Tasks
        const tasks = getTasksForDate(dateKey);
        if (tasks.length > 0) hasData.tasks[dateKey] = true;
        // Shipments under process
        const ships = getShipmentsUnderProcessForDate(dateKey);
        if (ships.length > 0) hasData.shipments[dateKey] = true;
        // Milestones
        const miles = getShipmentMilestonesForDate(dateKey);
        if (miles.length > 0) hasData.milestones[dateKey] = true;
    });

    // Empty cells before first day
    for (let i = 0; i < firstDay; i++) {
        const empty = document.createElement('div');
        empty.style.visibility = 'hidden';
        grid.appendChild(empty);
    }

    for (let day = 1; day <= daysInMonth; day++) {
        const dateObj = new Date(year, month, day);
        const dateKey = formatDateKey(dateObj);
        const isToday = dateKey === todayKey;
        const isSelected = dateKey === selectedKey;

        const cell = document.createElement('div');
        cell.className = 'planner-day';
        if (isSelected) cell.classList.add('selected');
        if (isToday) cell.style.border = '2px solid var(--primary)';
        cell.textContent = day;

        // Dots container
        const dotsContainer = document.createElement('div');
        dotsContainer.className = 'dots-container';
        const dotTypes = [
            { key: 'notes', cls: 'dot-note' },
            { key: 'quotes', cls: 'dot-quote' },
            { key: 'expiring', cls: 'dot-expiring' },
            { key: 'tasks', cls: 'dot-task' },
            { key: 'shipments', cls: 'dot-shipment' },
            { key: 'milestones', cls: 'dot-milestone' }
        ];
        dotTypes.forEach(({ key, cls }) => {
            if (hasData[key] && hasData[key][dateKey]) {
                const dot = document.createElement('span');
                dot.className = 'dot ' + cls;
                dotsContainer.appendChild(dot);
            }
        });
        cell.appendChild(dotsContainer);

        cell.dataset.date = dateKey;
        cell.style.cursor = 'pointer';
        cell.addEventListener('click', function() {
            plannerSelectedDate = new Date(dateKey + 'T00:00:00');
            plannerSummaryFromDate = '';
            plannerSummaryToDate = '';
            plannerSummaryRangeActive = false;
            renderPlannerCalendar();
            loadPlannerDay(dateKey);
        });
        grid.appendChild(cell);
    }

    document.getElementById('planner-month-year').textContent =
        `${new Intl.DateTimeFormat('en', { month: 'long' }).format(plannerCurrentDate)} ${year}`;
}

// ---------- Planner Section Count Badges ----------
function updatePlannerSectionCounts(counts) {
    const map = {
        notes: 'planner-count-notes',
        milestones: 'planner-count-milestones',
        quotes: 'planner-count-quotes',
        expiringQuotes: 'planner-count-expiring-quotes',
        expiringRates: 'planner-count-expiring-rates',
        tasks: 'planner-count-tasks',
        shipments: 'planner-count-shipments'
    };
    Object.keys(map).forEach(key => {
        const el = document.getElementById(map[key]);
        if (el) el.textContent = String(Number(counts[key]) || 0);
    });
}

// ---------- Load Day Details ----------
function loadPlannerDay(dateKey) {
    const displayDate = new Date(dateKey + 'T00:00:00');
    document.getElementById('planner-selected-date').textContent =
        `📅 ${displayDate.toLocaleDateString('en-IN', { weekday:'long', day:'numeric', month:'long', year:'numeric' })}`;

    renderIslamDailyTracker(dateKey);

    // ---- NOTES ----
    const notes = getNotesForDate(dateKey);
    const notesContainer = document.getElementById('planner-notes-container');
    if (notes.length === 0) {
        notesContainer.innerHTML = '<em style="color:var(--text-light);">No notes for this day.</em>';
    } else {
        notesContainer.innerHTML = notes.map(n =>
            `<div class="planner-note-item">
                <span class="note-text">${escapeHtml(n.note)}${n._recurring ? ' <span class="note-recurring">↻ ' + (n.recurrence === 'weekly' ? 'Weekly' : n.recurrence === 'monthly' ? 'Monthly' : n.recurrence) + '</span>' : ''}</span>
                <div>
                    ${!n._recurring ? `<button class="btn btn-sm btn-preview" onclick="plannerEditNote('${n.id}')">✏️</button>` : ''}
                    ${!n._recurring ? `<button class="btn btn-sm btn-clear" onclick="plannerDeleteNote('${n.id}')">×</button>` : '<span style="font-size:0.6rem;color:var(--text-light);">(recurring)</span>'}
                </div>
            </div>`
        ).join('');
    }

    // ---- MILESTONES ----
    const milestones = getShipmentMilestonesForDate(dateKey);
    const milesContainer = document.getElementById('planner-milestones-list');
    if (milestones.length === 0) {
        milesContainer.innerHTML = '<em style="color:var(--text-light);">No milestones on this day.</em>';
    } else {
        milesContainer.innerHTML = milestones.map(s => {
            // Display BOOKING NO. for shipment milestones. The internal
            // shipment reference remains separate so the existing open/edit
            // action continues to target the correct shipment.
            const shipmentRef = s.code || s.jobNo || s.shipmentNo || s.id || '';
            const bookingDisplay = String(s.bookingNo || s.jobBkg || '').trim() || 'N/A';
            const customer = shipmentCustomer(s);
            return `<div class="planner-milestone-item">
                <div>
                    <span class="milestone-type ${s.milestoneType === 'ETD' ? 'milestone-etd' : 'milestone-eta'}">${s.milestoneType}</span>
                    <a href="javascript:void(0)" onclick="plannerOpenShipment('${String(shipmentRef).replace(/'/g, "\\'")}')" style="color:var(--primary);">
                        ${escapeHtml(bookingDisplay)} - ${customer}
                    </a>
                    (${s.pol || '-'} → ${s.pod || '-'})
                </div>
                <span style="font-size:0.7rem;color:var(--text-light);">${s.milestoneDate || '-'}</span>
            </div>`;
        }).join('');
    }

    // ---- QUOTES QUOTED ----
    const quotes = getQuotesForDate(dateKey);
    const quotesContainer = document.getElementById('planner-quotes-list');
    if (quotes.length === 0) {
        quotesContainer.innerHTML = '<em style="color:var(--text-light);">No quotes quoted on this day.</em>';
    } else {
        quotesContainer.innerHTML = quotes.map(q =>
            `<div style="padding:2px 0; border-bottom:1px solid var(--border);">
                <a href="javascript:void(0)" onclick="plannerOpenQuote('${q.quoteNumber}','${q.mode}')" style="color:var(--primary);">
                    ${q.quoteNumber}
                </a>
                - ${q.client} (${q.pol} → ${q.pod})
            </div>`
        ).join('');
    }

    // ---- EXPIRING QUOTES ----
    const expQuotes = getExpiringQuotesForDate(dateKey);
    const expQuotesContainer = document.getElementById('planner-expiring-quotes-list');
    if (expQuotes.length === 0) {
        expQuotesContainer.innerHTML = '<em style="color:var(--text-light);">No quotes expiring on this day.</em>';
    } else {
        expQuotesContainer.innerHTML = expQuotes.map(q =>
            `<div style="padding:2px 0; border-bottom:1px solid var(--border); color:#991b1b;">
                <a href="javascript:void(0)" onclick="plannerOpenQuote('${q.quoteNumber}','${q.mode}')" style="color:#991b1b;">
                    ${q.quoteNumber}
                </a>
                - ${q.client} (${q.pol} → ${q.pod})
            </div>`
        ).join('');
    }

    // ---- RATES EXPIRING ON SELECTED DATE (from Rate Sheet) ----
    const expRates = getRatesExpiringOnDate(dateKey);
    const expRatesContainer = document.getElementById('planner-expiring-today-list-detail');
    if (expRates.length === 0) {
        expRatesContainer.innerHTML = '<em style="color:var(--text-light);">No rates expiring on this date.</em>';
    } else {
        expRatesContainer.innerHTML = expRates.map(r =>
            `<div style="padding:2px 0; border-bottom:1px solid var(--border);">
                <strong>${r.carrierName}</strong> - ${r.pol} → ${r.pod} (${r.freightType}) - ${r.freightAmount} ${r.currency}
                <button class="btn btn-sm btn-preview" onclick="plannerRenewRate('${r.id}')">🔄 Renew</button>
            </div>`
        ).join('');
    }

    // ---- TASKS ----
    const tasks = getTasksForDate(dateKey);
    const tasksContainer = document.getElementById('planner-tasks-list');
    if (tasks.length === 0) {
        tasksContainer.innerHTML = '<em style="color:var(--text-light);">No tasks for this day.</em>';
    } else {
        tasksContainer.innerHTML = tasks.map(t => {
            const statusClass = t.status === 'Done' ? 'task-status-done' :
                              t.status === 'In Progress' ? 'task-status-progress' : 'task-status-pending';
            const grouped = Array.isArray(t._groupedMilestones) ? t._groupedMilestones : [];
            const milestoneText = grouped.length > 1 ? ` <span style="font-size:0.72rem;color:var(--text-light);">(${grouped.map(escapeHtml).join(' • ')})</span>` : '';
            const groupedCount = Array.isArray(t._groupedTaskIds) ? t._groupedTaskIds.length : 1;
            const groupLabel = groupedCount > 1 ? ` <span style="font-size:0.68rem;color:var(--text-light);">[${groupedCount} shipment entries]</span>` : '';
            return `<div class="planner-task-item">
                <span class="task-title"><strong style="display:inline-block; min-width:28px; margin-right:8px;">${escapeHtml(t.displaySrNo || '-')}.</strong>${escapeHtml(t.title)}${milestoneText}${groupLabel} ${t.priority === 'High' ? '🔴' : t.priority === 'Low' ? '🟢' : '🟡'}</span>
                <span class="task-status ${statusClass}">${t.status || 'Pending'}</span>
                <div>
                    <button class="btn btn-sm btn-preview" onclick="plannerToggleTaskStatus('${t.id}')">🔄</button>
                    <button class="btn btn-sm btn-clear" onclick="plannerDeleteTask('${t.id}')">×</button>
                </div>
            </div>`;
        }).join('');
    }

    // ---- SHIPMENTS UNDER PROCESS ----
    const shipments = getShipmentsUnderProcessForDate(dateKey);
    const shipContainer = document.getElementById('planner-shipments-list');
    if (shipments.length === 0) {
        shipContainer.innerHTML = '<em style="color:var(--text-light);">No shipments under process on this day.</em>';
    } else {
        shipContainer.innerHTML = shipments.map(s =>
            `<div style="padding:2px 0; border-bottom:1px solid var(--border);">
                <a href="javascript:void(0)" onclick="plannerOpenShipment('${s.code}')" style="color:var(--primary);">
                    ${s.code} - ${s.shipper}
                </a>
                (${s.pol} → ${s.pod}) - ${s.cargoStatus}
            </div>`
        ).join('');
    }

    updatePlannerSectionCounts({
        notes: notes.length,
        milestones: milestones.length,
        quotes: quotes.length,
        expiringQuotes: expQuotes.length,
        expiringRates: expRates.length,
        tasks: tasks.length,
        shipments: shipments.length
    });

    // Keep the date-wise command-center totals synchronized with Planner data.
    updatePlannerDateWiseSummary();
    // (No need to call updateExpiringToday() separately)
}

// ---------- Expiring Today ----------
function updateExpiringToday() {
    const expiring = typeof getRatesExpiringToday === 'function' ? getRatesExpiringToday() : [];
    // Current Planner uses the section badge + detail list. Keep compatibility
    // with the older count/list IDs without assuming they still exist.
    const countEl = document.getElementById('planner-expiring-today-count')
        || document.getElementById('planner-count-expiring-rates');
    const listEl = document.getElementById('planner-expiring-today-list')
        || document.getElementById('planner-expiring-today-list-detail');

    if (countEl) countEl.textContent = String(expiring.length);
    if (!listEl) return;

    if (expiring.length === 0) {
        listEl.innerHTML = '<em style="color:var(--text-light);">No rates expiring on this date.</em>';
        return;
    }

    listEl.innerHTML = expiring.map(r =>
        `<div class="expiring-item">
            <strong>${r.carrierName}</strong> - ${r.pol} → ${r.pod} (${r.freightType}) - ${r.freightAmount} ${r.currency}
            <button class="btn btn-sm btn-preview" onclick="plannerRenewRate('${r.id}')">🔄 Renew</button>
        </div>`
    ).join('');
}

// ---------- Navigation ----------
function plannerChangeMonth(delta) {
    plannerCurrentDate.setMonth(plannerCurrentDate.getMonth() + delta);
    renderPlannerCalendar();
    const selectedKey = formatDateKey(plannerSelectedDate);
    loadPlannerDay(selectedKey);
}

function plannerGoToday() {
    plannerCurrentDate = new Date();
    plannerSelectedDate = new Date();
    plannerSummaryFromDate = '';
    plannerSummaryToDate = '';
    plannerSummaryRangeActive = false;
    renderPlannerCalendar();
    loadPlannerDay(formatDateKey(plannerSelectedDate));
}

// ---------- Notes CRUD with Recurrence ----------
function plannerAddNote() {
    document.getElementById('planner-note-input-area').style.display = 'block';
    document.getElementById('planner-note-text').value = '';
    document.getElementById('planner-note-recurring').checked = false;
    document.getElementById('planner-note-recurrence-type').style.display = 'none';
    plannerEditingNote = null;
}

function plannerCancelNote() {
    document.getElementById('planner-note-input-area').style.display = 'none';
    plannerEditingNote = null;
}

function plannerSaveNote() {
    const text = document.getElementById('planner-note-text').value.trim();
    if (!text) return alert('Please enter a note.');
    const dateKey = formatDateKey(plannerSelectedDate);
    const isRecurring = document.getElementById('planner-note-recurring').checked;
    let recurrenceType = document.getElementById('planner-note-recurrence-type').value;

    // If not recurring, force 'none'
    if (!isRecurring) recurrenceType = 'none';

    if (plannerEditingNote) {
        const note = db.plannerNotes.find(n => n.id === plannerEditingNote);
        if (note) {
            note.note = text;
            note.updatedAt = new Date().toISOString();
            note.recurrence = recurrenceType;
            if (recurrenceType !== 'none') {
                note.dayOfWeek = getDayOfWeek(dateKey);
                note.dayOfMonth = getDayOfMonth(dateKey);
            } else {
                delete note.dayOfWeek;
                delete note.dayOfMonth;
            }
        }
    } else {
        const newNote = {
            id: 'note_' + Date.now(),
            date: dateKey,
            note: text,
            recurrence: recurrenceType,
            createdAt: new Date().toISOString(),
            updatedAt: new Date().toISOString()
        };
        if (recurrenceType !== 'none') {
            newNote.dayOfWeek = getDayOfWeek(dateKey);
            newNote.dayOfMonth = getDayOfMonth(dateKey);
        }
        db.plannerNotes.push(newNote);
    }
    saveDB();
    plannerCancelNote();
    loadPlannerDay(dateKey);
    renderPlannerCalendar();
    autoBackup();
}

function legacy_plannerAddTaskQuick() {
    plannerAddTaskQuick();
}

function plannerEditNote(id) {
    const note = db.plannerNotes.find(n => n.id === id);
    if (!note || note._recurring) {
        alert('Recurring notes cannot be edited directly. Delete and create a new one.');
        return;
    }
    document.getElementById('planner-note-input-area').style.display = 'block';
    document.getElementById('planner-note-text').value = note.note;
    const isRecurring = note.recurrence && note.recurrence !== 'none';
    document.getElementById('planner-note-recurring').checked = isRecurring;
    const typeSelect = document.getElementById('planner-note-recurrence-type');
    typeSelect.style.display = isRecurring ? 'inline-block' : 'none';
    typeSelect.value = note.recurrence || 'weekly';
    plannerEditingNote = id;
}

function plannerDeleteNote(id) {
    if (!confirm('Delete this note?')) return;
    const idx = db.plannerNotes.findIndex(n => n.id === id);
    if (idx !== -1) db.plannerNotes.splice(idx, 1);
    saveDB();
    loadPlannerDay(formatDateKey(plannerSelectedDate));
    renderPlannerCalendar();
    autoBackup();
}


// ---------- Islam Daily Tracker (date-wise persistence) ----------
function ensureIslamDailyTrackerStore() {
    if (!db.islamDailyTracker || typeof db.islamDailyTracker !== 'object' || Array.isArray(db.islamDailyTracker)) {
        db.islamDailyTracker = {};
    }
    return db.islamDailyTracker;
}

function normalizeIslamDateKey(dateKey) {
    const v = String(dateKey || '').trim();
    return /^\d{4}-\d{2}-\d{2}$/.test(v) ? v : formatDateKey(plannerSelectedDate || new Date());
}

function getIslamDailyEntry(dateKey) {
    const store = ensureIslamDailyTrackerStore();
    return store[normalizeIslamDateKey(dateKey)] || null;
}

function normalizeIslamPrayerStatus(prayer) {
    const raw = String(prayer?.status || '').trim().toUpperCase();
    if (['YES','NO','QAZA','JAMAT'].includes(raw)) return raw;
    return prayer?.done === true ? 'YES' : 'NO';
}

function saveIslamDailyEntry(dateKey, entry) {
    const key = normalizeIslamDateKey(dateKey);
    const store = ensureIslamDailyTrackerStore();
    const old = store[key] || {};
    const prayers = entry?.prayers || {};
    store[key] = {
        date: key,
        prayers: {
            fajar: { status: normalizeIslamPrayerStatus(prayers.fajar), done: normalizeIslamPrayerStatus(prayers.fajar) !== 'NO', rakat: Math.max(0, Number(prayers.fajar?.rakat) || 0) },
            zuhar: { status: normalizeIslamPrayerStatus(prayers.zuhar), done: normalizeIslamPrayerStatus(prayers.zuhar) !== 'NO', rakat: Math.max(0, Number(prayers.zuhar?.rakat) || 0) },
            asr: { status: normalizeIslamPrayerStatus(prayers.asr), done: normalizeIslamPrayerStatus(prayers.asr) !== 'NO', rakat: Math.max(0, Number(prayers.asr?.rakat) || 0) },
            maghrib: { status: normalizeIslamPrayerStatus(prayers.maghrib), done: normalizeIslamPrayerStatus(prayers.maghrib) !== 'NO', rakat: Math.max(0, Number(prayers.maghrib?.rakat) || 0) },
            isha: { status: normalizeIslamPrayerStatus(prayers.isha), done: normalizeIslamPrayerStatus(prayers.isha) !== 'NO', rakat: Math.max(0, Number(prayers.isha?.rakat) || 0) }
        },
        quranReading: entry.quranReading === true,
        meditation: entry.meditation === true,
        yesterdaySleep: String(entry.yesterdaySleep ?? old.yesterdaySleep ?? ''),
        todayWakeUp: String(entry.todayWakeUp ?? old.todayWakeUp ?? ''),
        daroodCount: Math.max(0, Math.floor(Number(entry.daroodCount ?? old.daroodCount) || 0)),
        goodDeedCount: Math.max(0, Math.floor(Number(entry.goodDeedCount ?? old.goodDeedCount) || 0)),
        badDeedCount: Math.max(0, Math.floor(Number(entry.badDeedCount ?? old.badDeedCount) || 0)),
        updatedAt: new Date().toISOString()
    };
    saveDB();
    return store[key];
}
function islamTrackerStatus(statusOrDone) {
    const status = typeof statusOrDone === 'boolean'
        ? (statusOrDone ? 'YES' : 'NO')
        : normalizeIslamPrayerStatus({ status: statusOrDone });
    const cls = status === 'YES' || status === 'JAMAT' ? 'color:#059669;' : status === 'QAZA' ? 'color:#b45309;' : 'color:#dc2626;';
    return `<span style="${cls}font-weight:700;">● ${status}</span>`;
}

function islamTrackerYesNo(done) {
    return islamTrackerStatus(done);
}

function canViewIslamDailyTracker(user = checkLogin()) {
    if (!user) return false;
    return String(user.id || '').trim().toLowerCase() === 'shaikh shahid';
}

function renderIslamDailyTracker(dateKey) {
    const root = document.getElementById('islam-daily-tracker');
    if (!root) return;
    if (!canViewIslamDailyTracker()) {
        root.innerHTML = '';
        root.style.display = 'none';
        return;
    }
    root.style.display = '';
    const key = normalizeIslamDateKey(dateKey);
    const entry = getIslamDailyEntry(key) || {
        prayers: { fajar:{done:false,rakat:0}, zuhar:{done:false,rakat:0}, asr:{done:false,rakat:0}, maghrib:{done:false,rakat:0}, isha:{done:false,rakat:0} },
        quranReading:false, meditation:false, yesterdaySleep:'', todayWakeUp:'', daroodCount:0, goodDeedCount:0, badDeedCount:0
    };
    const fmt = new Date(key + 'T00:00:00').toLocaleDateString('en-IN', {day:'2-digit', month:'2-digit', year:'numeric', weekday:'long'});
    const rows = [
        ['Fajar','fajar','2'], ['Zuhar','zuhar','4'], ['Asr','asr','4'], ['Maghrib','maghrib','3'], ['Isha','isha','4']
    ];
    root.innerHTML = `
      <div class="islam-tracker-header"><span>🕌 Islam - Daily Tracker</span><span>📅 ${fmt}</span></div>
      <div class="islam-tracker-body">
        <table class="islam-tracker-table">
          <thead><tr><th>DETAILS</th><th>TODAY</th></tr></thead>
          <tbody>
            <tr class="islam-group"><td colspan="2">1. All 5 Times Prayer (Mark Yes / No &amp; No. of Rakat)</td></tr>
            ${rows.map(([label,keyName,defaultRakat]) => {
                const pr = entry.prayers[keyName] || {status:'NO',done:false,rakat:0};
                return `<tr><td>🕌 ${label}</td><td><span>${islamTrackerStatus(pr.status ?? pr.done)}</span> <span class="islam-rakat">${pr.rakat} Rakat</span></td></tr>`;
            }).join('')}
            <tr class="islam-group"><td colspan="2">2. Quran Reading <small>(Done or Not)</small></td></tr>
            <tr><td>📖 Quran Reading</td><td>${islamTrackerYesNo(entry.quranReading)}</td></tr>
            <tr class="islam-group"><td colspan="2">3. Meditation <small>(Done or Not)</small></td></tr>
            <tr><td>🧘 Meditation</td><td>${islamTrackerYesNo(entry.meditation)}</td></tr>
            <tr class="islam-group"><td colspan="2">4. Darood Counting</td></tr>
            <tr><td>📿 DAROOD</td><td><div class="islam-darood-counter"><button type="button" class="islam-darood-btn" onclick="changeIslamDaroodCount('${key}',-1)" aria-label="Decrease Darood count">−</button><span id="islam-darood-count-${key}" class="islam-darood-count">${Math.max(0,Math.floor(Number(entry.daroodCount)||0))}</span><button type="button" class="islam-darood-btn" onclick="changeIslamDaroodCount('${key}',1)" aria-label="Increase Darood count">+</button></div></td></tr>
            <tr class="islam-group"><td colspan="2">5. Good Deed / Bad Deed</td></tr>
            <tr><td>✅ GOOD DEED</td><td><strong>${Math.max(0, Math.floor(Number(entry.goodDeedCount)||0))}</strong></td></tr>
            <tr><td>❌ BAD DEED</td><td><strong>${Math.max(0, Math.floor(Number(entry.badDeedCount)||0))}</strong></td></tr>
            <tr class="islam-group"><td colspan="2">6. Sleep &amp; Wake Up</td></tr>
            <tr><td>😴 Yesterday Sleep (Time)</td><td>${entry.yesterdaySleep ? '🕐 ' + escapeHtml(entry.yesterdaySleep) : '—'}</td></tr>
            <tr><td>☀️ Today Wake Up (Time)</td><td>${entry.todayWakeUp ? '🕐 ' + escapeHtml(entry.todayWakeUp) : '—'}</td></tr>
          </tbody>
        </table>
        <div class="islam-tracker-actions"><button class="btn btn-sm btn-success" type="button" onclick="openIslamDailyEditor('${key}')">✏️ ${getIslamDailyEntry(key) ? 'EDIT' : 'ADD TODAY\'S ENTRY'}</button></div>
      </div>`;
}

function openIslamDailyEditor(dateKey) {
    if (!canViewIslamDailyTracker()) { alert('You do not have permission to access Islam - Daily Tracker.'); return false; }
    const key = normalizeIslamDateKey(dateKey);
    const entry = getIslamDailyEntry(key) || { prayers:{}, quranReading:false, meditation:false, yesterdaySleep:'', todayWakeUp:'', daroodCount:0, goodDeedCount:0, badDeedCount:0 };
    const root = document.getElementById('islam-daily-tracker');
    if (!root) return;
    const p = entry.prayers || {};
    const field = (name, val) => `<select id="islam-${name}" class="islam-input"><option value="NO" ${String(val || 'NO').toUpperCase() === 'NO' ? 'selected' : ''}>NO</option><option value="YES" ${String(val || '').toUpperCase() === 'YES' ? 'selected' : ''}>YES</option><option value="QAZA" ${String(val || '').toUpperCase() === 'QAZA' ? 'selected' : ''}>QAZA</option><option value="JAMAT" ${String(val || '').toUpperCase() === 'JAMAT' ? 'selected' : ''}>JAMAT</option></select>`;
    const rakat = (name, val) => `<input id="islam-${name}-rakat" class="islam-input islam-rakat-input" type="number" min="0" step="1" value="${Math.max(0,Number(val)||0)}">`;
    root.innerHTML = `
      <div class="islam-tracker-header"><span>🕌 Islam - Daily Tracker</span><span>📅 ${key}</span></div>
      <div class="islam-tracker-body">
        <table class="islam-tracker-table islam-editor-table"><thead><tr><th>DETAILS</th><th>TODAY</th></tr></thead><tbody>
        <tr class="islam-group"><td colspan="2">1. All 5 Times Prayer (Mark Yes / No &amp; No. of Rakat)</td></tr>
        <tr><td>🕌 Fajar</td><td>${field('fajar',p.fajar?.status ?? (p.fajar?.done ? 'YES' : 'NO'))} ${rakat('fajar',p.fajar?.rakat)} <span>Rakat</span></td></tr>
        <tr><td>🕌 Zuhar</td><td>${field('zuhar',p.zuhar?.status ?? (p.zuhar?.done ? 'YES' : 'NO'))} ${rakat('zuhar',p.zuhar?.rakat)} <span>Rakat</span></td></tr>
        <tr><td>🕌 Asr</td><td>${field('asr',p.asr?.status ?? (p.asr?.done ? 'YES' : 'NO'))} ${rakat('asr',p.asr?.rakat)} <span>Rakat</span></td></tr>
        <tr><td>🕌 Maghrib</td><td>${field('maghrib',p.maghrib?.status ?? (p.maghrib?.done ? 'YES' : 'NO'))} ${rakat('maghrib',p.maghrib?.rakat)} <span>Rakat</span></td></tr>
        <tr><td>🕌 Isha</td><td>${field('isha',p.isha?.status ?? (p.isha?.done ? 'YES' : 'NO'))} ${rakat('isha',p.isha?.rakat)} <span>Rakat</span></td></tr>
        <tr class="islam-group"><td colspan="2">2. Quran Reading <small>(Done or Not)</small></td></tr>
        <tr><td>📖 Quran Reading</td><td>${field('quran',entry.quranReading)}</td></tr>
        <tr class="islam-group"><td colspan="2">3. Meditation <small>(Done or Not)</small></td></tr>
        <tr><td>🧘 Meditation</td><td>${field('meditation',entry.meditation)}</td></tr>
        <tr class="islam-group"><td colspan="2">4. Darood Counting</td></tr>
        <tr><td>📿 Darood</td><td><input id="islam-darood" class="islam-input" type="number" min="0" step="1" value="${Math.max(0,Number(entry.daroodCount)||0)}"></td></tr>
        <tr class="islam-group"><td colspan="2">5. Good Deed / Bad Deed</td></tr>
        <tr><td>✅ GOOD DEED</td><td><input id="islam-good-deed" class="islam-input" type="number" min="0" step="1" value="${Math.max(0,Math.floor(Number(entry.goodDeedCount)||0))}"></td></tr>
        <tr><td>❌ BAD DEED</td><td><input id="islam-bad-deed" class="islam-input" type="number" min="0" step="1" value="${Math.max(0,Math.floor(Number(entry.badDeedCount)||0))}"></td></tr>
        <tr class="islam-group"><td colspan="2">6. Sleep &amp; Wake Up</td></tr>
        <tr><td>😴 Yesterday Sleep (Time)</td><td><input id="islam-sleep" class="islam-input" type="time" value="${escapeHtml(entry.yesterdaySleep || '')}"></td></tr>
        <tr><td>☀️ Today Wake Up (Time)</td><td><input id="islam-wakeup" class="islam-input" type="time" value="${escapeHtml(entry.todayWakeUp || '')}"></td></tr>
        </tbody></table>
        <div class="islam-tracker-actions"><button class="btn btn-sm btn-success" type="button" onclick="saveIslamDailyEditor('${key}')">💾 SAVE</button><button class="btn btn-sm btn-clear" type="button" onclick="renderIslamDailyTracker('${key}')">CANCEL</button></div>
      </div>`;
}

function saveIslamDailyEditor(dateKey) {
    if (!canViewIslamDailyTracker()) { alert('You do not have permission to access Islam - Daily Tracker.'); return false; }
    const key = normalizeIslamDateKey(dateKey);
    const val = n => String(document.getElementById('islam-' + n)?.value || 'NO').toUpperCase();
    const num = n => Math.max(0, Math.floor(Number(document.getElementById('islam-' + n + '-rakat')?.value) || 0));
    const entry = {
        prayers: {
            fajar:{status:val('fajar'),done:val('fajar') !== 'NO',rakat:num('fajar')}, zuhar:{status:val('zuhar'),done:val('zuhar') !== 'NO',rakat:num('zuhar')}, asr:{status:val('asr'),done:val('asr') !== 'NO',rakat:num('asr')}, maghrib:{status:val('maghrib'),done:val('maghrib') !== 'NO',rakat:num('maghrib')}, isha:{status:val('isha'),done:val('isha') !== 'NO',rakat:num('isha')}
        },
        quranReading: val('quran') === 'YES',
        meditation: val('meditation') === 'YES',
        yesterdaySleep: document.getElementById('islam-sleep')?.value || '',
        todayWakeUp: document.getElementById('islam-wakeup')?.value || '',
        daroodCount: Math.max(0, Math.floor(Number(document.getElementById('islam-darood')?.value) || 0)),
        goodDeedCount: Math.max(0, Math.floor(Number(document.getElementById('islam-good-deed')?.value) || 0)),
        badDeedCount: Math.max(0, Math.floor(Number(document.getElementById('islam-bad-deed')?.value) || 0))
    };
    saveIslamDailyEntry(key, entry);
    renderIslamDailyTracker(key);
}

// ---------- Darood Counting ----------
function changeIslamDaroodCount(dateKey, delta) {
    if (!canViewIslamDailyTracker()) { alert('You do not have permission to access Islam - Daily Tracker.'); return false; }
    const key = normalizeIslamDateKey(dateKey);
    const current = getIslamDailyEntry(key) || {
        prayers: {
            fajar:{done:false,rakat:0}, zuhar:{done:false,rakat:0},
            asr:{done:false,rakat:0}, maghrib:{done:false,rakat:0}, isha:{done:false,rakat:0}
        },
        quranReading:false,
        meditation:false,
        yesterdaySleep:'',
        todayWakeUp:'',
        daroodCount:0
    };
    const currentCount = Math.max(0, Math.floor(Number(current.daroodCount) || 0));
    const nextCount = Math.max(0, currentCount + (Number(delta) > 0 ? 1 : -1));
    current.daroodCount = nextCount;
    saveIslamDailyEntry(key, current);
    renderIslamDailyTracker(key);
}

// ---------- Tasks CRUD ----------
function plannerAddTaskModal() {
    const dateKey = formatDateKey(plannerSelectedDate);
    const srNo = plannerNextSrNumber();

    appPrompt('Enter task title:', '', (title) => {
        if (!title || !title.trim()) return;

        appPrompt('Select task priority:', 'Medium', (priority) => {
            db.plannerTasks.push({
                id: 'task_' + Date.now() + '_' + srNo,
                srNo: String(srNo),
                title: title.trim(),
                dueDate: dateKey,
                priority: priority || 'Medium',
                status: 'Pending',
                description: '',
                createdAt: new Date().toISOString(),
                updatedAt: new Date().toISOString()
            });
            saveDB();
            loadPlannerDay(dateKey);
            renderPlannerCalendar();
            autoBackup();
        }, ['High', 'Medium', 'Low']);
    });
}

function plannerNextSrNumber() {
    plannerEnsureSrNumbers();
    const tasks = Array.isArray(db.plannerTasks) ? db.plannerTasks : [];
    let max = 0;
    tasks.forEach(task => {
        const match = String(task?.srNo || '').match(/^(?:TASK-)?(\d+)$/i);
        if (match) max = Math.max(max, Number(match[1]));
    });
    return max + 1;
}

function plannerAddTaskQuick() {
    const dateKey = formatDateKey(plannerSelectedDate);
    const srNo = plannerNextSrNumber();

    appPrompt('Enter task title:', '', (title) => {
        if (!title || !title.trim()) return;

        appPrompt('Select task priority:', 'Medium', (priority) => {
            db.plannerTasks.push({
                id: 'task_' + Date.now() + '_' + srNo,
                srNo: String(srNo),
                title: title.trim(),
                dueDate: dateKey,
                priority: priority || 'Medium',
                status: 'Pending',
                description: '',
                createdAt: new Date().toISOString(),
                updatedAt: new Date().toISOString()
            });
            saveDB();
            loadPlannerDay(dateKey);
            renderPlannerCalendar();
            autoBackup();
        }, ['High', 'Medium', 'Low']);
    });
}

function plannerGetShipmentTaskGroup(task) {
    if (!task || !task.autoGenerated) return [];
    const action = String(task.openAction || '').trim();
    if (!action.toLowerCase().startsWith('shipment:')) return [task];
    const ref = action.slice('shipment:'.length).trim().toLowerCase();
    if (!ref) return [task];
    const dateKey = task.dueDate || '';
    return (db.plannerTasks || []).filter(t => {
        if (!t || !t.autoGenerated || t.dueDate !== dateKey) return false;
        const a = String(t.openAction || '').trim();
        return a.toLowerCase().startsWith('shipment:') &&
               a.slice('shipment:'.length).trim().toLowerCase() === ref;
    });
}

function plannerToggleTaskStatus(id) {
    const task = db.plannerTasks.find(t => t.id === id);
    if (!task) return;
    const statuses = ['Pending', 'In Progress', 'Done'];
    let idx = statuses.indexOf(task.status);
    idx = (idx + 1) % statuses.length;
    const nextStatus = statuses[idx];
    const group = plannerGetShipmentTaskGroup(task);
    group.forEach(item => {
        item.status = nextStatus;
        item.updatedAt = new Date().toISOString();
    });
    saveDB();
    loadPlannerDay(formatDateKey(plannerSelectedDate));
    renderPlannerCalendar();
    autoBackup();
}

function plannerDeleteTask(id) {
    const task = db.plannerTasks.find(t => t.id === id);
    if (!task) return;
    const group = plannerGetShipmentTaskGroup(task);
    const isShipmentGroup = group.length > 1;
    const message = isShipmentGroup
        ? `Delete all ${group.length} Planner entries for this shipment on this date?`
        : 'Delete this task?';
    if (!confirm(message)) return;
    const ids = new Set(group.map(item => item.id));
    db.plannerTasks = (db.plannerTasks || []).filter(item => !ids.has(item.id));
    saveDB();
    loadPlannerDay(formatDateKey(plannerSelectedDate));
    renderPlannerCalendar();
    autoBackup();
}

// ---------- Navigation to other tabs ----------
function plannerOpenQuote(quoteNumber, mode) {
    let quote = null, idx = -1, target = 'rates';
    const modes = ['sea','air','lcl'];
    if (modes.includes(mode)) {
        const arr = db.rates[mode];
        const found = arr.findIndex(q => q.quoteNumber === quoteNumber);
        if (found !== -1) {
            quote = arr[found];
            idx = found;
        } else {
            const draftArr = db.drafts[mode];
            const foundD = draftArr.findIndex(q => q.quoteNumber === quoteNumber);
            if (foundD !== -1) {
                quote = draftArr[foundD];
                idx = foundD;
                target = 'drafts';
            }
        }
    }
    if (!quote) return alert('Quote not found.');
    switchToTab(target);
    setTimeout(() => {
        previewSavedRecord(target, mode, idx);
    }, 500);
}

function plannerOpenShipment(code) {
    const s = db.shipments.find(s =>
        (s.code || s.jobNo || s.shipmentNo || s.id) === code
    );
    if (!s) return alert('Shipment not found.');
    switchToTab('dsr');
    setTimeout(() => {
        editDsrShipment(db.shipments.indexOf(s));
    }, 500);
}

