function changeDsrMode() {
    const mode = String(document.getElementById('dsr-mode')?.value || 'SEA').toUpperCase();
    const jobNo = document.getElementById('dsr-job-no')?.value || '';
    // Re-open the same form preserving currently entered data where possible.
    // When editing an existing shipment, keep the original record as the base so
    // fields that are not present in this lightweight snapshot are not lost.
    const existing = (Number.isInteger(dsrEditIdx) && dsrEditIdx >= 0 && db.shipments?.[dsrEditIdx])
        ? db.shipments[dsrEditIdx]
        : null;
    const current = {
        mode,
        jobNo,
        code: document.getElementById('dsr-code')?.value || '',
        date: document.getElementById('dsr-date')?.value || '',
        shipper: document.getElementById('dsr-shipper')?.value || '',
        packages: document.getElementById('dsr-packages')?.value || '',
        pol: document.getElementById('dsr-pol')?.value || '',
        pod: document.getElementById('dsr-pod')?.value || '',
        liner: document.getElementById('dsr-liner')?.value || '',
        etd: document.getElementById('dsr-etd')?.value || '',
        eta: document.getElementById('dsr-eta')?.value || '',
        cargoStatus: document.getElementById('dsr-cargo-status')?.value || '',
        docsStatus: document.getElementById('dsr-docs-status')?.value || '',
        remarks: document.getElementById('dsr-remarks')?.value || '',
        containers: typeof getDsrContainerRows === 'function' ? getDsrContainerRows() : []
    };
    openDsrModal(mode, dsrEditIdx, current);
}

// ===== OPEN DSR MODAL (UNIFIED) =====
function openDsrModal(mode, editIdx = null, prefill = null) {
    document.getElementById('addShipmentDropdown').classList.remove('show');
    addShipmentDropdownOpen = false;

    const parsedIdx = (editIdx === null || editIdx === undefined || editIdx === '')
        ? null
        : Number(editIdx);
    const hasValidEdit = Number.isInteger(parsedIdx) && parsedIdx >= 0 && !!db.shipments?.[parsedIdx];
    dsrEditIdx = hasValidEdit ? parsedIdx : null;

    const body = document.getElementById('dsrModalBody');
    const existing = hasValidEdit ? db.shipments[parsedIdx] : null;
    let s = existing ? { ...existing } : {};
    let isEdit = hasValidEdit;

    // Prefill may be supplied by quote-to-shipment or mode-change flows.
    // If an edit index exists, ALWAYS retain EDIT mode and overlay only the
    // supplied values on top of the existing shipment. This prevents the form
    // from silently becoming a NEW/SAVE form.
    if (prefill) {
        s = { ...s, ...prefill };
    }

    // Existing shipment data is authoritative for mode unless the user is
    // explicitly changing it from the current form.
    const resolvedMode = String(s.mode || s.type || mode || 'SEA').toUpperCase();
    mode = ['SEA', 'AIR', 'LCL'].includes(resolvedMode) ? resolvedMode : 'SEA';

    // Ensure mode is set
    s.mode = mode;
    s.type = s.type || mode;

    body.innerHTML = buildDsrForm(s, mode, isEdit);
    document.getElementById('dsrModalTitle').textContent = `${mode} Shipment ~ DSR`;
    openModal('dsrModal');

    setTimeout(() => {
        const visibleCarriers = ['ALL', ...db.carriers.filter(c => !(db.hiddenItems.carriers || []).includes(c))];
        const visiblePol = db.pol.filter(p => !(db.hiddenItems.pol || []).includes(p));
        const visiblePod = db.pod.filter(p => !(db.hiddenItems.pod || []).includes(p));

        // Populate editable dropdowns (datalist). Manual values are allowed and saved as entered.
        const fillDsrDatalist = (id, values) => {
            const list = document.getElementById(id);
            if (!list) return;
            const seen = new Set();
            list.innerHTML = (values || []).map(v => {
                const text = String(v ?? '').trim();
                const key = text.toLowerCase();
                if (!text || seen.has(key)) return '';
                seen.add(key);
                return `<option value="${text.replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}"></option>`;
            }).join('');
        };
        fillDsrDatalist('dsr-pol-list', visiblePol);
        fillDsrDatalist('dsr-pod-list', visiblePod);
        fillDsrDatalist('dsr-liner-list', visibleCarriers);
        refreshJobReferenceDropdowns();
        refreshDsrQuoteReferenceDropdown();
        if (s.quoteRef || s.quoteNumber || s.rateQuoteRef) { onDsrQuoteRefChange(true); }
        else if (s.jobNo || s.code) { onDsrJobReferenceChange(true); }

        // Existing/manual POL, POD and Shipping Line values are already preserved by the editable inputs.

        renderDsrCharges(mode, s);
        if (mode === 'SEA') {
            renderDsrContainerRows(Array.isArray(s.containers) && s.containers.length ? s.containers : (s.containerNo ? [{containerNo:s.containerNo,type:s.containerType||''}] : [{containerNo:'',type:''}]));
            applyDsrCutoffDefaults(false);
        }
    }, 100);
}

// ===== DSR MODE SWITCH & CHARGES RENDER =====
function renderDsrCharges(mode, s = {}) {
    const area = document.getElementById('dsr-charges-area');
    if (!area) return;

    // For both SEA and AIR: show a simple placeholder
    area.innerHTML = `
        <div style="background: #f1f5f9; padding: 12px; border-radius: 6px; margin-top: 10px; text-align: center; color: #64748b;">
            <span style="font-weight: 600;">📦 No local charges – they are now managed in the Rate Sheet.</span>
        </div>
    `;
}

// ===== DSR QUOTE REF LOOKUP / AUTO-FILL =====
function getAllRateQuoteRows() {
    const rows = [];
    ['sea','air','lcl'].forEach(mode => {
        (db.rates?.[mode] || []).forEach((q, idx) => rows.push({ mode, idx, source:'rates', data:q }));
        (db.drafts?.[mode] || []).forEach((q, idx) => rows.push({ mode, idx, source:'drafts', data:q }));
    });
    return rows;
}
function normalizeRef(v) { return String(v ?? '').trim().toLowerCase(); }
function findDsrQuoteByRef(ref) {
    const key = normalizeRef(ref);
    if (!key) return null;
    const rows = getAllRateQuoteRows();
    return rows.find(x => [x.data.quoteNumber,x.data.quoteNo,x.data.id,x.data.reference,x.data.jobNo,x.data.shipmentCode,x.data.quoteRef]
        .some(v => normalizeRef(v) === key)) || null;
}
function refreshDsrQuoteReferenceDropdown() {
    const el = document.getElementById('dsr-quote-ref-list');
    if (!el) return;
    const values=[];
    const add=v=>{const x=String(v??'').trim(); if(x && !values.some(y=>y.toLowerCase()===x.toLowerCase())) values.push(x);};
    getAllRateQuoteRows().forEach(x=>{
        add(x.data.quoteNumber); add(x.data.quoteNo); add(x.data.quoteRef); add(x.data.id); add(x.data.reference);
    });
    el.innerHTML=values.sort((a,b)=>a.localeCompare(b,undefined,{numeric:true,sensitivity:'base'}))
        .map(v=>`<option value="${escapeHtml(v)}">`).join('');
}
function applyDsrQuoteData(q, mode, options={}) {
    if (!q) return false;
    const set=(id,value,force=false)=>{
        const el=document.getElementById(id); if(!el || value===undefined || value===null || String(value).trim()==='') return;
        if(force || !String(el.value||'').trim()) el.value=String(value);
    };
    const ref=q.quoteNumber || q.quoteNo || q.quoteRef || q.id || q.reference || '';
    const job=q.jobNo || q.shipmentCode || q.shipmentCodeNo || '';
    set('dsr-quote-ref',ref,options.force);
    if (job) set('dsr-job-no',job,options.force);
    set('dsr-shipper',q.client || q.customer || q.shipper || '',options.force);
    set('dsr-pol',q.pol || '',options.force);
    set('dsr-pod',q.pod || '',options.force);
    set('dsr-liner',q.carrier || q.shippingLine || q.liner || '',options.force);
    set('dsr-etd',q.etd || q.etdDate || '',options.force);
    set('dsr-eta',q.eta || q.etaDate || '',options.force);
    set('dsr-booking-no',q.bookingNo || q.jobBkg || q.booking || '',options.force);
    // Preserve current mode unless the quote mode is explicit and the form is new.
    const modeEl=document.getElementById('dsr-mode');
    if(modeEl && mode && !options.keepMode) modeEl.value=String(mode).toUpperCase();
    // Select values case-insensitively after quote data is applied.
    ['dsr-pol','dsr-pod','dsr-liner'].forEach(id=>{
        const el=document.getElementById(id); if(!el || !el.value) return;
        const m=Array.from(el.options).find(o=>normalizeRef(o.value)===normalizeRef(el.value));
        if(m) el.value=m.value;
    });
    return true;
}
function onDsrQuoteRefChange(silent=false) {
    const ref=String(document.getElementById('dsr-quote-ref')?.value||'').trim();
    if(!ref) return false;
    const found=findDsrQuoteByRef(ref);
    if(!found) { if(!silent) console.warn('DSR Quote Ref not found:',ref); return false; }
    return applyDsrQuoteData(found.data,found.mode,{force:false,keepMode:false});
}
function onDsrJobReferenceChange(silent=false) {
    const job=String(document.getElementById('dsr-job-no')?.value||'').trim();
    if(!job) return false;

    // A Quote Ref selected from the JOB NO. dropdown must immediately drive
    // the same auto-fetch path as the dedicated QUOTE REF field.
    const quoteMatch=findDsrQuoteByRef(job);
    if (quoteMatch) {
        return applyDsrQuoteData(quoteMatch.data, quoteMatch.mode, {force:false, keepMode:false});
    }

    // Otherwise resolve an existing shipment/JOB NO. as before.
    const shipment=(db.shipments||[]).find(s=>[s.jobNo,s.code,s.shipmentCode,s.quoteRef,s.quoteNumber,s.rateQuoteRef]
        .some(v=>normalizeRef(v)===normalizeRef(job)));
    if(shipment) {
        const set=(id,value)=>{const el=document.getElementById(id); if(el && value!==undefined && value!==null && String(value).trim() && !String(el.value||'').trim()) el.value=String(value);};
        set('dsr-quote-ref',shipment.quoteRef||shipment.quoteNumber||shipment.rateQuoteRef||'');
        set('dsr-shipper',shipment.shipper||''); set('dsr-booking-no',shipment.bookingNo||shipment.jobBkg||''); set('dsr-pol',shipment.pol||''); set('dsr-pod',shipment.pod||''); set('dsr-liner',shipment.liner||shipment.carrier||'');
        return true;
    }
    if(!silent) console.warn('DSR JOB NO./Quote Ref not found:',job);
    return false;
}

// ===== DSR HELPER FUNCTIONS =====

function calcAirMargin() {
    const sell = parseFloat(document.getElementById('air-sellpk').value) || 0;
    const buy = parseFloat(document.getElementById('air-buy-pk').value) || 0; // ✅ Fixed typo
    document.getElementById('air-margin').value = (sell - buy).toFixed(2);
}

function dsrSearch() {
    closeModal('dsrModal');
    const s = document.getElementById('dsr-search');
    if (s) { s.focus();
        s.select(); }
}

function dsrModify() {
    const code = document.getElementById('dsr-job-no').value.trim() || document.getElementById('dsr-code').value.trim();
    if (!code) return alert('No shipment to modify.');
    const idx = db.shipments.findIndex(s => s.jobNo === code || s.code === code);
    if (idx === -1) return alert('Shipment not found.');
    closeModal('dsrModal');
    openDsrModal(db.shipments[idx].mode, idx);
}

function dsrAddNew() {
    closeModal('dsrModal');
    openDsrModal('SEA');
}

function dsrClear() {
    if (confirm('Clear all fields?')) {
        document.querySelectorAll('#dsrModalBody input, #dsrModalBody select, #dsrModalBody textarea').forEach(el => {
            if (el.tagName === 'SELECT') el.selectedIndex = 0;
            else if (el.type === 'number') el.value = '0';
            else if (el.type === 'date') el.value = '';
            else el.value = '';
        });
        document.getElementById('dsr-code').value = '';
        document.getElementById('dsr-job-no').value = '';
        dsrEditIdx = null;
    }
}

function dsrDuplicate() {
    const code = document.getElementById('dsr-job-no').value.trim() || document.getElementById('dsr-code').value.trim();
    if (!code) return alert('No shipment to duplicate.');
    const idx = db.shipments.findIndex(s => s.jobNo === code || s.code === code);
    if (idx === -1) return alert('Shipment not found.');
    const copy = JSON.parse(JSON.stringify(db.shipments[idx]));
    copy.shipmentId = createDsrShipmentId();
    copy.code = (copy.mode === 'SEA' ? 'SR-' : copy.mode === 'LCL' ? 'LR-' : 'AR-') + Date.now().toString(36).toUpperCase();
    copy.jobNo = copy.code;
    copy.createdAt = new Date().toISOString();
    copy.lastModified = new Date().toISOString();
    db.shipments.push(copy);
    saveDB();
    closeModal('dsrModal');
    renderShipments();
    alert('Shipment duplicated! New JOB NO: ' + copy.code);
    autoBackup();
}

async function dsrPersistAfterDelete() {
    // Deletion must be persisted before the next automatic backup cycle. The
    // existing backup/sync engine remains untouched; we only use its existing
    // busy flag as a cooperative lock and write the CURRENT database directly
    // to the configured SQLite backup.
    const waitStart = Date.now();
    while (window.__shahidBackupBusy) {
        if (Date.now() - waitStart > 30000) {
            throw new Error('Backup operation is busy. Please try deleting again.');
        }
        await new Promise(resolve => setTimeout(resolve, 100));
    }

    window.__shahidBackupBusy = true;
    try {
        if (saveDB() !== true) return false;

        const backupFormat = String(db?.backupFormat || '').toLowerCase();
        const folderPath = String(db?.backupFolderPath || '').trim();

        // Electron/EXE: write the live database directly to SHAHID_ERP.sqlite.
        // This deliberately avoids importing/merging the older backup file.
        if (
            backupFormat === 'sqlite' &&
            folderPath &&
            window.electronAPI &&
            typeof window.electronAPI.writeBackupFile === 'function' &&
            typeof buildCompleteSQLiteDatabase === 'function'
        ) {
            const sqliteDb = await buildCompleteSQLiteDatabase();
            let bytes;
            try {
                bytes = sqliteDb.export();
            } finally {
                sqliteDb.close();
            }

            const result = await window.electronAPI.writeBackupFile(
                folderPath,
                'SHAHID_ERP.sqlite',
                bytes
            );

            if (!result || result.success !== true) {
                throw new Error(result?.error || 'SQLite backup could not be updated after deletion.');
            }

            db.lastBackup = new Date().toISOString();
            if (saveDB() !== true) return false;
            return true;
        }

        // Browser/File System Access: write the current database directly to
        // the selected folder, without reading or merging an older backup.
        const folderHandle = window.backupFolderHandle ||
            (typeof backupFolderHandle !== 'undefined' ? backupFolderHandle : null);

        if (
            backupFormat === 'sqlite' &&
            folderHandle &&
            typeof buildCompleteSQLiteDatabase === 'function'
        ) {
            const sqliteDb = await buildCompleteSQLiteDatabase();
            let bytes;
            try {
                bytes = sqliteDb.export();
            } finally {
                sqliteDb.close();
            }

            const fileHandle = await folderHandle.getFileHandle(
                'SHAHID_ERP.sqlite',
                { create: true }
            );
            const writable = await fileHandle.createWritable({ keepExistingData: false });
            try {
                await writable.write(new Blob([bytes], { type: 'application/x-sqlite3' }));
            } finally {
                await writable.close();
            }

            db.lastBackup = new Date().toISOString();
            if (saveDB() !== true) return false;
        }

        return true;
    } finally {
        window.__shahidBackupBusy = false;
    }
}

function dsrDelete() {
    const code = document.getElementById('dsr-job-no').value.trim() || document.getElementById('dsr-code').value.trim();
    if (!code) return alert('No shipment to delete.');
    const idx = db.shipments.findIndex(s => s.jobNo === code || s.code === code);
    if (idx === -1) return alert('Shipment not found.');
    if (confirm(`Delete shipment "${code}"?`)) {
        const removed = db.shipments.splice(idx, 1)[0];
        Promise.resolve(dsrPersistAfterDelete()).then(ok => {
            if (!ok) {
                db.shipments.splice(idx, 0, removed);
                return alert('Unable to delete shipment because the database could not be saved.');
            }
            if (dsrSelectedIdx === idx) dsrSelectedIdx = -1;
            else if (dsrSelectedIdx > idx) dsrSelectedIdx--;
            window.dsrSelectedIdx = dsrSelectedIdx;
            closeModal('dsrModal');
            renderShipments();
            alert('Shipment deleted.');
        }).catch(e => {
            db.shipments.splice(idx, 0, removed);
            console.error('DSR delete failed:', e);
            alert('Unable to delete shipment: ' + (e?.message || e));
        });
    }
}

// ===== DSR DASHBOARD SELECTED-ROW ACTION ROUTER =====
// Keeps the existing DSR functions as the single source of truth while
// providing the dashboard action bar with a reliable selected-row bridge.
function dsrRunSelectedAction(action) {
    const idx = Number(dsrSelectedIdx);
    if (!Number.isInteger(idx) || idx < 0 || !db.shipments?.[idx]) {
        return alert('Please select a shipment first.');
    }

    const s = db.shipments[idx];
    const mode = String(s.mode || s.type || 'SEA').toUpperCase();

    try {
        switch (String(action || '').toLowerCase()) {
            case 'preview':
                if (typeof previewDsrShipment === 'function') return previewDsrShipment(idx);
                return openDsrModal(mode, idx);
            case 'edit':
                return editDsrShipment(idx);
            case 'duplicate':
                return duplicateDsrShipment(idx);
            case 'delete':
                return deleteDsrShipment(idx);
            case 'pdf':
                // dsrPDF() reads the currently open DSR form. Open the selected
                // shipment in edit mode first so the existing PDF implementation
                // remains unchanged.
                openDsrModal(mode, idx);
                setTimeout(() => {
                    try { dsrPDF(); }
                    catch (e) { console.error('DSR PDF action failed:', e); alert('Unable to generate PDF: ' + (e?.message || e)); }
                }, 0);
                return;
            default:
                return alert('Unknown DSR action.');
        }
    } catch (e) {
        console.error('DSR selected action failed:', e);
        alert('DSR action could not be completed: ' + (e?.message || e));
    }
}

// Explicit window exports make inline HTML onclick handlers reliable in
// browser/file:// and Electron runtimes.
window.dsrRunSelectedAction = dsrRunSelectedAction;
window.dsrSelectRow = dsrSelectRow;
window.dsrSelectedIdx = dsrSelectedIdx;

function dsrPDF() {
    const code = document.getElementById('dsr-job-no').value.trim() || document.getElementById('dsr-code').value.trim();
    if (!code) return alert('No shipment data to generate PDF.');
    const idx = db.shipments.findIndex(s => s.jobNo === code || s.code === code);
    if (idx === -1) return alert('Shipment not found.');
    const s = db.shipments[idx];
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF({ unit: 'mm', format: 'a4' });
    doc.setFontSize(16);
    doc.text(`${s.mode} SHIPMENT DSR`, 105, 20, { align: 'center' });
    doc.setFontSize(10);
    let y = 35;
    const fields = [
        ['Job No', s.jobNo || s.code],
        ['Shipper', s.shipper],
        ['POL', s.pol],
        ['POD', s.pod],
        ['Shipping Line', s.liner],
        ['ETD', s.etd],
        ['ETA', s.eta],
        ['Cargo Status', s.cargoStatus],
        ['Docs Status', s.docsStatus]
    ];
    fields.forEach(([label, value]) => {
        doc.text(`${label}: ${value || '-'}`, 14, y);
        y += 7;
    });
    doc.save(`${s.mode}_Shipment_${s.code}.pdf`);
}

// Stable technical identity for newly created DSR shipments.
// Existing shipment records are never rewritten by this helper.
function createDsrShipmentId(){
    try {
        if(window.crypto?.randomUUID) return window.crypto.randomUUID();
    } catch(e){}
    return 'SHP-' + Date.now().toString(36).toUpperCase() + '-' + Math.random().toString(36).slice(2,10).toUpperCase();
}

// ===== UNIFIED DSR SAVER =====
function saveDsrShipment(isUpdate) {
    try {
        const mode = String(document.getElementById('dsr-mode')?.value || 'SEA').toUpperCase();
        const jobNo = String(document.getElementById('dsr-job-no')?.value || '').trim();
        if (!jobNo) {
            alert('JOB NO. is required to save a new shipment. Other fields can be completed later.');
            return;
        }

        const val = id => document.getElementById(id)?.value ?? '';
        const rawVal = id => String(val(id)).trim();
        const shipper = rawVal('dsr-shipper');
        const pol = val('dsr-pol');
        const pod = val('dsr-pod');
        const liner = val('dsr-liner');
        const editIndex = Number(dsrEditIdx);
        const old = (isUpdate && Number.isInteger(editIndex) && editIndex >= 0 && db.shipments?.[editIndex])
            ? db.shipments[editIndex]
            : null;
        if (isUpdate && !old) {
            alert('The shipment being edited could not be found. Please close and reopen it from Shipment List.');
            return;
        }
        const seaContainers = mode === 'SEA' ? getDsrContainerRows() : [];

        let code = rawVal('dsr-code');
        if (!code) code = (mode === 'SEA' ? 'SR-' : mode === 'AIR' ? 'AR-' : 'LR-') + Date.now().toString(36).toUpperCase();

        const data = {
            ...(old || {}),
            mode, type: mode,
            exportImport: val('dsr-direction') || 'EXPORT',
            service1: val('dsr-service-a'),
            service2: val('dsr-service-b'),
            jobNo, code,
            quoteRef: rawVal('dsr-quote-ref'),
            rateQuoteRef: rawVal('dsr-quote-ref'),
            quoteNumber: rawVal('dsr-quote-ref'),
            date: val('dsr-date'),
            shipper: rawVal('dsr-shipper'),
            bookingNo: rawVal('dsr-booking-no'),
            jobBkg: rawVal('dsr-booking-no'),
            pol: val('dsr-pol'),
            pod: val('dsr-pod'),
            liner: val('dsr-liner'),
            etd: val('dsr-etd'),
            shippingBillNo: rawVal('dsr-shipping-bill-no'),
            shippingBillDate: val('dsr-shipping-bill-date'),
            mblNo: rawVal('dsr-mbl-no'), hblNo: rawVal('dsr-hbl-no'),
            pickupDate: val('dsr-pickup-date'), clearanceDate: val('dsr-clearance-date'),
            docsHandDate: val('dsr-docs-hand-date'), gateinDate: val('dsr-gatein-date'),
            dgdIndexingDate: val('dsr-dgd-indexing-date'), blReleaseDate: val('dsr-bl-release-date'),
            vesselAtd: rawVal('dsr-vessel-atd'), eta: val('dsr-eta'), remarks: rawVal('dsr-remarks'),
            containers: mode === 'SEA' ? (seaContainers.length ? seaContainers : (old?.containers || [])) : [],
            containerNo: mode === 'SEA' ? (seaContainers[0]?.containerNo || old?.containerNo || '') : '',
            containerType: mode === 'SEA' ? (seaContainers[0]?.type || old?.containerType || '') : '',
            gateOpening: mode === 'SEA' ? val('dsr-gate-opening') : (old?.gateOpening || ''),
            gateCutoff: mode === 'SEA' ? val('dsr-gate-cutoff') : (old?.gateCutoff || ''),
            sbCutoff: mode === 'SEA' ? val('dsr-sb-cutoff') : (old?.sbCutoff || ''),
            siCutoff: mode === 'SEA' ? val('dsr-si-cutoff') : (old?.siCutoff || ''),
            cargoStatus: val('dsr-cargo-status') || 'Booked',
            docsStatus: val('dsr-docs-status') || 'Pending',
            sales: old?.sales || getLoggedInUserName() || db.defaultUser || '',
            lastModified: new Date().toISOString(),
            shipmentId: old?.shipmentId || createDsrShipmentId(),
            carrierCharges: old?.carrierCharges || {}, otherCharges: old?.otherCharges || {}, quoteCharges: old?.quoteCharges || {},
            sell: old?.sell || 0, buy: old?.buy || 0, sellPK: old?.sellPK || 0, buyPK: old?.buyPK || 0,
            margin: old?.margin || 0, grossWeight: old?.grossWeight || 0, validEtd: old?.validEtd || ''
        };

        const existing = db.shipments.findIndex(s => (s.jobNo === jobNo || s.code === code) && s.mode === mode);
        if (existing !== -1 && (!isUpdate || existing !== dsrEditIdx)) {
            if (!confirm(`Shipment JOB NO. "${jobNo}" already exists. Do you want to overwrite/update it?`)) return;
            db.shipments[existing] = { ...db.shipments[existing], ...data };
            dsrEditIdx = existing;
        } else if (isUpdate && dsrEditIdx !== null && db.shipments[dsrEditIdx]) {
            db.shipments[dsrEditIdx] = { ...db.shipments[dsrEditIdx], ...data };
        } else {
            data.createdAt = new Date().toISOString();
            db.shipments.push(data);
            dsrEditIdx = db.shipments.length - 1;
        }

        if (!saveDB()) throw new Error('Database save failed.');
        syncPlannerAutoTasksForShipment(data);
        closeModal('dsrModal');
        renderShipments();
        refreshPlanner();
        alert(isUpdate ? `${mode} Shipment updated successfully!` : `${mode} Shipment saved successfully!`);
        try { autoBackup(); } catch (backupErr) { console.warn('Auto-backup skipped:', backupErr); }
    } catch (e) {
        console.error('Error in saveDsrShipment:', e);
        alert('Shipment could not be saved: ' + (e?.message || e));
    }
}

// ===== EDIT DSR SHIPMENT (CLICK FROM LIST) =====
function legacy_editDsrShipment(idx) {
    const s = db.shipments[idx];
    if (!s) {
        alert('Shipment not found.');
        return;
    }
    // Use the mode from the shipment data
    const mode = s.mode || s.type || 'SEA';
    openDsrModal(mode, idx);
}

// ===== Shipment List Rendering / DSR Dashboard =====
let dsrDashboardMode = 'ALL';
let dsrSortState = { key: '', dir: 0 };
let dsrDashboardQuickFilter = '';

function applyDsrDashboardFilter(kind, mode = null) {
    const k = String(kind || 'ALL').toUpperCase();
    const targetMode = mode ? String(mode).toUpperCase() : (dsrDashboardMode || 'ALL');
    if (['SEA','LCL','AIR'].includes(targetMode)) dsrDashboardMode = targetMode;
    else if (k === 'ALL') dsrDashboardMode = 'ALL';
    dsrDashboardQuickFilter = k === 'UPCOMING' ? 'UPCOMING' : '';
    const statusEl = document.getElementById('dsr-status-filter');
    if (statusEl) statusEl.value = ['IN TRANSIT','DELIVERED','DELAYED'].includes(k) ? (k === 'IN TRANSIT' ? 'In Transit' : k.charAt(0)+k.slice(1).toLowerCase()) : '';
    const typeEl = document.getElementById('dsr-type-filter');
    if (typeEl) typeEl.value = dsrDashboardMode === 'ALL' ? '' : dsrDashboardMode;
    document.querySelectorAll('.dsr-mode-tab').forEach(btn => btn.classList.toggle('active', String(btn.dataset.mode||'').toUpperCase() === dsrDashboardMode));
    sessionStorage.setItem('dsrDashboardMode', dsrDashboardMode);
    sessionStorage.setItem('dsrDashboardQuickFilter', dsrDashboardQuickFilter);
    sessionStorage.setItem('dsrPage','1');
    renderShipments();
}

function dsrSelectRow(idx, event) {
    if (event && event.target && ['INPUT','BUTTON','SELECT','A'].includes(event.target.tagName)) return;
    const n = Number(idx);
    dsrSelectedIdx = Number.isInteger(n) && n >= 0 && db.shipments?.[n] ? n : -1;
    window.dsrSelectedIdx = dsrSelectedIdx;
    renderShipments();
}

function setDsrDashboardMode(mode){
    dsrDashboardMode = String(mode || 'ALL').toUpperCase();
    dsrDashboardQuickFilter = '';
    document.querySelectorAll('.dsr-mode-tab').forEach(btn => btn.classList.toggle('active', String(btn.dataset.mode||'').toUpperCase() === dsrDashboardMode));
    const typeEl = document.getElementById('dsr-type-filter');
    if(typeEl) typeEl.value = dsrDashboardMode === 'ALL' ? '' : dsrDashboardMode;
    const statusEl = document.getElementById('dsr-status-filter');
    if(statusEl) statusEl.value = '';
    sessionStorage.setItem('dsrDashboardMode', dsrDashboardMode);
    sessionStorage.setItem('dsrDashboardQuickFilter', '');
    sessionStorage.setItem('dsrPage','1');
    renderShipments();
}

function dsrModeOf(s){ return String(s?.mode || s?.type || '').trim().toUpperCase(); }
function dsrBookingOf(s){ return String(s?.bookingNo || s?.jobBkg || s?.booking || '').trim(); }
function dsrJobOf(s){ return String(s?.jobNo || s?.code || s?.shipmentNo || s?.shipmentCode || '').trim(); }
function dsrCarrierOf(s){ return String(s?.liner || s?.carrier || s?.shippingLine || '').trim(); }
function dsrConsigneeOf(s){ return String(s?.consignee || s?.consigneeName || '').trim(); }
function dsrContainerCount(s){ return Array.isArray(s?.containers) ? s.containers.length : (s?.containerNo ? 1 : Number(s?.containerCount||0)); }
function dsrWeightOf(s){ return Number(s?.weight || s?.grossWeight || s?.totalWeight || 0) || 0; }
function dsrCbmOf(s){ return Number(s?.cbm || s?.volume || s?.totalCbm || 0) || 0; }
function dsrDateValue(s, key){
    const v = key === 'etd' ? (s?.etd || s?.etdDate) : key === 'eta' ? (s?.eta || s?.etaDate) : (s?.date || s?.createdAt || s?.lastModified);
    const t = Date.parse(v || ''); return Number.isFinite(t) ? t : 0;
}
function dsrSortValue(s,key){
    switch(key){
        case 'jobNo': return dsrJobOf(s);
        case 'bookingNo': return dsrBookingOf(s);
        case 'mode': return dsrModeOf(s);
        case 'shipper': return String(s?.shipper||'');
        case 'consignee': return dsrConsigneeOf(s);
        case 'pol': return String(s?.pol||'');
        case 'pod': return String(s?.pod||'');
        case 'carrier': return dsrCarrierOf(s);
        case 'status': return String(s?.cargoStatus || s?.status || '');
        case 'etd': return dsrDateValue(s,'etd');
        case 'eta': return dsrDateValue(s,'eta');
        case 'containers': return dsrContainerCount(s);
        case 'weight': return dsrWeightOf(s);
        case 'cbm': return dsrCbmOf(s);
        case 'date': return dsrDateValue(s,'date');
        default: return '';
    }
}
function dsrCompare(a,b,key,dir){
    const av=dsrSortValue(a,key), bv=dsrSortValue(b,key);
    const aBlank=av==='' || av===0, bBlank=bv==='' || bv===0;
    if(aBlank && !bBlank) return 1; if(!aBlank && bBlank) return -1; if(aBlank && bBlank) return 0;
    let cmp;
    if(typeof av==='number' && typeof bv==='number') cmp=av-bv;
    else cmp=String(av).localeCompare(String(bv),undefined,{numeric:true,sensitivity:'base'});
    return cmp * dir;
}
function dsrToggleSort(key){
    if(dsrSortState.key !== key) dsrSortState={key,dir:1};
    else if(dsrSortState.dir===1) dsrSortState.dir=-1;
    else dsrSortState={key:'',dir:0};
    sessionStorage.setItem('dsrSortState',JSON.stringify(dsrSortState));
    sessionStorage.setItem('dsrPage','1');
    renderShipments();
}
function dsrSortIcon(key){
    if(dsrSortState.key!==key) return '↕';
    return dsrSortState.dir===1 ? '▲' : '▼';
}
function dsrSortHeader(label,key){
    return `<button type="button" class="dsr-sort-btn" onclick="dsrToggleSort('${key}')">${escapeHtml(label)} <span class="dsr-sort-indicator">${dsrSortIcon(key)}</span></button>`;
}
function dsrUniqueOptions(list){ return [...new Set(list.map(v=>String(v||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true,sensitivity:'base'})); }
function dsrPopulateFilter(id, values, selected){
    const el=document.getElementById(id); if(!el) return;
    const first=el.options[0]?.outerHTML || '<option value="">All</option>';
    el.innerHTML=first + dsrUniqueOptions(values).map(v=>`<option value="${escapeHtml(v)}">${escapeHtml(v)}</option>`).join('');
    if([...el.options].some(o=>o.value===selected)) el.value=selected; else el.value='';
}
function dsrUpdateFilterOptions(all){
    dsrPopulateFilter('dsr-pol-filter',all.map(s=>s.pol),document.getElementById('dsr-pol-filter')?.value||'');
    dsrPopulateFilter('dsr-pod-filter',all.map(s=>s.pod),document.getElementById('dsr-pod-filter')?.value||'');
    dsrPopulateFilter('dsr-carrier-filter',all.map(dsrCarrierOf),document.getElementById('dsr-carrier-filter')?.value||'');
}
function dsrGetStatus(s){ return String(s?.cargoStatus || s?.status || 'Not Started').trim() || 'Not Started'; }
function dsrKpiCard(label,value,sub,icon,filterKind){
    const kind=String(filterKind||'ALL').toUpperCase();
    return `<button type="button" class="dsr-kpi dsr-kpi-clickable" onclick="applyDsrDashboardFilter('${kind}')" title="Click to filter shipments by ${escapeHtml(label)}"><div class="dsr-kpi-label"><span>${escapeHtml(label)}</span><span>${icon||''}</span></div><div class="dsr-kpi-value">${escapeHtml(String(value))}</div><div class="dsr-kpi-sub">${escapeHtml(sub||'')} <span class="dsr-click-hint">↗</span></div></button>`;
}
function renderDsrKpis(rows, allRows){
    const el=document.getElementById('dsr-kpi-grid'); if(!el) return;
    const total=rows.length, containers=rows.reduce((n,s)=>n+dsrContainerCount(s),0), cbm=rows.reduce((n,s)=>n+dsrCbmOf(s),0);
    const transit=rows.filter(s=>/in transit/i.test(dsrGetStatus(s))).length;
    const delivered=rows.filter(s=>/delivered|closed/i.test(dsrGetStatus(s))).length;
    const delayed=rows.filter(s=>/delay/i.test(dsrGetStatus(s))).length;
    const upcoming=rows.filter(s=>dsrDateValue(s,'eta')>Date.now() || dsrDateValue(s,'etd')>Date.now()).length;
    el.innerHTML=[
      dsrKpiCard('Total Shipments',total,dsrDashboardMode==='ALL'?'All Shipments':dsrDashboardMode+' Freight','📦','ALL'),
      dsrKpiCard('In Transit',transit,total?((transit/total)*100).toFixed(0)+'% of total':'0%','🚚','IN TRANSIT'),
      dsrKpiCard('Arrived',delivered,total?((delivered/total)*100).toFixed(0)+'% of total':'0%','✓','DELIVERED'),
      dsrKpiCard('Delayed',delayed,total?((delayed/total)*100).toFixed(0)+'% of total':'0%','⏱️','DELAYED'),
      dsrKpiCard('Upcoming',upcoming,total?((upcoming/total)*100).toFixed(0)+'% of total':'0%','📅','UPCOMING'),
      dsrKpiCard('Containers',containers,'Shipment containers','📦','ALL'),
      dsrKpiCard('CBM',cbm?cbm.toFixed(2):'0.00','Recorded volume','◫','ALL')
    ].join('');
}
function dsrSafeText(v){ return escapeHtml(String(v==null?'':v)); }
function dsrStatusCounts(rows){
    const counts={transit:0,arrived:0,delayed:0,upcoming:0,other:0};
    rows.forEach(s=>{const st=dsrGetStatus(s); if(/delay/i.test(st)) counts.delayed++; else if(/in transit/i.test(st)) counts.transit++; else if(/delivered|closed|arrived/i.test(st)) counts.arrived++; else if(dsrDateValue(s,'eta')>Date.now() || dsrDateValue(s,'etd')>Date.now()) counts.upcoming++; else counts.other++;});
    return counts;
}
function dsrTopCounts(rows, keyFn){
    const map=new Map(); rows.forEach(s=>{const k=String(keyFn(s)||'').trim(); if(k) map.set(k,(map.get(k)||0)+1);});
    return [...map.entries()].sort((a,b)=>b[1]-a[1] || a[0].localeCompare(b[0],undefined,{sensitivity:'base'})).slice(0,5);
}
function dsrAttentionData(rows){
    const delayed=rows.filter(s=>/delay/i.test(dsrGetStatus(s))).length;
    const etaChanged=rows.filter(s=>s.etaChanged===true || s.etaChanged==='true' || s.etaChange || s.etaUpdated || s.originalEta).length;
    const missingContainer=rows.filter(s=>{const count=dsrContainerCount(s); return !count || !(Array.isArray(s.containers)?s.containers.some(c=>String(c?.containerNo||c?.number||'').trim()):String(s.containerNo||'').trim());}).length;
    const blPending=rows.filter(s=>/pending|draft/i.test(String(s.docsStatus||s.blStatus||s.blDraftStatus||''))).length;
    const costing=rows.filter(s=>/pending|due/i.test(String(s.costingStatus||s.jobCostingStatus||s.costing||''))).length;
    return {delayed,etaChanged,missingContainer,blPending,costing};
}
function renderDsrInsights(allRows, visibleRows){
    const rows=Array.isArray(allRows)?allRows:[];
    const counts=dsrStatusCounts(rows), total=rows.length||1;
    const setText=(id,v)=>{const e=document.getElementById(id); if(e)e.textContent=v;};
    setText('dsr-mode-count-all',`${rows.length} Shipments`);
    setText('dsr-mode-count-sea',`${rows.filter(s=>dsrModeOf(s)==='SEA').length} Shipments`);
    setText('dsr-mode-count-lcl',`${rows.filter(s=>dsrModeOf(s)==='LCL').length} Shipments`);
    setText('dsr-mode-count-air',`${rows.filter(s=>dsrModeOf(s)==='AIR').length} Shipments`);
    const statusEl=document.getElementById('dsr-status-overview');
    if(statusEl){
      const items=[['In Transit',counts.transit,'#2563eb','IN TRANSIT'],['Arrived',counts.arrived,'#10b981','DELIVERED'],['Delayed',counts.delayed,'#ef4444','DELAYED'],['Upcoming',counts.upcoming,'#94a3b8','UPCOMING']];
      statusEl.innerHTML=`<div class="dsr-donut" style="--p1:${(counts.transit/total)*100}%;--p2:${((counts.transit+counts.arrived)/total)*100}%;--p3:${((counts.transit+counts.arrived+counts.delayed)/total)*100}%"><div>${rows.length}<small>Total</small></div></div><div class="dsr-status-legend">${items.map(([l,v,c,k])=>`<button type="button" class="dsr-legend-row" onclick="applyDsrDashboardFilter('${k}')"><i style="background:${c}"></i><span>${l}</span><strong>${v}</strong></button>`).join('')}</div></div>`;
    }
    const modeEl=document.getElementById('dsr-mode-wise-summary');
    if(modeEl){
      const modes=[['SEA','🚢 Sea Freight','#2563eb'],['LCL','📦 LCL Freight','#f59e0b'],['AIR','✈️ Air Freight','#8b5cf6']];
      modeEl.innerHTML=modes.map(([m,label,c])=>{const n=rows.filter(s=>dsrModeOf(s)===m).length; const pct=Math.round((n/total)*100); return `<button type="button" class="dsr-bar-row" onclick="applyDsrDashboardFilter('ALL','${m}')"><span>${label}</span><div class="dsr-bar-track"><b style="width:${pct}%;background:${c}"></b></div><strong>${n}</strong></button>`;}).join('');
    }
    const keyEl=document.getElementById('dsr-key-stats');
    if(keyEl){const containers=rows.reduce((n,s)=>n+dsrContainerCount(s),0),cbm=rows.reduce((n,s)=>n+dsrCbmOf(s),0),upcoming=counts.upcoming; keyEl.innerHTML=[['Total',rows.length,'📊'],['In Transit',counts.transit,'🚚'],['Arrived',counts.arrived,'✓'],['Delayed',counts.delayed,'⏱️'],['Containers',containers,'📦'],['CBM',cbm?cbm.toFixed(2):'0.00','◫']].map(x=>`<div class="dsr-stat-tile"><span>${x[2]}</span><small>${x[0]}</small><strong>${x[1]}</strong></div>`).join('');}
    const routeEl=document.getElementById('dsr-top-routes');
    if(routeEl){const routes=dsrTopCounts(rows,s=>`${s.pol||'-'} → ${s.pod||'-'}`),max=routes[0]?.[1]||1; routeEl.innerHTML=routes.length?routes.map(([k,v])=>`<button type="button" class="dsr-ranking-row" onclick="document.getElementById('dsr-search').value='${String(k).replace(/'/g,"\\'")}';renderShipments()"><span>${dsrSafeText(k)}</span><b>${v}</b><i><em style="width:${Math.round(v/max*100)}%"></em></i></button>`).join(''):'<div class="dsr-empty-insight">No route data</div>';}
    const carrierEl=document.getElementById('dsr-top-carriers');
    if(carrierEl){const carriers=dsrTopCounts(rows,dsrCarrierOf),max=carriers[0]?.[1]||1; carrierEl.innerHTML=carriers.length?carriers.map(([k,v])=>`<button type="button" class="dsr-ranking-row" onclick="document.getElementById('dsr-carrier-filter').value='${String(k).replace(/'/g,"\\'")}';renderShipments()"><span>${dsrSafeText(k)}</span><b>${v}</b><i><em style="width:${Math.round(v/max*100)}%"></em></i></button>`).join(''):'<div class="dsr-empty-insight">No carrier data</div>';}
    const att=dsrAttentionData(rows), attEl=document.getElementById('dsr-attention-panel');
    if(attEl){const cards=[['delayed','⏱️','Delayed Shipments',att.delayed,'DELAYED'],['etaChanged','⚠️','ETA Changed',att.etaChanged,'ALL'],['missingContainer','📦','Missing Container Details',att.missingContainer,'ALL'],['blPending','📄','BL Draft Pending',att.blPending,'ALL'],['costing','₹','Pending Costing',att.costing,'ALL']]; attEl.innerHTML=`<div class="dsr-attention-head"><strong>⚠️ ATTENTION REQUIRED</strong><span>Operational items requiring review</span></div><div class="dsr-attention-grid">${cards.map(([id,icon,label,val,filter])=>`<button type="button" class="dsr-attention-card ${val?'has-alert':''}" onclick="applyDsrDashboardFilter('${filter}')"><span>${icon}</span><strong>${val}</strong><small>${label}</small></button>`).join('')}</div>`;}
}
function dsrSummaryCard(mode,rows){
    const total=rows.length, transit=rows.filter(s=>/in transit/i.test(dsrGetStatus(s))).length, delivered=rows.filter(s=>/delivered|closed/i.test(dsrGetStatus(s))).length, delayed=rows.filter(s=>/delay/i.test(dsrGetStatus(s))).length;
    const upcoming=rows.filter(s=>dsrDateValue(s,'eta')>Date.now() || dsrDateValue(s,'etd')>Date.now()).length;
    const stats=[['Total',total],['In Transit',transit],['ARRIVED',delivered],['Delayed',delayed],['Upcoming',upcoming]];
    const title=mode==='SEA'?'🚢 SEA FREIGHT SUMMARY':mode==='LCL'?'📦 LCL FREIGHT SUMMARY':'✈️ AIR FREIGHT SUMMARY';
    return `<div class="dsr-summary-card"><div class="dsr-summary-title">${title}</div><div class="dsr-summary-stats">${stats.map(x=>`<div class="dsr-mini-stat"><small>${x[0]}</small><strong>${x[1]}</strong></div>`).join('')}</div></div>`;
}
function renderDsrSummary(allRows){
    const el=document.getElementById('dsr-summary-grid'); if(!el) return;
    const modes=[['SEA','🚢 SEA FREIGHT'],['LCL','📦 LCL FREIGHT'],['AIR','✈️ AIR FREIGHT']];
    el.innerHTML=`<div class="dsr-summary-rows">${modes.map(([mode,title])=>{
        const rows=allRows.filter(s=>dsrModeOf(s)===mode);
        const total=rows.length;
        const transit=rows.filter(s=>/in transit/i.test(dsrGetStatus(s))).length;
        const delivered=rows.filter(s=>/delivered|closed/i.test(dsrGetStatus(s))).length;
        const delayed=rows.filter(s=>/delay/i.test(dsrGetStatus(s))).length;
        const upcoming=rows.filter(s=>dsrDateValue(s,'eta')>Date.now() || dsrDateValue(s,'etd')>Date.now()).length;
        const stats=[['Total',total,'ALL'],['In Transit',transit,'IN TRANSIT'],['ARRIVED',delivered,'DELIVERED'],['Delayed',delayed,'DELAYED'],['Upcoming',upcoming,'UPCOMING']];
        return `<div class="dsr-summary-row"><button type="button" class="dsr-summary-row-title dsr-summary-clickable" onclick="applyDsrDashboardFilter('ALL','${mode}')" title="Show ${mode} shipments">${title}<span class="dsr-click-hint">↗</span></button><div class="dsr-summary-row-stats">${stats.map(([label,value,kind])=>`<button type="button" class="dsr-mini-stat dsr-summary-stat-clickable" onclick="applyDsrDashboardFilter('${kind}','${mode}')" title="Filter ${mode} - ${label}"><small>${label}</small><strong>${value}</strong></button>`).join('')}</div></div>`;
    }).join('')}</div>`;
    const u=document.getElementById('dsr-last-updated'); if(u) u.textContent='Last Updated: '+new Date().toLocaleString();
}

function renderShipments() {
    const search = (document.getElementById('dsr-search')?.value || '').trim().toLowerCase();
    const typeFilter = document.getElementById('dsr-type-filter')?.value || '';
    const statusFilter = document.getElementById('dsr-status-filter')?.value || '';
    const polFilter = document.getElementById('dsr-pol-filter')?.value || '';
    const podFilter = document.getElementById('dsr-pod-filter')?.value || '';
    const carrierFilter = document.getElementById('dsr-carrier-filter')?.value || '';
    const perPage = parseInt(document.getElementById('dsr-per-page')?.value) || 25;
    const list = document.getElementById('dsr-list'); const pagination = document.getElementById('dsr-pagination'); if(!list) return;
    let allRows = Array.isArray(db.shipments) ? db.shipments.slice() : [];
    dsrUpdateFilterOptions(allRows);
    if(!dsrDashboardMode) dsrDashboardMode=String(sessionStorage.getItem('dsrDashboardMode')||'ALL').toUpperCase();
    if(!dsrDashboardQuickFilter) dsrDashboardQuickFilter=String(sessionStorage.getItem('dsrDashboardQuickFilter')||'');
    let shipments = allRows.filter(s => {
        const mode=dsrModeOf(s), status=dsrGetStatus(s), carrier=dsrCarrierOf(s);
        const containers=Array.isArray(s.containers)?s.containers.map(c=>c?.containerNo||c?.number||'').join(' '):String(s.containerNo||'');
        const text = `${dsrJobOf(s)} ${dsrBookingOf(s)} ${s.quoteRef||''} ${s.quoteNumber||''} ${s.shipper||''} ${dsrConsigneeOf(s)} ${s.pol||''} ${s.pod||''} ${carrier} ${mode} ${status} ${containers}`.toLowerCase();
        if(search && !text.includes(search)) return false;
        if(dsrDashboardMode!=='ALL' && mode!==dsrDashboardMode) return false;
        if(typeFilter && mode!==String(typeFilter).toUpperCase()) return false;
        if(statusFilter && status!==statusFilter) return false;
        if(dsrDashboardQuickFilter==='UPCOMING' && !(dsrDateValue(s,'eta')>Date.now() || dsrDateValue(s,'etd')>Date.now())) return false;
        if(polFilter && String(s.pol||'')!==polFilter) return false;
        if(podFilter && String(s.pod||'')!==podFilter) return false;
        if(carrierFilter && carrier!==carrierFilter) return false;
        return true;
    });
    renderDsrKpis(shipments,allRows); renderDsrSummary(allRows); renderDsrInsights(allRows,shipments);
    if(dsrSortState.key && dsrSortState.dir) shipments.sort((a,b)=>dsrCompare(a,b,dsrSortState.key,dsrSortState.dir));
    else shipments.sort((a,b)=>dsrDateValue(b,'date')-dsrDateValue(a,'date'));
    const total=shipments.length, perPageVal=perPage===0?total:perPage, totalPages=perPageVal>0?Math.ceil(total/perPageVal):1;
    let page=parseInt(sessionStorage.getItem('dsrPage')||'1'); if(page<1) page=1; if(page>totalPages) page=totalPages; if(!Number.isFinite(page)||page<1) page=1; sessionStorage.setItem('dsrPage',String(page));
    const start=(page-1)*perPageVal, pageData=shipments.slice(start,start+perPageVal);
    if(total===0){ list.innerHTML='<div style="padding:28px;text-align:center;color:var(--text-light);">No shipments found for the selected filters.</div>'; pagination.innerHTML=''; return; }
    list.innerHTML=`<div class="dsr-section-header sea-header">${dsrDashboardMode==='ALL'?'🚢 ✈️ 📦 ALL SHIPMENTS':dsrDashboardMode==='SEA'?'🚢 SEA FREIGHT':dsrDashboardMode==='LCL'?'📦 LCL FREIGHT':'✈️ AIR FREIGHT'} <span class="badge">${total}</span><span style="margin-left:auto;font-size:.72rem;opacity:.8;">Click any column heading for A→Z / Z→A</span></div>${buildShipmentTable(pageData)}`;
    if(totalPages<=1) pagination.innerHTML=''; else pagination.innerHTML=`<button class="page-btn" onclick="changeDsrPage(${page-1})" ${page===1?'disabled':''}>‹ Prev</button><span class="page-info">Page ${page} of ${totalPages} (${total} records)</span><button class="page-btn" onclick="changeDsrPage(${page+1})" ${page===totalPages?'disabled':''}>Next ›</button>`;
    const sel=document.getElementById('dsr-selected-label'); if(sel) sel.textContent=dsrSelectedIdx>=0&&db.shipments[dsrSelectedIdx] ? `Selected: ${dsrJobOf(db.shipments[dsrSelectedIdx])}` : 'No shipment selected';
}
function changeDsrPage(page) {
    const perPage=parseInt(document.getElementById('dsr-per-page')?.value)||25, total=(db.shipments||[]).length, perPageVal=perPage===0?total:perPage, totalPages=perPageVal>0?Math.ceil(total/perPageVal):1;
    if(page<1||page>totalPages)return; sessionStorage.setItem('dsrPage',String(page)); renderShipments();
}
function buildShipmentTable(data) {
    const colMap={'code':{label:'JOB NO.',key:'jobNo'},'mode':{label:'MODE',key:'mode'},'bookingNo':{label:'BOOKING NO.',key:'bookingNo'},'shipper':{label:'SHIPPER',key:'shipper'},'pol':{label:'POL (ETD)',key:'pol'},'pod':{label:'POD (ETA)',key:'pod'},'liner':{label:'CARRIER',key:'carrier'},'cargoStatus':{label:'STATUS',key:'status'},'docsStatus':{label:'DOCS STATUS',key:'docsStatus'}};
    let headerHtml='<tr><th style="width:34px;text-align:center;"><input type="checkbox" title="Select all on this page" onchange="dsrTogglePageSelection(this.checked)"></th><th>SR No.</th>';
    dsrColumns.forEach(col=>{if(col!=='actions'&&colMap[col]) headerHtml+=`<th>${dsrSortHeader(colMap[col].label,colMap[col].key)}</th>`;});
    if(!dsrColumns.includes('mode')) headerHtml+=`<th>${dsrSortHeader('MODE','mode')}</th>`;
    if(!dsrColumns.includes('bookingNo')) headerHtml+=`<th>${dsrSortHeader('BOOKING NO.','bookingNo')}</th>`;
    headerHtml+='<th>ACTION</th></tr>';
    let html=`<table class="dsr-table"><thead>${headerHtml}</thead><tbody>`;
    data.forEach((s,idx)=>{
        const realIdx=db.shipments.indexOf(s), isSelected=dsrSelectedIdx===realIdx, mode=dsrModeOf(s)||'-', booking=dsrBookingOf(s), status=dsrGetStatus(s), etd=s.etd||s.etdDate||'-', eta=s.eta||s.etaDate||'-', containers=dsrContainerCount(s), weight=dsrWeightOf(s), cbm=dsrCbmOf(s);
        html+=`<tr class="${isSelected?'dsr-row-selected':''}" onclick="dsrSelectRow(${realIdx}, event)"><td style="text-align:center;"><input type="checkbox" class="dsr-row-check" data-idx="${realIdx}" ${isSelected?'checked':''} onclick="event.stopPropagation();dsrSelectRow(${realIdx},event)"></td><td>${idx+1}</td>`;
        dsrColumns.forEach(col=>{if(col==='actions')return; let val=s[col]||'-'; if(col==='code') html+=`<td><a href="javascript:void(0)" onclick="event.stopPropagation();editDsrShipment(${realIdx})" style="color:var(--primary);font-weight:700;text-decoration:underline;cursor:pointer;">${escapeHtml(dsrJobOf(s)||'-')}</a></td>`; else if(col==='bookingNo') html+=`<td>${escapeHtml(booking||'-')}</td>`; else if(col==='mode') html+=`<td><span class="status-badge ${mode==='AIR'?'status-expiring':mode==='LCL'?'status-active':'status-active'}">${escapeHtml(mode)}</span></td>`; else if(col==='cargoStatus') html+=`<td><span class="status-badge ${/delivered|closed/i.test(status)?'status-active':/transit/i.test(status)?'status-expiring':/delay|cancel/i.test(status)?'status-expired':'status-active'}">${escapeHtml(status)}</span></td>`; else if(col==='docsStatus') html+=`<td>${escapeHtml(s.docsStatus||'-')}</td>`; else html+=`<td>${escapeHtml(String(val))}</td>`;});
        if(!dsrColumns.includes('mode')) html+=`<td><span class="status-badge ${mode==='AIR'?'status-expiring':'status-active'}">${escapeHtml(mode)}</span></td>`;
        if(!dsrColumns.includes('bookingNo')) html+=`<td>${escapeHtml(booking||'-')}</td>`;
        html+=`<td><div style="display:flex;gap:4px;justify-content:center;"><button type="button" class="btn btn-sm btn-preview" title="Preview" onclick="event.stopPropagation();previewDsrShipment(${realIdx})">👁</button><button type="button" class="btn btn-sm btn-preview" title="Edit" onclick="event.stopPropagation();editDsrShipment(${realIdx})">✏️</button></div></td></tr>`;
    });
    return html+'</tbody></table>';
}

function openDsrByCode(code) {
    const idx = db.shipments.findIndex(s => s.jobNo === code || s.code === code);
    if (idx === -1) {
        alert('Shipment not found.');
        return;
    }
    editDsrShipment(idx);
}
function legacy_editDsrShipment2(idx) {
    const s = db.shipments[idx];
    if (!s) return alert('Shipment not found.');
    if (s.type === 'SEA') {
        openSeaDsrModal(idx);
    } else if (s.type === 'AIR') {
        openAirDsrModal(idx);
    } else {
        openShipmentModal(idx);
    }
}


function duplicateDsrShipment(idx) {
    const s = db.shipments[idx];
    if (!s) return alert('Shipment not found.');
    const copy = JSON.parse(JSON.stringify(s));
    const prefix = s.type === 'SEA' ? 'SR-' : s.type === 'AIR' ? 'AR-' : 'LR-';
    copy.shipmentId = createDsrShipmentId();
    copy.code = prefix + Date.now().toString(36).toUpperCase();
    copy.createdAt = new Date().toISOString();
    copy.lastModified = new Date().toISOString();
    db.shipments.push(copy);
    saveDB();
    renderShipments();
    alert(`${s.type} Shipment duplicated! New code: ${copy.code}`);
    autoBackup();
}
function deleteDsrShipment(idx) {
    const s = db.shipments[idx];
    if (!s) return alert('Shipment not found.');
    const shipmentLabel = s.type || s.mode || 'Shipment';
    const shipmentCode = s.code || s.jobNo || s.shipmentNo || s.bookingNo || 'selected';
    if (confirm(`Delete ${shipmentLabel} "${shipmentCode}"?`)) {
        const removed = db.shipments.splice(idx, 1)[0];
        Promise.resolve(dsrPersistAfterDelete()).then(ok => {
            if (!ok) {
                db.shipments.splice(idx, 0, removed);
                return alert('Unable to delete shipment because the database could not be saved.');
            }
            if (dsrSelectedIdx === idx) dsrSelectedIdx = -1;
            else if (dsrSelectedIdx > idx) dsrSelectedIdx--;
            window.dsrSelectedIdx = dsrSelectedIdx;
            renderShipments();
            alert('Shipment deleted.');
        }).catch(e => {
            db.shipments.splice(idx, 0, removed);
            console.error('DSR delete failed:', e);
            alert('Unable to delete shipment: ' + (e?.message || e));
        });
    }
}
function clearDSRFilters() {
    ['dsr-search','dsr-type-filter','dsr-status-filter','dsr-pol-filter','dsr-pod-filter','dsr-carrier-filter'].forEach(id=>{ const el=document.getElementById(id); if(el) el.value=''; });
    const pp=document.getElementById('dsr-per-page'); if(pp) pp.value='25';
    dsrDashboardMode='ALL'; dsrDashboardQuickFilter=''; dsrSortState={key:'',dir:0}; dsrSelectedIdx=-1; window.dsrSelectedIdx=dsrSelectedIdx;
    document.querySelectorAll('.dsr-mode-tab').forEach(btn=>btn.classList.toggle('active',String(btn.dataset.mode||'')==='ALL'));
    sessionStorage.setItem('dsrDashboardMode','ALL'); sessionStorage.setItem('dsrDashboardQuickFilter',''); sessionStorage.setItem('dsrSortState',JSON.stringify(dsrSortState)); sessionStorage.setItem('dsrPage','1');
    renderShipments();
}
// ===== CORRECTED addShipmentFromQuote =====
function addShipmentFromQuote(target, mode, idx, noModal = false) {
    const quote = db[target][mode][idx];
    if (!quote) return alert('Quote not found.');

    const freightKey = mode === 'air' ? 'AIR FREIGHT' : 'FREIGHT';
    let rawSellAmt = 0, rawSellCur = 'INR', rawBuyAmt = 0, rawBuyCur = 'INR';

    // Extract freight amounts
    if (quote.charges && quote.charges[freightKey]) {
        const f = quote.charges[freightKey];
        rawSellAmt = parseFloat(f.amount) || 0;
        rawSellCur = f.currency || 'INR';
        rawBuyAmt = parseFloat(f.buyAmount) || rawSellAmt;
        rawBuyCur = f.buyCurrency || rawSellCur || 'INR';
    }

    // Base shipment object
    const baseShipment = {
        exportImport: 'EXPORT',
        mode: mode.toUpperCase(),
        service1: 'SELF SEAL',
        service2: 'CLEAN ONLY',
        jobNo: quote.jobNo || quote.quoteNumber || 'JOB-' + Date.now().toString(36).toUpperCase(),
        quoteRef: quote.quoteNumber || quote.quoteNo || quote.id || quote.reference || '',
        rateQuoteRef: quote.quoteNumber || quote.quoteNo || quote.id || quote.reference || '',
        quoteNumber: quote.quoteNumber || quote.quoteNo || '',
        date: new Date().toISOString().split('T')[0],
        shipper: quote.client || '',
        packages: '',
        pol: quote.pol || '',
        pod: quote.pod || '',
        liner: quote.carrier || '',
        etd: '',
        shippingBillNo: '',
        shippingBillDate: '',
        mblNo: '',
        hblNo: '',
        pickupDate: '',
        clearanceDate: '',
        docsHandDate: '',
        gateinDate: '',
        dgdIndexingDate: '',
        blReleaseDate: '',
        vesselAtd: '',
        eta: '',
        remarks: quote.remarks || '',
        code: quote.quoteNumber || 'SR-' + Date.now().toString(36).toUpperCase(),
        shipmentId: createDsrShipmentId(),
        cargoStatus: (db.cargoStatusMaster && db.cargoStatusMaster[0]) || 'Booked',
        docsStatus: (db.docsStatusMaster && db.docsStatusMaster[0]) || 'Pending',
        sales: getLoggedInUserName() || db.defaultUser || '',
        weight: quote.weight || 0,
        carrierCharges: null,
        otherCharges: null,
        quoteCharges: null,
        sell: 0,
        buy: 0,
        containerNo: '',
        sellPK: 0,
        buyPK: 0,
        grossWeight: 0,
        validEtd: ''
    };

    // Mode-specific filling
    if (mode === 'sea') {
        let sellAmtUSD = rawSellAmt;
        let buyAmtUSD = rawBuyAmt;
        if (rawSellCur !== 'USD') {
            const inrValue = toINR(sellAmtUSD, rawSellCur);
            const usdRate = Number(db.exchangeRates?.USD);
            sellAmtUSD = usdRate > 0 ? inrValue / usdRate : 0;
        }
        if (rawBuyCur !== 'USD') {
            const inrValue = toINR(buyAmtUSD, rawBuyCur);
            const usdRate = Number(db.exchangeRates?.USD);
            buyAmtUSD = usdRate > 0 ? inrValue / usdRate : 0;
        }
        const s = {
            ...baseShipment,
            type: 'SEA',
            sell: sellAmtUSD,
            buy: buyAmtUSD,
            containerNo: quote.container || '',
            packages: quote.container || '',
            carrierCharges: {
                THC: 0, SEAWAY: 0, SEAL: 0, ETS: 0, MUC: 0,
                HAZDOCS: 0, DOCS: 0, AMS: 0,
                GRWEIGHT: parseFloat(quote.weight) || 0
            },
            otherCharges: {
                CFS: 0, CLEARANCE: 0, VGM: 0, TOLL: 0,
                LASCHO: 0, HAZSTICKER: 0, TRANSPORTATION: 0,
                LOLO: 0, OTHERLOCAL: 0, ONWHEEL: 0, OTHERLOCAL3: 0
            }
        };
        const carrierMap = {
            'THC': 'THC', 'SEAL': 'SEAL', 'MUC': 'MUC', 'DOCS': 'DOCS',
            'SEAWAY BL': 'SEAWAY', 'SEAWAY': 'SEAWAY',
            'ETS': 'ETS', 'HAZ DOCS': 'HAZDOCS', 'AMS': 'AMS'
        };
        const otherMap = {
            'CFS': 'CFS', 'CLEARANCE': 'CLEARANCE', 'VGM': 'VGM', 'TOLL': 'TOLL',
            'LASHING & CHOKING': 'LASCHO', 'HAZ STICKER': 'HAZSTICKER',
            'ON WHEEL': 'ON WHEEL', 'TRANSPORTATION': 'TRANSPORTATION',
            'LOLO': 'LOLO', 'OTHER LOCALS': 'OTHERLOCAL'
        };
        const charges = quote.charges || {};
        Object.entries(carrierMap).forEach(([key, val]) => {
            if (charges[key]) s.carrierCharges[val] = parseFloat(charges[key].amount) || 0;
        });
        Object.entries(otherMap).forEach(([key, val]) => {
            if (charges[key]) s.otherCharges[val] = parseFloat(charges[key].amount) || 0;
        });
        db.shipments.push(s);
        saveDB();
        if (target === 'rates') {
            quote.convertedToShipment = true;
            saveDB();
        }
        if (!noModal) {
            openDsrModal('SEA', null, s);
        }
    }
    else if (mode === 'air') {
        const rawSellPK = rawSellAmt;
        const rawBuyPK = rawBuyAmt;
        const s = {
            ...baseShipment,
            type: 'AIR',
            sellPK: rawSellPK,
            buyPK: rawBuyPK,
            grossWeight: parseFloat(quote.weight) || 0,
            validEtd: quote.validityDate || '',
            packages: quote.pallets ? String(quote.pallets) : '',
            quoteCharges: {
                CARTAGE: 0, MCC: 0, XRAY: 0, GATEPASS: 0, ASI: 0, AMS: 0, PALLET: 0,
                LOADING_UNLOADING: 0, DGFEE: 0, DGAGENT: 0, PLY: 0, REPACKING: 0, AWB: 0, TEDI: 0,
                ADD_SURCHARGE: 0, TRANSPORT: 0, CLEARANCE: 0, TERMINAL_TRANSFER: 0
            }
        };
        const airMap = {
            'CARTAGE': 'CARTAGE', 'MCC': 'MCC', 'XRAY': 'XRAY',
            'GATE PASS': 'GATEPASS', 'ASI GMAX': 'ASI', 'AMS': 'AMS',
            'PALLETISATION': 'PALLET', 'LOADING & UNLOADING': 'LOADING_UNLOADING',
            'DG FEES': 'DGFEE', 'DG AGENT FEE': 'DGAGENT',
            'PLY': 'PLY', 'REPACKING': 'REPACKING', 'AWB FEES': 'AWB',
            'TEDI': 'TEDI', 'ADD.SURCHARGE': 'ADD_SURCHARGE', 'TRANSPORATION': 'TRANSPORT',
            'CUSTOM CLEARANCE': 'CLEARANCE', 'TERMINAL TRANSFER': 'TERMINAL_TRANSFER'
        };
        const charges = quote.charges || {};
        Object.entries(airMap).forEach(([key, val]) => {
            if (charges[key]) s.quoteCharges[val] = parseFloat(charges[key].amount) || 0;
        });
        db.shipments.push(s);
        saveDB();
        if (target === 'rates') {
            quote.convertedToShipment = true;
            saveDB();
        }
        if (!noModal) {
            openDsrModal('AIR', null, s);
        }
    }
    else {
        alert('Unsupported mode: ' + mode);
    }
}

// ===== EDIT DSR SHIPMENT (CLICK FROM LIST) =====
function editDsrShipment(idx) {
    const parsedIdx = Number(idx);
    if (!Number.isInteger(parsedIdx) || parsedIdx < 0 || !db.shipments?.[parsedIdx]) {
        alert('Shipment not found.');
        return;
    }

    const s = db.shipments[parsedIdx];
    // Prefer the actual current mode. Older records may only have `type`.
    const resolvedMode = String(s.mode || s.type || 'SEA').toUpperCase();
    const mode = ['SEA', 'AIR', 'LCL'].includes(resolvedMode) ? resolvedMode : 'SEA';

    // No prefill is passed here: openDsrModal loads the exact existing record
    // and marks it as EDIT mode, so UPDATE/DELETE are shown.
    return openDsrModal(mode, parsedIdx);
}

function convertQuoteToShipmentByIndex(target, mode, idx) {
    addShipmentFromQuote(target, mode, idx);
}

// Legacy DSR entry points retained for older action links/templates.
// The unified DSR modal is now the canonical implementation.
window.openSeaDsrModal = window.openSeaDsrModal || function(idx = null, prefill = null) {
    return openDsrModal('SEA', idx, prefill);
};
window.openAirDsrModal = window.openAirDsrModal || function(idx = null, prefill = null) {
    return openDsrModal('AIR', idx, prefill);
};
window.openShipmentModal = window.openShipmentModal || function(idx = null, prefill = null) {
    const mode = String(prefill?.mode || prefill?.type || db.shipments?.[idx]?.mode || db.shipments?.[idx]?.type || 'SEA').toUpperCase();
    return openDsrModal(mode, idx, prefill);
};

// Override renderRecords for enhanced views
const originalRenderRecords = renderRecords;
renderRecords = function(target) {
    if (target === 'rates') {
        renderEnhancedRates();
        return;
    }
    if (target === 'drafts') {
        renderEnhancedDrafts();
        return;
    }
    if (target === 'rrdrafts') {
        renderEnhancedRRDrafts();
        return;
    }
    // Fallback for other targets
    originalRenderRecords(target);
};
// ===== NEW: Claymorphism Shipment Preview HTML =====

const originalSaveDB = saveDB;
saveDB = function() {
    const result = originalSaveDB();
    const dsrPanel = document.getElementById('dsr');
    if (dsrPanel && dsrPanel.classList.contains('active')) {
        setTimeout(renderShipments, 100);
    }
    return result;
};
const originalCloseModal = closeModal;
closeModal = function(id) {
    originalCloseModal(id);
    if (id === 'seaDsrModal' || id === 'airDsrModal') {
        const dsrPanel = document.getElementById('dsr');
        if (dsrPanel && dsrPanel.classList.contains('active')) {
            setTimeout(renderShipments, 200);
        }
    }
};


