// ---------- Helper: Find Quote by Ref ----------
function findQuote(ref) {
    if (!ref) return null;
    const r = String(ref).trim().toUpperCase();
    if (!r) return null;
    for (const m of ['sea', 'air', 'lcl']) {
        const arr = db.rates?.[m] || [];
        const idx = arr.findIndex(x => [x.quoteNumber, x.quoteNo, x.id, x.reference].some(v => String(v || '').trim().toUpperCase() === r));
        if (idx >= 0) return { target: 'rates', mode: m, idx: idx, data: arr[idx] };
    }
    for (const m of ['sea', 'air', 'lcl']) {
        const arr = db.drafts?.[m] || [];
        const idx = arr.findIndex(x => [x.quoteNumber, x.quoteNo, x.id, x.reference].some(v => String(v || '').trim().toUpperCase() === r));
        if (idx >= 0) return { target: 'drafts', mode: m, idx: idx, data: arr[idx] };
    }
    return null;
}

// ---------- Extract charge lines ----------
function quoteChargeLines(q) {
    const charges = q.charges || {};
    const lines = [];
    Object.entries(charges).forEach(([name, c]) => {
        if (!c) return;
        const amount = parseFloat(c.amount) || 0;
        const buy = parseFloat(c.buyAmount) || 0;
        if (amount === 0 && buy === 0) return;
        let qty = 1;
        let basis = String(c.basis || 'Normal');
        const upper = basis.toUpperCase();
        if (upper.includes('KGS')) qty = parseFloat(q.weight) || 1;
        else if (upper.includes('CBM')) qty = parseFloat(q.volume) || 1;
        else if (upper.includes('CONT')) qty = parseFloat(q.containers) || parseFloat(q.containerCount) || 1;
        else if (upper.includes('PKG')) qty = parseFloat(q.packages) || parseFloat(q.pallets) || 1;
        const rate = amount;
        const total = rate * qty;
        const currency = String(c.currency || 'INR').toUpperCase();
        const fx = currency === 'INR' ? 1 : Number(db.exchangeRates?.[currency] || (currency === 'USD' ? db.exchangeRates?.USD : 0) || 0);
        const totalINR = currency === 'INR' ? total : total * fx;
        lines.push({ name, basis, qty, rate, total, totalINR, currency });
    });
    return lines;
}

// ---------- Open Invoice Modal ----------
function openInvoiceFromQuote(prefillRef) {
    let modal = document.getElementById('v91InvoiceModal');
    if (!modal) {
        // Create modal if not present
        modal = document.createElement('div');
        modal.id = 'v91InvoiceModal';
        modal.className = 'modal-overlay';
        modal.innerHTML = `
            <div class="v91-invoice-modal">
                <div class="modal-header">
                    <div><h3>🧾 Generate Invoice</h3><small>Quote Ref → Invoice</small></div>
                    <button class="btn btn-clear" onclick="document.getElementById('v91InvoiceModal').classList.remove('show')">×</button>
                </div>
                <div class="v91-invoice-body" id="v91InvoiceBody"></div>
            </div>
        `;
        document.body.appendChild(modal);
    }

    // Build quote list
    const quotes = [];
    ['sea', 'air', 'lcl', 'sea-import'].forEach(mode => {
        (db.rates?.[mode] || []).forEach(q => quotes.push({ ...q, _mode: mode }));
    });
    const options = quotes.map(q =>
        `<option value="${escapeHtml(q.quoteNumber || q.quoteNo || q.id || '')}">${escapeHtml(q.quoteNumber || q.quoteNo || q.id || '-')} — ${escapeHtml(q.client || q.customer || '-')} — ${escapeHtml(q.pol || '-')} → ${escapeHtml(q.pod || '-')}</option>`
    ).join('');

    const body = document.getElementById('v91InvoiceBody');
    body.innerHTML = `
        <div class="v91-invoice-grid">
            <div><label>QUOTE REF *</label>
                <input id="v91-inv-quote" list="v91-inv-quote-list" value="${escapeHtml(prefillRef || '')}" placeholder="Type or select Quote Ref" oninput="loadInvoiceFromQuote()" onchange="loadInvoiceFromQuote()" onblur="loadInvoiceFromQuote()">
                <datalist id="v91-inv-quote-list">${options}</datalist>
            </div>
            <div><label>Invoice Date</label><input type="date" id="v91-inv-date" value="${new Date().toISOString().slice(0, 10)}"></div>
            <div><label>Due Date</label><input type="date" id="v91-inv-due"></div>
            <div><label>Payment Terms</label><input id="v91-inv-terms" value="15 Days"></div>
        </div>
        <div id="v91-inv-preview" class="v91-invoice-preview">Select a Quote Ref to fetch customer, route and amount.</div>
        <div class="v91-invoice-actions">
            <button class="btn btn-clear" onclick="document.getElementById('v91InvoiceModal').classList.remove('show')">Cancel</button>
            <button class="btn btn-success" onclick="saveInvoiceFromQuote()">💾 Generate Invoice</button>
        </div>
    `;
    modal.classList.add('show');
    if (prefillRef) setTimeout(loadInvoiceFromQuote, 100);
}

// ---------- Load Quote Data ----------
function loadInvoiceFromQuote() {
    const ref = document.getElementById('v91-inv-quote')?.value.trim();
    const preview = document.getElementById('v91-inv-preview');
    if (!ref) { preview.innerHTML = 'Please select a Quote Ref.'; return; }
    const found = findQuote(ref);
    if (!found) { preview.innerHTML = '❌ Quote not found. Please check the reference.'; return; }
    const q = found.data;
    // Keep an editable working copy for this invoice BEFORE finalization.
    window._invoiceDraftLines = quoteChargeLines(q).map(l => ({
        name: l.name || 'Charge', basis: l.basis || 'Normal', qty: Number(l.qty) || 1,
        rate: Number(l.rate) || 0, currency: String(l.currency || 'INR').toUpperCase()
    }));
    renderInvoiceDraftEditor();
}

function invoiceDraftFX(currency){
    const c=String(currency||'INR').toUpperCase();
    if(c==='INR') return 1;
    const r=parseFloat(db.exchangeRates?.[c]);
    return Number.isFinite(r) && r>0 ? r : (c==='USD' ? parseFloat(db.exchangeRates?.USD)||0 : 0);
}
function normalizeInvoiceDraftLine(l){
    const currency=String(l.currency||'INR').toUpperCase();
    const qty=Math.max(0,parseFloat(l.qty)||0);
    const rate=parseFloat(l.rate)||0;
    const total=qty*rate;
    const fx=invoiceDraftFX(currency);
    return {...l, name:l.name||'Charge', basis:l.basis||'Normal', qty, rate, currency, total, totalINR:currency==='INR'?total:total*fx};
}
function renderInvoiceDraftEditor(){
    const preview=document.getElementById('v91-inv-preview'); if(!preview)return;
    const lines=(window._invoiceDraftLines||[]).map(normalizeInvoiceDraftLine);
    window._invoiceDraftLines=lines;
    const total=lines.reduce((a,l)=>a+(Number(l.totalINR)||0),0);
    const q=(()=>{const ref=document.getElementById('v91-inv-quote')?.value.trim(); const f=findQuote(ref); return f?f.data:null;})();
    if(!q){preview.innerHTML='Please select a valid Quote Ref.';return;}
    const mode=(()=>{const f=findQuote(document.getElementById('v91-inv-quote')?.value.trim());return (f?.mode||'').toUpperCase();})();
    const rows=lines.map((l,i)=>`<tr>
      <td><input class="invoice-draft-edit" data-i="${i}" data-f="name" value="${escapeHtml(l.name)}"></td>
      <td><input class="invoice-draft-edit" data-i="${i}" data-f="basis" value="${escapeHtml(l.basis)}"></td>
      <td><input class="invoice-draft-edit" data-i="${i}" data-f="qty" type="number" step="any" min="0" value="${l.qty}"></td>
      <td><input class="invoice-draft-edit" data-i="${i}" data-f="rate" type="number" step="any" min="0" value="${l.rate}"></td>
      <td><select class="invoice-draft-edit" data-i="${i}" data-f="currency"><option ${l.currency==='INR'?'selected':''}>INR</option><option ${l.currency==='USD'?'selected':''}>USD</option><option ${l.currency==='EUR'?'selected':''}>EUR</option><option ${l.currency==='GBP'?'selected':''}>GBP</option></select></td>
      <td style="text-align:right;font-weight:700">${formatINR(l.totalINR)}</td>
      <td><button type="button" class="btn btn-sm btn-clear" onclick="invoiceDraftRemoveLine(${i})">🗑</button></td>
    </tr>`).join('') || '<tr><td colspan="7" style="text-align:center">No charge lines. Add a charge before finalizing.</td></tr>';
    preview.innerHTML=`
      <div class="v91-invoice-summary">
        <div><span>QUOTE</span><b>${escapeHtml(q.quoteNumber || q.quoteNo || q.id || '-')}</b></div>
        <div><span>CUSTOMER</span><b>${escapeHtml(q.client || q.customer || '-')}</b></div>
        <div><span>ROUTE</span><b>${escapeHtml(q.pol || '-')} → ${escapeHtml(q.pod || '-')}</b></div>
        <div><span>MODE</span><b>${escapeHtml(mode || '-')}</b></div>
        <div><span>CARRIER</span><b>${escapeHtml(q.carrier || '-')}</b></div>
        <div><span>GRAND TOTAL</span><b id="v91-draft-grand">${formatINR(total)}</b></div>
      </div>
      <div style="margin-top:12px;border-top:1px solid var(--border);padding-top:8px">
        <div style="display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:6px">
          <h4 style="font-size:.8rem;margin:0">✏️ Invoice Charges — Edit Before Finalization</h4>
          <button type="button" class="btn btn-sm btn-info" onclick="invoiceDraftAddLine()">＋ Add Charge</button>
        </div>
        <div class="v11-inv-table-wrap"><table class="v11-inv-table">
          <thead><tr><th>Charge</th><th>Basis</th><th>Qty</th><th>Rate</th><th>Currency</th><th>INR Amount</th><th>Action</th></tr></thead>
          <tbody id="v91-invoice-draft-lines">${rows}</tbody>
          <tfoot><tr><td colspan="5">GRAND TOTAL</td><td id="v91-draft-grand-foot"><strong>${formatINR(total)}</strong></td><td></td></tr></tfoot>
        </table></div>
        <div style="margin-top:6px;font-size:.72rem;color:#64748b">You can change charge name, basis, quantity, rate and currency before clicking Generate Invoice.</div>
      </div>`;
    preview.querySelectorAll('.invoice-draft-edit').forEach(el=>{
      el.addEventListener('input',invoiceDraftFieldChange);
      el.addEventListener('change',invoiceDraftFieldChange);
    });
}
function invoiceDraftFieldChange(e){
    const i=Number(e.target.dataset.i), f=e.target.dataset.f;
    if(!window._invoiceDraftLines?.[i])return;
    // Update the data without re-rendering the table on every keystroke.
    // Re-rendering here was stealing focus after the first character.
    window._invoiceDraftLines[i][f]=e.target.value;

    const line=normalizeInvoiceDraftLine(window._invoiceDraftLines[i]);
    const row=e.target.closest('tr');
    if(row){
      const inrCell=row.children?.[5];
      if(inrCell) inrCell.textContent=formatINR(line.totalINR);
    }

    const total=(window._invoiceDraftLines||[])
      .map(normalizeInvoiceDraftLine)
      .reduce((a,l)=>a+(Number(l.totalINR)||0),0);
    const grand=formatINR(total);
    const summary=document.getElementById('v91-draft-grand');
    const footer=document.getElementById('v91-draft-grand-foot');
    if(summary) summary.textContent=grand;
    if(footer) footer.innerHTML=`<strong>${grand}</strong>`;
}
window.invoiceDraftAddLine=function(){
    window._invoiceDraftLines=window._invoiceDraftLines||[];
    window._invoiceDraftLines.push({name:'New Charge',basis:'Normal',qty:1,rate:0,currency:'INR'});
    renderInvoiceDraftEditor();
};
window.invoiceDraftRemoveLine=function(i){
    if(!window._invoiceDraftLines)return;
    window._invoiceDraftLines.splice(i,1);
    renderInvoiceDraftEditor();
};

// ---------- Save Invoice ----------
function saveInvoiceFromQuote() {
    const ref = document.getElementById('v91-inv-quote')?.value.trim();
    const dueDate = document.getElementById('v91-inv-due')?.value || '';
    if (!dueDate) return alert('Invoice Due Date is mandatory. Please select Due Date.');
    const found = findQuote(ref);
    if (!found) return alert('Please select a valid Quote Ref.');
    const q = found.data;
    const lines = (window._invoiceDraftLines || []).map(normalizeInvoiceDraftLine);
    if (!lines.length) return alert('Please add at least one invoice charge before finalization.');
    const total = lines.reduce((a, l) => a + (Number(l.totalINR) || 0), 0);
    if (!Number.isFinite(total)) return alert('Invoice total could not be calculated. Please check charge values.');

    db.invoices = Array.isArray(db.invoices) ? db.invoices : [];
    const now = new Date();
    const no = `INV-${now.getFullYear().toString().slice(-2)}${String(now.getMonth() + 1).padStart(2, '0')}-${String(db.invoices.length + 1).padStart(5, '0')}`;
    const linkedShipment = (db.shipments || []).find(s => String(s.quoteRef || s.quoteNumber || s.rateQuoteRef || '').trim() === String(q.quoteNumber || ref).trim());
    db.invoices.push({
        id: no, invoiceNo: no,
        jobNo: linkedShipment?.jobNo || linkedShipment?.code || '',
        shipmentCode: linkedShipment?.code || '',
        quoteRef: q.quoteNumber || ref,
        customer: q.client || q.customer || '', client: q.client || q.customer || '',
        mode: String(found.mode || '').toUpperCase(), pol: q.pol || '', pod: q.pod || '', carrier: q.carrier || '',
        amount: total, total: total, inrEquivalent: total, received: 0, status: 'ISSUED',
        invoiceDate: document.getElementById('v91-inv-date')?.value || now.toISOString().slice(0, 10),
        dueDate, paymentTerms: document.getElementById('v91-inv-terms')?.value || '15 Days',
        chargeLines: lines, createdAt: now.toISOString()
    });
    window._invoiceDraftLines=[];
    saveDB();
    try { syncPlannerAutoTasksFromInvoices(); saveDB(); } catch (e) { console.warn('Invoice task sync:', e); }
    document.getElementById('v91InvoiceModal')?.classList.remove('show');
    renderInvoiceTab();
    alert(`✅ Invoice ${no} finalized from ${q.quoteNumber || ref}.`);
}

// ---------- Render Invoice List ----------
function getSelectedInvoiceIndex() {
    const checked = Array.from(document.querySelectorAll('.invoice-row-check:checked'));
    if (checked.length !== 1) {
        alert(checked.length === 0 ? 'Please select one invoice first.' : 'Please select only one invoice for this action.');
        return null;
    }
    const idx = parseInt(checked[0].dataset.idx, 10);
    return Number.isFinite(idx) ? idx : null;
}

function invoiceActionPreview() { const idx=getSelectedInvoiceIndex(); if(idx===null)return; const x=db.invoices[idx]; openInvoicePreviewV11(x.invoiceNo||x.id); }
function invoiceActionEmail() { const idx=getSelectedInvoiceIndex(); if(idx===null)return; const x=db.invoices[idx]; emailInvoiceV11(x.invoiceNo||x.id); }
function invoiceActionCopyCompact() { const idx=getSelectedInvoiceIndex(); if(idx===null)return; const x=db.invoices[idx]; window._previewInvoiceData=x; copyInvoiceTables(); }
function invoiceActionDelete() { const idx=getSelectedInvoiceIndex(); if(idx===null)return; const x=db.invoices[idx]; deleteInvoiceV11(x.invoiceNo||x.id); }

function renderInvoiceTab() {
    const tbody = document.getElementById('invoice-list');
    if (!tbody) return;
    db.invoices = Array.isArray(db.invoices) ? db.invoices : [];

    // Update KPI cards
    const total = db.invoices.reduce((a, x) => a + (parseFloat(x.amount || x.total) || 0), 0);
    const issued = db.invoices.filter(x => String(x.status || '').toUpperCase() === 'ISSUED').length;
    const paid = db.invoices.filter(x => String(x.status || '').toUpperCase() === 'PAID').length;
    const outstanding = db.invoices.reduce((a, x) => {
        const amt = parseFloat(x.amount || x.total) || 0;
        const rec = parseFloat(x.received || x.paid) || 0;
        return a + Math.max(0, amt - rec);
    }, 0);

    document.getElementById('invoice-kpi-total').textContent = db.invoices.length;
    document.getElementById('invoice-kpi-issued').textContent = issued;
    document.getElementById('invoice-kpi-paid').textContent = paid;
    document.getElementById('invoice-kpi-outstanding').textContent = formatINR(outstanding);

    // Build table rows
    if (db.invoices.length === 0) {
        tbody.innerHTML = '<tr><td colspan="11" class="v9-empty">No invoices yet. Click "+ New Invoice" to generate one.</td></tr>';
        return;
    }

    // Remaining Days = Invoice Due Date - Today (calendar days).
    // Do not change/save invoice data; this is display-only.
    const getInvoiceRemainingDays = (invoice) => {
        const dueValue = invoice.dueDate || invoice.due || invoice.invoiceDueDate || '';
        if (!dueValue) return { text: '-', cls: 'invoice-remaining-neutral' };
        if (String(invoice.status || '').toUpperCase() === 'PAID') {
            return { text: '-', cls: 'invoice-remaining-neutral' };
        }

        const due = new Date(dueValue);
        if (Number.isNaN(due.getTime())) return { text: '-', cls: 'invoice-remaining-neutral' };

        const today = new Date();
        const todayUTC = Date.UTC(today.getFullYear(), today.getMonth(), today.getDate());
        const dueUTC = Date.UTC(due.getFullYear(), due.getMonth(), due.getDate());
        const days = Math.round((dueUTC - todayUTC) / 86400000);

        if (days > 0) return { text: `${days} Days`, cls: 'invoice-remaining-ok' };
        if (days === 0) return { text: 'Due Today', cls: 'invoice-remaining-today' };
        return { text: `Overdue ${Math.abs(days)} Days`, cls: 'invoice-remaining-overdue' };
    };

    tbody.innerHTML = db.invoices.slice().reverse().map((x, idx) => {
        const realIdx = db.invoices.length - 1 - idx;
        const statusClass = String(x.status || '').toUpperCase() === 'PAID' ? 'v9-status-final' : 'v9-status-draft';
        const remaining = getInvoiceRemainingDays(x);
        return `
            <tr>
                <td style="text-align:center;"><input type="checkbox" class="invoice-row-check" data-idx="${realIdx}" onchange="updateInvoiceSelection()"></td>
                <td><strong class="v9-ref">${escapeHtml(x.invoiceNo || x.id || '-')}</strong></td>
                <td>${escapeHtml(x.quoteRef || '-')}</td>
                <td><strong>${escapeHtml(x.customer || x.client || '-')}</strong></td>
                <td><span class="v9-service ${String(x.mode || '').toLowerCase()}">${escapeHtml(x.mode || '-')}</span></td>
                <td>${escapeHtml(x.pol || '-')}</td>
                <td>${escapeHtml(x.pod || '-')}</td>
                <td><strong>${formatINR(x.amount || x.total)}</strong></td>
                <td>${fmtDate(x.invoiceDate || x.date)}</td>
                <td><span class="${remaining.cls}">${remaining.text}</span></td>
                <td><span class="${statusClass}">${escapeHtml(x.status || 'ISSUED')}</span></td>
            </tr>
        `;
    }).join('');

    // Sync selection count
    updateInvoiceSelection();
}


// ---------- Preview Invoice ----------
function toggleAllInvoices(checked) {
    document.querySelectorAll('.invoice-row-check').forEach(cb => cb.checked = checked);
    updateInvoiceSelection();
}

// ---------- Update Selection Count ----------
function updateInvoiceSelection() {
    const count = document.querySelectorAll('.invoice-row-check:checked').length;
    const el = document.getElementById('v11-invoice-selected');
    if (el) el.textContent = count + ' selected';
}



