// ==================== AUTO-SAVE MEASUREMENT DEFAULTS ON CHANGE ====================
function autoSaveMeasurementDefaults() {
    const inputIds = [
        'def-gst', 'def-insurance', 'def-profit',
        'def-us-tariff', 'def-us-mpf', 'def-us-hmf',
        'def-in-duty', 'def-in-social', 'def-drawback', 'def-rodtep'
    ];
    inputIds.forEach(id => {
        const el = document.getElementById(id);
        if (el) {
            el.addEventListener('input', function() {
                db.defaults.gst = parseFloat(document.getElementById('def-gst').value) || 0;
                db.defaults.insurance = parseFloat(document.getElementById('def-insurance').value) || 0;
                db.defaults.profitMargin = parseFloat(document.getElementById('def-profit').value) || 0;
                db.defaults.usTariff = parseFloat(document.getElementById('def-us-tariff').value) || 0;
                db.defaults.usMPF = parseFloat(document.getElementById('def-us-mpf').value) || 0;
                db.defaults.usHMF = parseFloat(document.getElementById('def-us-hmf').value) || 0;
                db.defaults.inDuty = parseFloat(document.getElementById('def-in-duty').value) || 0;
                db.defaults.inSocialWelfare = parseFloat(document.getElementById('def-in-social').value) || 0;
                db.defaults.drawback = parseFloat(document.getElementById('def-drawback').value) || 0;
                db.defaults.rodtep = parseFloat(document.getElementById('def-rodtep').value) || 0;
                saveDB();
                refreshMeasurementDefaults();
            });
        }
    });
}

document.addEventListener('DOMContentLoaded', function() {
    autoSaveMeasurementDefaults();
});

// ==================== MEASUREMENT CALCULATORS ====================
function showMeasurementMenu() {
    document.getElementById('measurement-menu').style.display = 'block';
    document.getElementById('measurement-content').style.display = 'none';
    document.querySelectorAll('#measurement-content .calc-panel').forEach(p => p.classList.remove('active'));
}

function switchCalcTab(tabId) {
    document.getElementById('measurement-menu').style.display = 'none';
    document.getElementById('measurement-content').style.display = 'block';
    document.querySelectorAll('#measurement-content .calc-panel').forEach(p => p.classList.remove('active'));

    // Apply the same selected-card visual treatment used by the Reporting Command Center.
    const measurementCards = document.querySelectorAll('#measurement-menu > div > .form-section');
    measurementCards.forEach(card => card.classList.remove('shahid-selection-active'));
    measurementCards.forEach(card => {
        const action = card.getAttribute('onclick') || '';
        if (action.indexOf("switchCalcTab('" + tabId + "')") !== -1) {
            card.classList.add('shahid-selection-active');
        }
    });

    const panel = document.getElementById('calc-' + tabId);
    if (panel) panel.classList.add('active');

    if (tabId === 'stuffing') {
        initStuffingPlanning();
    }

    if (['duty', 'product', 'insurance', 'us-duty'].includes(tabId)) {
        const ids = ['duty-currency', 'prod-currency', 'ins-currency', 'us-duty-currency'];
        ids.forEach(id => {
            const sel = document.getElementById(id);
            if (sel && sel.options.length === 0) {
                sel.innerHTML = '<option value="">Select</option>' + Object.keys(db.exchangeRates).map(c =>
                    `<option value="${c}">${c}</option>`).join('');
            }
        });
    }

    refreshMeasurementDefaults();
    if (tabId === 'duty') calcDuty();
    else if (tabId === 'product') calcProduct();
    else if (tabId === 'insurance') calcInsurance();
    else if (tabId === 'us-duty') calcUSDuty();
}

function setExchangeRate(targetInputId, currencyInputId) {
    const cur = document.getElementById(currencyInputId).value;
    const rate = db.exchangeRates[cur];
    if (rate) {
        document.getElementById(targetInputId).value = rate;
        document.getElementById(targetInputId).disabled = false;
    } else {
        document.getElementById(targetInputId).value = '';
        document.getElementById(targetInputId).disabled = false;
    }
    const panel = document.getElementById(currencyInputId).closest('.calc-panel');
    if (panel.id === 'calc-duty') calcDuty();
    else if (panel.id === 'calc-product') calcProduct();
    else if (panel.id === 'calc-insurance') calcInsurance();
    else if (panel.id === 'calc-us-duty') calcUSDuty();
}

document.addEventListener('change', function(e) {
    if (e.target.id === 'duty-currency') setExchangeRate('duty-exrate', 'duty-currency');
    if (e.target.id === 'prod-currency') setExchangeRate('prod-exrate', 'prod-currency');
    if (e.target.id === 'ins-currency') setExchangeRate('ins-exrate', 'ins-currency');
    if (e.target.id === 'us-duty-currency') setExchangeRate('us-duty-exrate', 'us-duty-currency');
});

function _dutyEsc(value) {
    return String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

function _dutyFormatUSD(n) {
    return '$ ' + Number(n || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function _dutyFormatInput(n) {
    return Number(n || 0).toLocaleString('en-US', { maximumFractionDigits: 2, useGrouping: false });
}

function _dutyDefaultPct() {
    const d = (typeof db !== 'undefined' && db.defaults) ? db.defaults : {};
    return Number.isFinite(parseFloat(d.inDuty)) ? parseFloat(d.inDuty) : 0;
}

function addDutyProduct(data = {}) {
    const body = document.getElementById('duty-products-body');
    if (!body) return;
    const index = body.querySelectorAll('tr[data-duty-row]').length + 1;
    const dutyPct = data.dutyPct !== undefined ? data.dutyPct : _dutyDefaultPct();
    const row = document.createElement('tr');
    row.setAttribute('data-duty-row', '1');
    row.style.borderBottom = '1px solid var(--border)';
    row.innerHTML = `
        <td style="padding:8px;text-align:center;"><input type="checkbox" class="duty-select" aria-label="Select product ${index}"></td>
        <td class="duty-row-no" style="padding:8px;text-align:center;font-weight:700;">${index}</td>
        <td style="padding:8px;"><input class="duty-product-desc" type="text" placeholder="Product description" value="${_dutyEsc(data.description || '')}" oninput="calcDuty()" style="width:100%;min-width:150px;padding:7px 8px;border:1px solid var(--border);border-radius:6px;background:var(--card-bg);color:var(--text);"></td>
        <td style="padding:8px;"><input class="duty-hs-code" type="text" placeholder="HS Code" value="${_dutyEsc(data.hsCode || '')}" oninput="calcDuty()" style="width:100%;min-width:115px;padding:7px 8px;border:1px solid var(--border);border-radius:6px;background:var(--card-bg);color:var(--text);"></td>
        <td style="padding:8px;"><input class="duty-cargo" type="number" min="0" step="0.01" value="${_dutyFormatInput(data.cargoValue || 0)}" oninput="calcDuty()" style="width:100%;min-width:110px;padding:7px 8px;border:1px solid var(--border);border-radius:6px;text-align:right;background:var(--card-bg);color:var(--text);"></td>
        <td style="padding:8px;"><input class="duty-rate" type="number" min="0" step="0.01" value="${_dutyFormatInput(dutyPct)}" oninput="calcDuty()" style="width:100%;min-width:80px;padding:7px 8px;border:1px solid var(--border);border-radius:6px;text-align:right;background:var(--card-bg);color:var(--text);"></td>
        <td class="duty-allocated-freight" style="padding:8px;text-align:right;font-weight:600;">$ 0.00</td>
        <td class="duty-assessable" style="padding:8px;text-align:right;font-weight:600;">$ 0.00</td>
        <td class="duty-bcd" style="padding:8px;text-align:right;font-weight:700;">$ 0.00</td>
        <td class="duty-sws" style="padding:8px;text-align:right;font-weight:700;">$ 0.00</td>
        <td class="duty-gst" style="padding:8px;text-align:right;font-weight:700;">$ 0.00</td>
        <td class="duty-total" style="padding:8px;text-align:right;font-weight:800;">$ 0.00</td>
        <td style="padding:8px;text-align:center;"><button type="button" class="btn btn-danger btn-sm" onclick="removeDutyProduct(this)" title="Remove product">🗑</button></td>`;
    body.appendChild(row);
    calcDuty();
}

function removeDutyProduct(button) {
    const row = button && button.closest ? button.closest('tr[data-duty-row]') : null;
    if (row) row.remove();
    const body = document.getElementById('duty-products-body');
    if (body && !body.querySelector('tr[data-duty-row]')) addDutyProduct();
    else {
        body.querySelectorAll('.duty-row-no').forEach((el, i) => el.textContent = i + 1);
        calcDuty();
    }
}

function removeSelectedDutyProducts() {
    const body = document.getElementById('duty-products-body');
    if (!body) return;
    body.querySelectorAll('tr[data-duty-row]').forEach(row => {
        const cb = row.querySelector('.duty-select');
        if (cb && cb.checked) row.remove();
    });
    if (!body.querySelector('tr[data-duty-row]')) addDutyProduct();
    else {
        body.querySelectorAll('.duty-row-no').forEach((el, i) => el.textContent = i + 1);
        calcDuty();
    }
}

function resetDutyProducts() {
    const body = document.getElementById('duty-products-body');
    if (!body) return;
    body.innerHTML = '';
    const freight = document.getElementById('duty-freight');
    if (freight) freight.value = 0;
    addDutyProduct();
    calcDuty();
}

function ensureDutyProducts() {
    const body = document.getElementById('duty-products-body');
    if (body && !body.querySelector('tr[data-duty-row]')) addDutyProduct();
}

function calcDuty() {
    ensureDutyProducts();
    const ex = parseFloat(document.getElementById('duty-exrate')?.value) || 0;
    const freightInsUsd = parseFloat(document.getElementById('duty-freight')?.value) || 0;
    const swsPct = parseFloat(document.getElementById('duty-service')?.value) || 0;
    const gstPct = parseFloat(document.getElementById('duty-gst')?.value) || 0;
    const currency = document.getElementById('duty-currency')?.value || 'USD';
    const body = document.getElementById('duty-products-body');
    if (!body) return;

    const rows = [...body.querySelectorAll('tr[data-duty-row]')];
    const products = rows.map(row => ({
        row,
        cargo: Math.max(0, parseFloat(row.querySelector('.duty-cargo')?.value) || 0),
        dutyPct: Math.max(0, parseFloat(row.querySelector('.duty-rate')?.value) || 0)
    }));
    const totalCargoInput = products.reduce((sum, p) => sum + p.cargo, 0);

    let totalCargoInr = 0;
    let totalFreightInr = 0;
    let totalAssessableInr = 0;
    let totalDutyInr = 0;
    let totalSwsInr = 0;
    let totalGstInr = 0;

    products.forEach(p => {
        // Preserve the existing calculator's logic exactly, applied per product:
        // assessable value = cargo value + allocated freight & insurance;
        // duty = assessable value × product duty %;
        // SWS = duty × SWS %;
        // GST = (assessable value + duty + SWS) × GST %.
        const share = totalCargoInput > 0 ? p.cargo / totalCargoInput : 0;
        const allocatedFreightUsd = freightInsUsd * share;
        const cargoInr = p.cargo * ex;
        const freightInr = allocatedFreightUsd * ex;
        const assessableInr = cargoInr + freightInr;
        const dutyInr = assessableInr * (p.dutyPct / 100);
        const swsInr = dutyInr * (swsPct / 100);
        const gstInr = gstPct / 100 * (assessableInr + dutyInr + swsInr);
        const totalInr = dutyInr + swsInr + gstInr;

        p.row.querySelector('.duty-allocated-freight').textContent = _dutyFormatUSD(allocatedFreightUsd);
        p.row.querySelector('.duty-assessable').textContent = _dutyFormatUSD(assessableInr / (ex || 1));
        p.row.querySelector('.duty-bcd').textContent = _dutyFormatUSD(dutyInr / (ex || 1));
        p.row.querySelector('.duty-sws').textContent = _dutyFormatUSD(swsInr / (ex || 1));
        p.row.querySelector('.duty-gst').textContent = _dutyFormatUSD(gstInr / (ex || 1));
        p.row.querySelector('.duty-total').textContent = _dutyFormatUSD(totalInr / (ex || 1));

        totalCargoInr += cargoInr;
        totalFreightInr += freightInr;
        totalAssessableInr += assessableInr;
        totalDutyInr += dutyInr;
        totalSwsInr += swsInr;
        totalGstInr += gstInr;
    });

    const totalPayableInr = totalDutyInr + totalSwsInr + totalGstInr;
    const exSafe = ex || 1;
    const totalCargoUsd = totalCargoInr / exSafe;
    const totalAssessableUsd = totalAssessableInr / exSafe;
    const totalDutyUsd = totalDutyInr / exSafe;
    const totalSwsUsd = totalSwsInr / exSafe;
    const totalGstUsd = totalGstInr / exSafe;
    const totalPayableUsd = totalPayableInr / exSafe;

    const totalFoot = document.getElementById('duty-products-total');
    if (totalFoot) {
        totalFoot.innerHTML = `<tr style="background:#dcfce7;font-weight:800;color:var(--text);"><td></td><td></td><td style="padding:10px;">Total</td><td></td><td style="padding:10px;text-align:right;">${_dutyFormatUSD(totalCargoUsd)}</td><td></td><td style="padding:10px;text-align:right;">${_dutyFormatUSD(freightInsUsd)}</td><td style="padding:10px;text-align:right;">${_dutyFormatUSD(totalAssessableUsd)}</td><td style="padding:10px;text-align:right;">${_dutyFormatUSD(totalDutyUsd)}</td><td style="padding:10px;text-align:right;">${_dutyFormatUSD(totalSwsUsd)}</td><td style="padding:10px;text-align:right;">${_dutyFormatUSD(totalGstUsd)}</td><td style="padding:10px;text-align:right;">${_dutyFormatUSD(totalPayableUsd)}</td><td></td></tr>`;
    }

    const setText = (id, value) => { const el = document.getElementById(id); if (el) el.textContent = value; };
    setText('duty-inr', formatINR(totalCargoInr));
    setText('duty-usd', _dutyFormatUSD(totalCargoUsd));
    setText('duty-frt-inr', formatINR(totalFreightInr));
    setText('duty-frt-usd', _dutyFormatUSD(freightInsUsd));
    setText('duty-assessable-inr', formatINR(totalAssessableInr));
    setText('duty-assessable-usd', _dutyFormatUSD(totalAssessableUsd));
    setText('duty-amt', formatINR(totalDutyInr));
    setText('duty-amt-usd', _dutyFormatUSD(totalDutyUsd));
    setText('duty-service-amt', formatINR(totalSwsInr));
    setText('duty-service-usd', _dutyFormatUSD(totalSwsUsd));
    setText('duty-gst-amt', formatINR(totalGstInr));
    setText('duty-gst-usd', _dutyFormatUSD(totalGstUsd));
    setText('duty-total', formatINR(totalPayableInr));
    setText('duty-total-usd', _dutyFormatUSD(totalPayableUsd));
    setText('duty-assessable-label', '📋 Total Assessable Value');
    setText('duty-amt-label', `DUT Basic Customs Duty (${products.length ? products.map(p => p.dutyPct).join(' / ') : 0}%)`);
    setText('duty-service-label', `SWS (${swsPct}%)`);
    setText('duty-gst-label', `GST (${gstPct}%)`);
    const head = document.getElementById('duty-cargo-head');
    if (head) head.textContent = `Cargo Value (${currency || 'USD'})`;
    const hiddenDutyPct = document.getElementById('duty-pct');
    if (hiddenDutyPct && products[0]) hiddenDutyPct.value = products[0].dutyPct;
}


function calcProduct() {
    const pricePerUnit = parseFloat(document.getElementById('prod-price').value) || 0;
    const weight = parseFloat(document.getElementById('prod-weight').value) || 0;
    const unit = document.getElementById('prod-unit').value;
    const ex = parseFloat(document.getElementById('prod-exrate').value) || 0;
    const freightUsd = parseFloat(document.getElementById('prod-freight').value) || 0;
    const otherUsd = parseFloat(document.getElementById('prod-other').value) || 0;
    const drawbackPct = parseFloat(document.getElementById('prod-drawback').value) || 0;
    const rodtepPct = parseFloat(document.getElementById('prod-rodtep').value) || 0;
    const profitPct = parseFloat(document.getElementById('prod-profit').value) || 0;

    let weightKgs = weight;
    if (unit === 'tons') weightKgs = weight * 1000;

    const productPriceUsd = pricePerUnit * weightKgs;
    const insuranceUsd = Math.max((productPriceUsd * 1.10) * 0.0005, 25);
    // Drawback and RODTEP are calculated on Product Price minus Insurance minus Freight.
    const benefitBaseUsd = productPriceUsd - insuranceUsd - freightUsd;
    const drawbackUsd = benefitBaseUsd * (drawbackPct / 100);
    const rodtepUsd = benefitBaseUsd * (rodtepPct / 100);
    const totalCostUsd = productPriceUsd + freightUsd + insuranceUsd + otherUsd;

    const productPriceInr = productPriceUsd * ex;
    const freightInr = freightUsd * ex;
    const insuranceInr = insuranceUsd * ex;
    const otherInr = otherUsd * ex;
    const drawbackInr = drawbackUsd * ex;
    const rodtepInr = rodtepUsd * ex;
    const totalCostInr = totalCostUsd * ex;

    const profitInr = totalCostInr * (profitPct / 100);
    const profitUsd = profitInr / ex;
    const finalPriceInr = totalCostInr + profitInr;
    const finalPriceUsd = finalPriceInr / ex;
    const totalMarginInr = drawbackInr + rodtepInr + profitInr;
    const totalMarginUsd = drawbackUsd + rodtepUsd + profitUsd;

    const formatUSD = (n) => '$ ' + Number(n || 0).toLocaleString('en-US', { minimumFractionDigits: 2,
        maximumFractionDigits: 2 });

    document.getElementById('prod-inr').textContent = formatINR(productPriceInr);
    document.getElementById('prod-usd').textContent = formatUSD(productPriceUsd);
    document.getElementById('prod-ins-inr').textContent = formatINR(insuranceInr);
    document.getElementById('prod-ins-usd').textContent = formatUSD(insuranceUsd);
    document.getElementById('prod-freight-inr').textContent = formatINR(freightInr);
    document.getElementById('prod-freight-usd').textContent = formatUSD(freightUsd);
    document.getElementById('prod-other-inr').textContent = formatINR(otherInr);
    document.getElementById('prod-other-usd').textContent = formatUSD(otherUsd);
    document.getElementById('prod-landed-inr').textContent = formatINR(totalCostInr);
    document.getElementById('prod-landed-usd').textContent = formatUSD(totalCostUsd);
    document.getElementById('prod-profit-inr').textContent = formatINR(profitInr);
    document.getElementById('prod-profit-usd').textContent = formatUSD(profitUsd);
    document.getElementById('prod-final').textContent = formatINR(finalPriceInr);
    document.getElementById('prod-final-usd').textContent = formatUSD(finalPriceUsd);

    document.getElementById('prod-drawback-inr').textContent = formatINR(drawbackInr);
    document.getElementById('prod-drawback-usd').textContent = formatUSD(drawbackUsd);
    document.getElementById('prod-rodtep-inr').textContent = formatINR(rodtepInr);
    document.getElementById('prod-rodtep-usd').textContent = formatUSD(rodtepUsd);
    document.getElementById('prod-benefit-profit-inr').textContent = formatINR(profitInr);
    document.getElementById('prod-benefit-profit-usd').textContent = formatUSD(profitUsd);
    document.getElementById('prod-total-margin-inr').textContent = formatINR(totalMarginInr);
    document.getElementById('prod-total-margin-usd').textContent = formatUSD(totalMarginUsd);

	document.querySelector('#prod-drawback-inr').closest('tr').querySelector('td:first-child').innerHTML =
		`<span style="background:#dbeafe;color:#1e3a8a;padding:2px 8px;border-radius:4px;font-size:0.7rem;">DBK</span> Drawback (${drawbackPct}%)`;
	document.querySelector('#prod-rodtep-inr').closest('tr').querySelector('td:first-child').innerHTML =
		`<span style="background:#fef3c7;color:#92400e;padding:2px 8px;border-radius:4px;font-size:0.7rem;">ROD</span> RODTEP (${rodtepPct}%)`;
	document.querySelector('#prod-benefit-profit-inr').closest('tr').querySelector('td:first-child').innerHTML =
		`<span style="background:#dbeafe;color:#1e3a8a;padding:2px 8px;border-radius:4px;font-size:0.7rem;">PRF</span> Expected Profit (${profitPct}%)`;


}

