function clearStuffingRows() {
    if (!confirm('Clear all stuffing rows?')) return;
    const tbody = document.getElementById('stuffing-table-body');
    if (!tbody) return;
    tbody.innerHTML = '';
    addStuffingRow();
}

function updateStuffingDates(departureInput) {
    if (!departureInput) return;
    const row = departureInput.closest('tr');
    if (!row || !departureInput.value) return;

    // Treat YYYY-MM-DD as a local calendar date so the displayed day never shifts by timezone.
    const parts = departureInput.value.split('-').map(Number);
    if (parts.length !== 3 || parts.some(Number.isNaN)) return;
    const depDate = new Date(parts[0], parts[1] - 1, parts[2]);
    if (Number.isNaN(depDate.getTime())) return;

    const readOffset = (id, fallback) => {
        const el = document.getElementById(id);
        if (!el || el.value === '') return fallback;
        const n = Number(el.value);
        return Number.isFinite(n) ? n : fallback;
    };

    const offsetEta = readOffset('offset-eta', -1);
    const offsetGateOpen = readOffset('offset-gate-open', -5);
    const offsetGateCut = readOffset('offset-gate-cut', -2);
    const offsetSbCut = readOffset('offset-sb-cut', -2);
    const offsetSiCut = readOffset('offset-si-cut', -3);

    const formatDate = (date) => {
        const y = date.getFullYear();
        const m = String(date.getMonth() + 1).padStart(2, '0');
        const d = String(date.getDate()).padStart(2, '0');
        return `${y}-${m}-${d}`;
    };

    const setOffsetDate = (selector, offset) => {
        const target = row.querySelector(selector);
        if (!target) return;
        const date = new Date(depDate);
        date.setDate(date.getDate() + offset);
        target.value = formatDate(date);
    };

    setOffsetDate('.stuffing-eta', offsetEta);
    setOffsetDate('.stuffing-gate-open', offsetGateOpen);
    setOffsetDate('.stuffing-gate-cut', offsetGateCut);
    setOffsetDate('.stuffing-sb-cut', offsetSbCut);
    setOffsetDate('.stuffing-si-cut', offsetSiCut);
}

function legacy_initStuffingPlanning() {
    const tbody = document.getElementById('stuffing-table-body');
    if (tbody && tbody.children.length === 0) {
        addStuffingRow();
    }
}

function calcInsurance() {
    const val = parseFloat(document.getElementById('ins-value').value) || 0;
    const ex = parseFloat(document.getElementById('ins-exrate').value) || 0;
    const insPct = parseFloat(document.getElementById('ins-pct').value) || 0;
    const gstPct = parseFloat(document.getElementById('ins-gst').value) || 0;
    const totalRow = document.getElementById('ins-total-row');
    if (val === 0 || ex === 0) {
        totalRow.style.display = 'none';
        document.getElementById('ins-inr').textContent = '₹ 0.00';
        document.getElementById('ins-usd').textContent = '$ 0.00';
        document.getElementById('ins-amt').textContent = '₹ 0.00';
        document.getElementById('ins-amt-usd').textContent = '$ 0.00';
        document.getElementById('ins-gst-amt').textContent = '₹ 0.00';
        document.getElementById('ins-gst-usd').textContent = '$ 0.00';
        document.getElementById('ins-total').textContent = '₹ 0.00';
        document.getElementById('ins-total-usd').textContent = '$ 0.00';
        return;
    }
    // Insurance is always calculated on 110% of the entered cargo value.
    // Example: cargo value 100 => insured cargo value 110.
    const insuredCargoValue = val * 1.10;
    const calculatedIns = insuredCargoValue * (insPct / 100);
    const insUsd = Math.max(calculatedIns, 25);
    const insInr = insUsd * ex;
    const gstUsd = insUsd * (gstPct / 100);
    const gstInr = gstUsd * ex;
    const totalUsd = insUsd + gstUsd;
    const totalInr = insInr + gstInr;
    const formatUSD = (n) => '$ ' + Number(n || 0).toLocaleString('en-US', { minimumFractionDigits: 2,
        maximumFractionDigits: 2 });
    document.getElementById('ins-inr').textContent = formatINR(insuredCargoValue * ex);
    document.getElementById('ins-usd').textContent = formatUSD(insuredCargoValue);
    document.getElementById('ins-amt').textContent = formatINR(insInr);
    document.getElementById('ins-amt-usd').textContent = formatUSD(insUsd);
    document.getElementById('ins-gst-amt').textContent = formatINR(gstInr);
    document.getElementById('ins-gst-usd').textContent = formatUSD(gstUsd);
    document.getElementById('ins-total').textContent = formatINR(totalInr);
    document.getElementById('ins-total-usd').textContent = formatUSD(totalUsd);
    totalRow.style.display = 'table-footer-group';
	
	document.querySelector('#ins-gst-amt').closest('tr').querySelector('td:first-child').innerHTML =
    `<span style="background:#dbeafe;color:#1e3a8a;padding:2px 8px;border-radius:4px;font-size:0.7rem;">GST</span> GST on Insurance (${gstPct}%)`;
}

function calcUSDuty() {
    const val = parseFloat(document.getElementById('us-duty-value').value) || 0;
    const ex = parseFloat(document.getElementById('us-duty-exrate').value) || 0;
    const dutyPct = parseFloat(document.getElementById('us-duty-pct').value) || 0;
    const tariffPct = parseFloat(document.getElementById('us-duty-tariff').value) || 0;
    const mpfPct = parseFloat(document.getElementById('us-duty-mpf').value) || 0;
    const hmfPct = parseFloat(document.getElementById('us-duty-hmf').value) || 0;
    const inr = val * ex;
    const duty = inr * (dutyPct / 100);
    const tariff = inr * (tariffPct / 100);
    const mpf = inr * (mpfPct / 100);
    const hmf = inr * (hmfPct / 100);
    const total = duty + tariff + mpf + hmf;
    const valUsd = val;
    const dutyUsd = duty / ex;
    const tariffUsd = tariff / ex;
    const mpfUsd = mpf / ex;
    const hmfUsd = hmf / ex;
    const totalUsd = total / ex;
    const formatUSD = (n) => '$ ' + Number(n || 0).toLocaleString('en-US', { minimumFractionDigits: 2,
        maximumFractionDigits: 2 });
    document.getElementById('us-duty-inr').textContent = formatINR(inr);
    document.getElementById('us-duty-usd').textContent = formatUSD(valUsd);
    document.getElementById('us-duty-amt').textContent = formatINR(duty);
    document.getElementById('us-duty-amt-usd').textContent = formatUSD(dutyUsd);
    document.getElementById('us-duty-tariff-amt').textContent = formatINR(tariff);
    document.getElementById('us-duty-tariff-usd').textContent = formatUSD(tariffUsd);
    document.getElementById('us-duty-mpf-amt').textContent = formatINR(mpf);
    document.getElementById('us-duty-mpf-usd').textContent = formatUSD(mpfUsd);
    document.getElementById('us-duty-hmf-amt').textContent = formatINR(hmf);
    document.getElementById('us-duty-hmf-usd').textContent = formatUSD(hmfUsd);
    document.getElementById('us-duty-total').textContent = formatINR(total);
    document.getElementById('us-duty-total-usd').textContent = formatUSD(totalUsd);
}

if (!db.stuffing) db.stuffing = [];

function createStuffingRow(index, data) {
    const row = document.createElement('tr');
    row.style.borderBottom = '1px solid var(--border)';
    row.style.background = index % 2 === 0 ? 'var(--bg)' : 'var(--card-bg)';
    row.dataset.index = index;
    row.innerHTML = `
        <td style="padding:8px 14px;text-align:center;font-weight:600;">${index + 1}</td>
        <td style="padding:8px 14px;text-align:center;">
            <input type="text" class="stuffing-vessel" value="${data?.vessel || ''}" placeholder="Vessel name" style="width:100%;padding:4px;border:1px solid var(--border);border-radius:4px;text-align:center;" oninput="onStuffingInput()" />
        </td>
        <td style="padding:8px 14px;text-align:center;">
            <input type="date" class="stuffing-departure" value="${data?.departure || ''}" onchange="updateStuffingDates(this); onStuffingInput();" style="width:100%;padding:4px;border:1px solid var(--border);border-radius:4px;text-align:center;" />
        </td>
        <td style="padding:8px 14px;text-align:center;">
            <input type="date" class="stuffing-eta" value="${data?.eta || ''}" readonly style="width:100%;padding:4px;border:1px solid var(--border);border-radius:4px;text-align:center;background:#f1f5f9;" />
        </td>
        <td style="padding:8px 14px;text-align:center;">
            <input type="date" class="stuffing-gate-open" value="${data?.gateOpen || ''}" readonly style="width:100%;padding:4px;border:1px solid var(--border);border-radius:4px;text-align:center;background:#f1f5f9;" />
        </td>
        <td style="padding:8px 14px;text-align:center;">
            <input type="date" class="stuffing-gate-cut" value="${data?.gateCut || ''}" readonly style="width:100%;padding:4px;border:1px solid var(--border);border-radius:4px;text-align:center;background:#f1f5f9;" />
        </td>
        <td style="padding:8px 14px;text-align:center;">
            <input type="date" class="stuffing-sb-cut" value="${data?.sbCut || ''}" readonly style="width:100%;padding:4px;border:1px solid var(--border);border-radius:4px;text-align:center;background:#f1f5f9;" />
        </td>
        <td style="padding:8px 14px;text-align:center;">
            <input type="date" class="stuffing-si-cut" value="${data?.siCut || ''}" readonly style="width:100%;padding:4px;border:1px solid var(--border);border-radius:4px;text-align:center;background:#f1f5f9;" />
        </td>
        <td style="padding:8px 14px;text-align:center;">
            <button class="btn btn-sm btn-clear" onclick="event.stopPropagation(); removeStuffingRow(this)" style="padding:2px 8px;">×</button>
        </td>
    `;
    return row;
}

function saveStuffingData() {
    const tbody = document.getElementById('stuffing-table-body');
    if (!tbody) return;
    const rows = tbody.querySelectorAll('tr');
    if (!db || typeof db !== 'object') return;
    if (!Array.isArray(db.stuffing)) db.stuffing = [];

    db.stuffing = Array.from(rows).map(row => ({
        vessel: row.querySelector('.stuffing-vessel')?.value || '',
        departure: row.querySelector('.stuffing-departure')?.value || '',
        eta: row.querySelector('.stuffing-eta')?.value || '',
        gateOpen: row.querySelector('.stuffing-gate-open')?.value || '',
        gateCut: row.querySelector('.stuffing-gate-cut')?.value || '',
        sbCut: row.querySelector('.stuffing-sb-cut')?.value || '',
        siCut: row.querySelector('.stuffing-si-cut')?.value || ''
    }));
    saveDB();
}

function onStuffingInput() {
    saveStuffingData();
}

function onOffsetChange() {
    document.querySelectorAll('#stuffing-table-body .stuffing-departure').forEach(depInput => {
        if (depInput.value) updateStuffingDates(depInput);
    });
    saveStuffingData();
}

function removeStuffingRow(btn) {
    const row = btn && btn.closest('tr');
    const tbody = document.getElementById('stuffing-table-body');
    if (!row || !tbody) return;

    if (tbody.children.length > 1) {
        row.remove();
        tbody.querySelectorAll('tr').forEach((tr, i) => {
            const numberCell = tr.querySelector('td:first-child');
            if (numberCell) numberCell.textContent = i + 1;
        });
        saveStuffingData();
    } else {
        alert('You must keep at least one row.');
    }
}

function initStuffingPlanning() {
    const tbody = document.getElementById('stuffing-table-body');
    const panel = document.getElementById('calc-stuffing');
    if (!tbody || !panel) return;

    // Keep Stuffing Planning open while initializing/reinitializing its rows.
    panel.classList.add('active');
    tbody.innerHTML = '';
    const data = Array.isArray(db.stuffing) ? db.stuffing : [];

    if (data.length === 0) {
        const row = createStuffingRow(0, {});
        tbody.appendChild(row);
    } else {
        data.forEach((item, idx) => {
            tbody.appendChild(createStuffingRow(idx, item || {}));
        });
    }

    tbody.querySelectorAll('.stuffing-departure').forEach(depInput => {
        if (depInput.value) updateStuffingDates(depInput);
    });
}

// Explicit global bindings for Stuffing Planning action buttons.
// Kept module-scoped in purpose: no other ERP function is modified.
window.createStuffingRow = createStuffingRow;
window.addStuffingRow = addStuffingRow;
window.removeStuffingRow = removeStuffingRow;
window.clearStuffingRows = clearStuffingRows;
window.updateStuffingDates = updateStuffingDates;
window.onStuffingInput = onStuffingInput;
window.onOffsetChange = onOffsetChange;
window.saveStuffingData = saveStuffingData;
window.initStuffingPlanning = initStuffingPlanning;



// ============================================================
// CUSTOMER FOLLOWUP — REPORTING COMMAND CENTER INNER TAB
// ============================================================
const CUSTOMER_FOLLOWUP_PAGE_KEY = 'customerFollowupPage';
const CUSTOMER_FOLLOWUP_SIZE_KEY = 'customerFollowupPageSize';

function ensureCustomerFollowupStore() {
    if (!Array.isArray(db.customerFollowups)) db.customerFollowups = [];
    return db.customerFollowups;
}

function customerFollowupEsc(v) {
    return typeof escapeHtml === 'function' ? escapeHtml(v == null ? '' : String(v)) : String(v == null ? '' : v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function customerFollowupDateValue(v) {
    if (!v) return '';
    const d = String(v).slice(0,10);
    return /^\d{4}-\d{2}-\d{2}$/.test(d) ? d : '';
}

function customerFollowupStatusClass(status) {
    return String(status || 'PENDING').toLowerCase().replace(/\s+/g,'-');
}

function openCustomerFollowupForm(index = -1) {
    const form = document.getElementById('customer-followup-form');
    if (!form) return;
    const rows = ensureCustomerFollowupStore();
    const rec = index >= 0 && rows[index] ? rows[index] : {};
    const editing = index >= 0;
    form.style.display = 'block';
    form.innerHTML = `
      <div class="customer-followup-form-head"><strong>${editing ? '✏️ Edit Customer Followup' : '＋ Add Customer Followup'}</strong><button class="btn btn-clear btn-sm" type="button" onclick="closeCustomerFollowupForm()">✕ Close</button></div>
      <div class="customer-followup-form-grid">
        <div class="form-group"><label>Customer Name *</label><input id="cf-form-customer" type="text" value="${customerFollowupEsc(rec.customerName || '')}"/></div>
        <div class="form-group"><label>Contact Person</label><input id="cf-form-contact" type="text" value="${customerFollowupEsc(rec.contactPerson || '')}"/></div>
        <div class="form-group"><label>Phone No.</label><input id="cf-form-phone" type="tel" value="${customerFollowupEsc(rec.phone || '')}"/></div>
        <div class="form-group"><label>Email Id</label><input id="cf-form-email" type="email" value="${customerFollowupEsc(rec.email || '')}"/></div>
        <div class="form-group"><label>Stuffing Date</label><input id="cf-form-stuffing" type="date" value="${customerFollowupDateValue(rec.stuffingDate)}"/></div>
        <div class="form-group"><label>POL</label><input id="cf-form-pol" type="text" value="${customerFollowupEsc(rec.pol || '')}"/></div>
        <div class="form-group"><label>POD</label><input id="cf-form-pod" type="text" value="${customerFollowupEsc(rec.pod || '')}"/></div>
        <div class="form-group"><label>Cargo</label><input id="cf-form-cargo" type="text" value="${customerFollowupEsc(rec.cargo || '')}"/></div>
        <div class="form-group"><label>Inventory</label><input id="cf-form-inventory" type="text" value="${customerFollowupEsc(rec.inventory || '')}"/></div>
        <div class="form-group"><label>Call Time</label><input id="cf-form-calltime" type="time" value="${customerFollowupEsc(rec.callTime || '')}"/></div>
        <div class="form-group"><label>Status</label><select id="cf-form-status"><option ${(!rec.status || rec.status==='FOLLOW UP')?'selected':''}>FOLLOW UP</option><option ${rec.status==='IN PROGRESS'?'selected':''}>IN PROGRESS</option><option ${rec.status==='PENDING'?'selected':''}>PENDING</option><option ${rec.status==='DONE'?'selected':''}>DONE</option></select></div>
      </div>
      <div class="customer-followup-form-actions"><button class="btn btn-success btn-sm" type="button" onclick="saveCustomerFollowup(${index})">💾 Save</button><button class="btn btn-clear btn-sm" type="button" onclick="closeCustomerFollowupForm()">Cancel</button></div>`;
    form.scrollIntoView({behavior:'smooth', block:'nearest'});
}

function closeCustomerFollowupForm() {
    const form = document.getElementById('customer-followup-form');
    if (form) { form.style.display='none'; form.innerHTML=''; }
}

function saveCustomerFollowup(index = -1) {
    const rows = ensureCustomerFollowupStore();
    const customerName = (document.getElementById('cf-form-customer')?.value || '').trim();
    if (!customerName) return alert('Customer Name is required.');
    const now = new Date().toISOString();
    const rec = {
        customerName,
        contactPerson:(document.getElementById('cf-form-contact')?.value || '').trim(),
        phone:(document.getElementById('cf-form-phone')?.value || '').trim(),
        email:(document.getElementById('cf-form-email')?.value || '').trim(),
        emptyColumn:'',
        stuffingDate:document.getElementById('cf-form-stuffing')?.value || '',
        pol:(document.getElementById('cf-form-pol')?.value || '').trim(),
        pod:(document.getElementById('cf-form-pod')?.value || '').trim(),
        cargo:(document.getElementById('cf-form-cargo')?.value || '').trim(),
        inventory:(document.getElementById('cf-form-inventory')?.value || '').trim(),
        callTime:document.getElementById('cf-form-calltime')?.value || '',
        status:document.getElementById('cf-form-status')?.value || 'FOLLOW UP',
        lastModified:now
    };
    if (index >= 0 && rows[index]) {
        rows[index] = {...rows[index], ...rec};
    } else {
        rec.createdAt=now;
        rows.push(rec);
    }
    saveDB();
    closeCustomerFollowupForm();
    renderCustomerFollowup();
}

function deleteCustomerFollowup(index) {
    const rows=ensureCustomerFollowupStore();
    if (!rows[index]) return;
    if (!confirm(`Delete Customer Followup for ${rows[index].customerName || 'this customer'}?`)) return;
    rows.splice(index,1);
    saveDB();
    renderCustomerFollowup();
}

function clearCustomerFollowupFilters() {
    ['cf-search','cf-from','cf-to','cf-pol','cf-pod'].forEach(id => { const e=document.getElementById(id); if(e) e.value=''; });
    const status=document.getElementById('cf-status'); if(status) status.value='';
    sessionStorage.setItem(CUSTOMER_FOLLOWUP_PAGE_KEY,'1');
    renderCustomerFollowup();
}

function setCustomerFollowupPageSize(value) {
    const n=Math.max(1,Number(value)||15);
    sessionStorage.setItem(CUSTOMER_FOLLOWUP_SIZE_KEY,String(n));
    sessionStorage.setItem(CUSTOMER_FOLLOWUP_PAGE_KEY,'1');
    renderCustomerFollowup();
}

function renderCustomerFollowup() {
    const body=document.getElementById('customer-followup-detail');
    if (!body) return;
    const rows=ensureCustomerFollowupStore();
    const search=(document.getElementById('cf-search')?.value||'').trim().toLowerCase();
    const status=document.getElementById('cf-status')?.value||'';
    const from=document.getElementById('cf-from')?.value||'';
    const to=document.getElementById('cf-to')?.value||'';
    const pol=(document.getElementById('cf-pol')?.value||'').trim().toLowerCase();
    const pod=(document.getElementById('cf-pod')?.value||'').trim().toLowerCase();
    const filtered=rows.filter(r=>{
        const hay=[r.customerName,r.contactPerson,r.phone,r.email,r.cargo,r.inventory,r.pol,r.pod,r.callTime,r.status].join(' ').toLowerCase();
        const date=customerFollowupDateValue(r.stuffingDate);
        return (!search || hay.includes(search)) && (!status || (r.status||'PENDING')===status) && (!from || (date && date>=from)) && (!to || (date && date<=to)) && (!pol || String(r.pol||'').toLowerCase().includes(pol)) && (!pod || String(r.pod||'').toLowerCase().includes(pod));
    });
    const size=Math.max(1,Number(sessionStorage.getItem(CUSTOMER_FOLLOWUP_SIZE_KEY)||document.getElementById('customer-followup-page-size')?.value||15));
    const totalPages=Math.max(1,Math.ceil(filtered.length/size));
    let page=Math.max(1,Number(sessionStorage.getItem(CUSTOMER_FOLLOWUP_PAGE_KEY)||1));
    if(page>totalPages) page=totalPages;
    sessionStorage.setItem(CUSTOMER_FOLLOWUP_PAGE_KEY,String(page));
    const start=(page-1)*size;
    const view=filtered.slice(start,start+size);
    body.innerHTML=view.length ? view.map((r,i)=>{
        const idx=rows.indexOf(r);
        const phone=r.phone ? `<a class="customer-followup-phone" href="tel:${customerFollowupEsc(r.phone)}">${customerFollowupEsc(r.phone)} ☎</a>` : '-';
        const time=r.callTime ? customerFollowupEsc(r.callTime) : '-';
        const date=r.stuffingDate ? customerFollowupEsc(r.stuffingDate) : '-';
        const st=r.status||'PENDING';
        return `<tr><td>${start+i+1}</td><td><strong>${customerFollowupEsc(r.customerName||'-')}</strong></td><td>${customerFollowupEsc(r.contactPerson||'-')}</td><td>${phone}</td><td>${date}</td><td>${customerFollowupEsc(r.pol||'-')}</td><td>${customerFollowupEsc(r.pod||'-')}</td><td>${customerFollowupEsc(r.cargo||'-')}</td><td>${customerFollowupEsc(r.inventory||'-')}</td><td>${time}</td><td><span class="customer-followup-status status-${customerFollowupStatusClass(st)}">${customerFollowupEsc(st)}</span></td><td><div class="customer-followup-actions"><button class="btn btn-info btn-sm" onclick="openCustomerFollowupForm(${idx})">✏️</button><button class="btn btn-clear btn-sm" onclick="deleteCustomerFollowup(${idx})">🗑️</button></div></td></tr>`;
    }).join('') : '<tr><td colspan="14" class="report-empty">No Customer Followup records found.</td></tr>';
    const count=document.getElementById('customer-followup-count');
    if(count) count.textContent=filtered.length ? `Showing ${start+1} to ${Math.min(start+size,filtered.length)} of ${filtered.length} entries` : 'Showing 0 entries';
    const sizeEl=document.getElementById('customer-followup-page-size'); if(sizeEl) sizeEl.value=String(size);
    const pg=document.getElementById('customer-followup-pagination');
    if(pg){
        const btn=(label,p,disabled=false,active=false)=>`<button type="button" class="${active?'active':''}" ${disabled?'disabled':''} onclick="goCustomerFollowupPage(${p})">${label}</button>`;
        let html=btn('‹',Math.max(1,page-1),page===1);
        const maxButtons=5; let a=Math.max(1,page-2), b=Math.min(totalPages,a+maxButtons-1); a=Math.max(1,b-maxButtons+1);
        for(let p=a;p<=b;p++) html+=btn(String(p),p,false,p===page);
        html+=btn('›',Math.min(totalPages,page+1),page===totalPages); pg.innerHTML=html;
    }
}

function goCustomerFollowupPage(page) {
    sessionStorage.setItem(CUSTOMER_FOLLOWUP_PAGE_KEY,String(Math.max(1,Number(page)||1)));
    renderCustomerFollowup();
}

function importCustomerFollowups(file) {
    if(!file) return;
    if(typeof XLSX==='undefined') return alert('Excel library is not loaded.');
    const reader=new FileReader();
    reader.onload=e=>{
        try{
            const wb=XLSX.read(new Uint8Array(e.target.result),{type:'array'});
            const ws=wb.Sheets[wb.SheetNames[0]];
            const data=XLSX.utils.sheet_to_json(ws,{defval:''});
            const rows=ensureCustomerFollowupStore(); const now=new Date().toISOString();
            data.forEach(x=>{
                const get=(...keys)=>{ for(const k of keys){ if(x[k]!==undefined && x[k]!==null) return String(x[k]).trim(); } return ''; };
                const customer=get('Customer Name','Customer','customerName'); if(!customer) return;
                rows.push({customerName:customer,contactPerson:get('Contact Person','contactPerson'),phone:get('Phone No.','Phone','phone'),email:get('Email Id','Email','email'),emptyColumn:'',stuffingDate:get('Stuffing Date','stuffingDate'),pol:get('POL','pol'),pod:get('POD','pod'),cargo:get('Cargo','cargo'),inventory:get('Inventory','inventory'),callTime:get('Call Time','callTime'),status:(get('Status','status')||'FOLLOW UP').toUpperCase(),createdAt:now,lastModified:now});
            });
            saveDB(); renderCustomerFollowup(); alert(`${data.length} row(s) imported.`);
        }catch(err){ console.error(err); alert('Unable to import Customer Followup file.'); }
    };
    reader.readAsArrayBuffer(file);
}

