function getBLCombinedData(b) {
    const out = { ...(b || {}) };
    const key = out.quoteRef || out.shipmentCode || out.jobNo || out.reference || '';
    if (!key) return out;
    const linked = findBLRelatedRecords(key);
    const s = linked.shipment || {};
    const q = linked.quote || {};
    // Preserve BL-entered values; use linked Shipment/Rate Quote only as fallbacks.
    const pick = (...vals) => vals.find(v => v !== undefined && v !== null && String(v).trim() !== '');
    out.jobNo = pick(out.jobNo, out.shipmentCode, s.jobNo, s.code, key);
    out.shipmentCode = pick(out.shipmentCode, s.jobNo, s.code, key);
    out.shipperName = pick(out.shipperName, s.shipper, s.shipperName, q.shipper, q.shipperName, q.client, q.customer);
    out.shipperAddr = pick(out.shipperAddr, s.shipperAddr, s.shipperAddress, q.shipperAddr, q.shipperAddress);
    out.consigneeName = pick(out.consigneeName, s.consignee, s.consigneeName, q.consignee, q.consigneeName);
    out.consigneeAddr = pick(out.consigneeAddr, s.consigneeAddr, s.consigneeAddress, q.consigneeAddr, q.consigneeAddress);
    out.notifyName = pick(out.notifyName, s.notifyParty, s.notifyName, q.notifyParty, q.notifyName);
    out.notifyAddr = pick(out.notifyAddr, s.notifyAddr, s.notifyAddress, q.notifyAddr, q.notifyAddress);
    out.deliveryAgentName = pick(out.deliveryAgentName, s.deliveryAgentName, s.deliveryAgent, q.deliveryAgentName, q.deliveryAgent);
    out.deliveryAgentAddr = pick(out.deliveryAgentAddr, s.deliveryAgentAddr, s.deliveryAgentAddress, q.deliveryAgentAddr, q.deliveryAgentAddress);
    out.pol = pick(out.pol, s.pol, q.pol);
    out.pod = pick(out.pod, s.pod, q.pod);
    out.vessel = pick(out.vessel, s.vessel, s.liner, q.carrier);
    out.bookingNo = pick(out.bookingNo, s.bookingNo, q.bookingNo);
    out.voyage = pick(out.voyage, s.voyage, q.voyage);
    out.grossWeight = pick(out.grossWeight, s.grossWeight, s.weight, q.grossWeight, q.weight, 0);
    out.measurement = pick(out.measurement, s.cbm, s.volume, q.cbm, q.volume, 0);
    out.packagesCount = pick(out.packagesCount, s.packages, q.packages);
    if ((!out.containers || !out.containers.length) && Array.isArray(s.containers) && s.containers.length) out.containers = s.containers.map(c => ({...c}));
    out.linkedShipment = s;
    out.linkedRateQuote = q;
    out.linkedQuoteMode = linked.quoteMode || '';
    return out;
}

function downloadBLPDF(idx) {
    const b = db.bldrafts[idx];
    if (!b) return alert('BL not found.');
    const combined = getBLCombinedData(b);
    const html = buildBLPreviewHTML(combined);
    const renderArea = document.getElementById('pdf-render-area');
    if (!renderArea) return alert('PDF render area not found.');
    renderArea.innerHTML = html;

    // SHAHID ERP — BL PDF TEXT SIZE AMENDMENT
    // Increase every rendered BL PDF text size by exactly 30%.
    // This is applied only to the PDF render copy; BL preview/UI sizing,
    // stored data, calculations, and the underlying BL HTML remain unchanged.
    try {
        const textSizeTargets = Array.from(renderArea.querySelectorAll('*')).map(el => {
            const computed = window.getComputedStyle(el);
            const px = parseFloat(computed.fontSize);
            return { el, px: Number.isFinite(px) ? px : null };
        });
        textSizeTargets.forEach(({el, px}) => {
            if (px !== null && px > 0) {
                el.style.setProperty('font-size', `${(px * 1.30).toFixed(3)}px`, 'important');
            }
        });
    } catch (e) {
        console.warn('BL PDF text-size adjustment skipped:', e);
    }

    // A4 printable area with exactly 0.5 cm margins on all sides.
    const PAGE_W_MM = 210, PAGE_H_MM = 297, MARGIN_MM = 5;
    const CONTENT_W_MM = PAGE_W_MM - (MARGIN_MM * 2);
    const CONTENT_H_MM = PAGE_H_MM - (MARGIN_MM * 2);
    const RENDER_PX = 1120;
    renderArea.style.cssText = `position:fixed;left:0;top:0;width:${RENDER_PX}px;background:white;z-index:9999;opacity:1;padding:0;margin:0;overflow:hidden;box-sizing:border-box;`;

    setTimeout(() => {
        html2canvas(renderArea, {
            scale: 2,
            useCORS: true,
            backgroundColor: '#ffffff',
            logging: false,
            width: RENDER_PX,
            windowWidth: RENDER_PX
        }).then(canvas => {
            const { jsPDF } = window.jspdf;
            const pdf = new jsPDF({ unit:'mm', format:'a4', orientation:'portrait', compress:true });
            // Crop any accidental blank rows produced by the hidden render container
            // before placing the BL on A4. This keeps the document flush to the top
            // instead of preserving invisible/empty vertical space.
            let cropTop = 0, cropBottom = canvas.height - 1;
            try {
                const ctx = canvas.getContext('2d', { willReadFrequently: true });
                const pixels = ctx.getImageData(0, 0, canvas.width, canvas.height).data;
                const rowHasContent = (y) => {
                    const start = y * canvas.width * 4;
                    const end = start + canvas.width * 4;
                    for (let i = start; i < end; i += 4) {
                        const r = pixels[i], g = pixels[i + 1], b = pixels[i + 2], a = pixels[i + 3];
                        if (a > 0 && (r < 248 || g < 248 || b < 248)) return true;
                    }
                    return false;
                };
                while (cropTop < canvas.height && !rowHasContent(cropTop)) cropTop++;
                while (cropBottom > cropTop && !rowHasContent(cropBottom)) cropBottom--;
            } catch (cropErr) {
                console.warn('BL PDF whitespace crop skipped:', cropErr);
            }

            const cropHeight = Math.max(1, cropBottom - cropTop + 1);
            const croppedCanvas = document.createElement('canvas');
            croppedCanvas.width = canvas.width;
            croppedCanvas.height = cropHeight;
            const cropCtx = croppedCanvas.getContext('2d');
            cropCtx.fillStyle = '#ffffff';
            cropCtx.fillRect(0, 0, croppedCanvas.width, croppedCanvas.height);
            cropCtx.drawImage(canvas, 0, cropTop, canvas.width, cropHeight, 0, 0, canvas.width, cropHeight);

            const imgData = croppedCanvas.toDataURL('image/jpeg', 0.98);
            const scale = Math.min(CONTENT_W_MM / croppedCanvas.width, CONTENT_H_MM / croppedCanvas.height);
            const imgW = croppedCanvas.width * scale;
            const imgH = croppedCanvas.height * scale;
            const x = MARGIN_MM + (CONTENT_W_MM - imgW) / 2;
            const y = MARGIN_MM;
            pdf.addImage(imgData, 'JPEG', x, y, imgW, imgH, undefined, 'FAST');
            pdf.save(`BL_${b.blNumber || 'Draft'}.pdf`);
            renderArea.style.cssText = 'position:fixed;left:-10000px;top:0;width:1000px;background:white;z-index:-1;padding:0;';
            renderArea.innerHTML = '';
        }).catch(err => {
            console.error(err);
            alert('PDF generation failed. Please try again.');
            renderArea.style.cssText = 'position:fixed;left:-10000px;top:0;width:1000px;background:white;z-index:-1;padding:0;';
            renderArea.innerHTML = '';
        });
    }, 400);
}


