function bulkExportLocalCharges() {
    if (typeof XLSX === 'undefined') {
        alert('XLSX library not loaded. Please refresh and try again.');
        return;
    }

    const wb = XLSX.utils.book_new();

    // Helper: flatten charges into rows
    function flattenCharges(base, chargesObj) {
        const rows = [];
        for (const [chargeName, chargeData] of Object.entries(chargesObj || {})) {
            rows.push({
                ...base,
                'Charge Name': chargeName,
                'Sell Amount': chargeData.amount || '',
                'Sell Currency': chargeData.currency || 'INR',
                'Buy Amount': chargeData.buyAmount || '',
                'Buy Currency': chargeData.buyCurrency || 'INR',
                'Basis': chargeData.basis || 'Normal'
            });
        }
        return rows;
    }

    // 1. Sea Default Charges
    let seaDefaultRows = [];
    db.defaultSeaCharges.forEach(r => {
        const base = {
            Carrier: r.carrier || 'ALL',
            POL: r.pol,
            Container: r.container || '',
            Commodity: r.commodity || ''
        };
        seaDefaultRows = seaDefaultRows.concat(flattenCharges(base, r.charges));
    });
    if (seaDefaultRows.length) {
        const ws = XLSX.utils.json_to_sheet(seaDefaultRows);
        XLSX.utils.book_append_sheet(wb, ws, 'Sea Default');
    }

    // 2. Air Default Charges
    let airDefaultRows = [];
    db.defaultAirCharges.forEach(r => {
        const base = {
            POL: r.pol,
            Commodity: r.commodity || ''
        };
        airDefaultRows = airDefaultRows.concat(flattenCharges(base, r.charges));
    });
    if (airDefaultRows.length) {
        const ws = XLSX.utils.json_to_sheet(airDefaultRows);
        XLSX.utils.book_append_sheet(wb, ws, 'Air Default');
    }

    // 3. LCL Default Charges
    let lclDefaultRows = [];
    db.defaultLclCharges.forEach(r => {
        const base = {
            POL: r.pol,
            Commodity: r.commodity || ''
        };
        lclDefaultRows = lclDefaultRows.concat(flattenCharges(base, r.charges));
    });
    if (lclDefaultRows.length) {
        const ws = XLSX.utils.json_to_sheet(lclDefaultRows);
        XLSX.utils.book_append_sheet(wb, ws, 'Lcl Default');
    }

    // 4. Carrier Sea/Lcl
    let carrierSLRows = [];
    db.carrierChargesSeaLcl.forEach(r => {
        const base = {
            Mode: r.mode || 'sea',
            Carrier: r.carrier,
            POL: r.pol,
            Container: r.container || '',
            Commodity: r.commodity || ''
        };
        carrierSLRows = carrierSLRows.concat(flattenCharges(base, r.charges));
    });
    if (carrierSLRows.length) {
        const ws = XLSX.utils.json_to_sheet(carrierSLRows);
        XLSX.utils.book_append_sheet(wb, ws, 'Carrier Sea/Lcl');
    }

    // 5. Carrier Air
    let carrierAirRows = [];
    db.carrierChargesAir.forEach(r => {
        const base = {
            Carrier: r.carrier,
            POL: r.pol,
            Commodity: r.commodity || ''
        };
        carrierAirRows = carrierAirRows.concat(flattenCharges(base, r.charges));
    });
    if (carrierAirRows.length) {
        const ws = XLSX.utils.json_to_sheet(carrierAirRows);
        XLSX.utils.book_append_sheet(wb, ws, 'Carrier Air');
    }

    XLSX.writeFile(wb, `LocalCharges_Backup_${new Date().toISOString().split('T')[0]}.xlsx`);
    alert('✅ Export completed! Each charge is now a separate row.');
}

function bulkImportLocalCharges(input) {
    if (!input.files || !input.files[0]) return;
    const file = input.files[0];
    const reader = new FileReader();
    reader.onload = function(e) {
        try {
            const data = new Uint8Array(e.target.result);
            const workbook = XLSX.read(data, { type: 'array' });
            let updated = 0;

            // Helper: read sheet and group rows by base fields, building charges object
            function processSheet(sheetName, baseFields, mode) {
                const sheet = workbook.Sheets[sheetName];
                if (!sheet) return [];
                const rows = XLSX.utils.sheet_to_json(sheet);
                if (!rows.length) return [];

                // Group by a composite key of base fields
                const groups = {};
                rows.forEach(row => {
                    // Build key from base fields
                    const key = baseFields.map(f => row[f] || '').join('||');
                    if (!groups[key]) {
                        groups[key] = {};
                        baseFields.forEach(f => groups[key][f] = row[f] || '');
                        groups[key].charges = {};
                    }
                    const chargeName = row['Charge Name'];
                    if (chargeName) {
                        groups[key].charges[chargeName] = {
                            amount: parseFloat(row['Sell Amount']) || 0,
                            currency: row['Sell Currency'] || 'INR',
                            buyAmount: parseFloat(row['Buy Amount']) || 0,
                            buyCurrency: row['Buy Currency'] || 'INR',
                            basis: row['Basis'] || 'Normal'
                        };
                    }
                });
                return Object.values(groups);
            }

            // Merge imported groups into existing masters. Existing records are
            // never replaced or deleted; only matching imported charge fields are updated.
            const normImport = v => String(v ?? '').trim().replace(/\s+/g, ' ').toUpperCase();
            function mergeImportRecords(target, incoming, keyFields, makeRecord) {
                if (!Array.isArray(target)) target = [];
                incoming.forEach(group => {
                    const incomingKey = keyFields.map(f => normImport(group[f])).join('||');
                    let existingIndex = target.findIndex(rec =>
                        keyFields.map(f => normImport(rec[f])).join('||') === incomingKey
                    );
                    if (existingIndex < 0) {
                        target.push(makeRecord(group));
                    } else {
                        const existing = target[existingIndex];
                        existing.charges = { ...(existing.charges || {}), ...(group.charges || {}) };
                        if (existing.updated !== undefined) existing.updated = new Date().toISOString();
                        if (existing.updatedAt !== undefined) existing.updatedAt = new Date().toISOString();
                    }
                });
                return target;
            }

            // 1. Sea Default — MERGE, never overwrite old records.
            const seaDefaults = processSheet('Sea Default', ['Carrier', 'POL', 'Container', 'Commodity']);
            if (seaDefaults.length) {
                db.defaultSeaCharges = mergeImportRecords(
                    db.defaultSeaCharges,
                    seaDefaults,
                    ['carrier', 'pol', 'container', 'commodity'],
                    g => ({
                        carrier: g.Carrier || 'ALL',
                        pol: g.POL || '',
                        container: g.Container || '',
                        commodity: g.Commodity || '',
                        charges: { ...(g.charges || {}) }
                    })
                );
                updated += seaDefaults.length;
            }

            // 2. Air Default — MERGE, never overwrite old records.
            const airDefaults = processSheet('Air Default', ['POL', 'Commodity']);
            if (airDefaults.length) {
                db.defaultAirCharges = mergeImportRecords(
                    db.defaultAirCharges,
                    airDefaults,
                    ['pol', 'commodity'],
                    g => ({
                        pol: g.POL || '',
                        commodity: g.Commodity || '',
                        charges: { ...(g.charges || {}) }
                    })
                );
                updated += airDefaults.length;
            }

            // 3. LCL Default — MERGE, never overwrite old records.
            const lclDefaults = processSheet('Lcl Default', ['POL', 'Commodity']);
            if (lclDefaults.length) {
                db.defaultLclCharges = mergeImportRecords(
                    db.defaultLclCharges,
                    lclDefaults,
                    ['pol', 'commodity'],
                    g => ({
                        pol: g.POL || '',
                        commodity: g.Commodity || '',
                        charges: { ...(g.charges || {}) }
                    })
                );
                updated += lclDefaults.length;
            }

            // 4. Carrier Sea/Lcl — MERGE, never overwrite old records.
            const carrierSL = processSheet('Carrier Sea/Lcl', ['Mode', 'Carrier', 'POL', 'Container', 'Commodity']);
            if (carrierSL.length) {
                db.carrierChargesSeaLcl = mergeImportRecords(
                    db.carrierChargesSeaLcl,
                    carrierSL,
                    ['mode', 'carrier', 'pol', 'container', 'commodity'],
                    g => ({
                        mode: g.Mode || 'sea',
                        carrier: g.Carrier || '',
                        pol: g.POL || '',
                        container: g.Container || '',
                        commodity: g.Commodity || '',
                        charges: { ...(g.charges || {}) },
                        updated: new Date().toISOString()
                    })
                );
                updated += carrierSL.length;
            }

            // 5. Carrier Air — MERGE, never overwrite old records.
            const carrierAir = processSheet('Carrier Air', ['Carrier', 'POL', 'Commodity']);
            if (carrierAir.length) {
                db.carrierChargesAir = mergeImportRecords(
                    db.carrierChargesAir,
                    carrierAir,
                    ['carrier', 'pol', 'commodity'],
                    g => ({
                        carrier: g.Carrier || '',
                        pol: g.POL || '',
                        commodity: g.Commodity || '',
                        charges: { ...(g.charges || {}) },
                        updated: new Date().toISOString()
                    })
                );
                updated += carrierAir.length;
            }

            saveDB();
            alert(`✅ Import successful! ${updated} charge groups updated.`);
            
            // Refresh the local tabs if visible
            ['sealocal', 'airlocal', 'lcllocal'].forEach(tab => {
                const panel = document.getElementById(tab);
                if (panel && panel.classList.contains('active')) {
                    const mode = tab === 'sealocal' ? 'sea' : tab === 'airlocal' ? 'air' : 'lcl';
                    renderDefaultChargesMaster(mode);
                    renderCarrierChargesMaster(mode === 'sea' ? 'sealcl' : mode);
                }
            });
            autoBackup();
        } catch (err) {
            alert('❌ Import failed: ' + err.message);
            console.error(err);
        }
    };
    reader.readAsArrayBuffer(file);
    input.value = '';
}
// ============================================================
// BULK EXPORT / IMPORT – LOCAL CHARGES (SEA, AIR, LCL)
// ============================================================

// ---------- 1. Export Default Charges ----------
// ============================================================================
// LOCAL CHARGES IMPORT / EXPORT — STANDARDIZED ROUND-TRIP FORMAT
// IMPORTANT: This block is isolated to Local Charges only.
// Existing quotation/rate-sheet/preview/PDF logic is not changed.
// Currency rule: value containing "$" = USD; otherwise = INR.
// ============================================================================

function lcNormalize(value) {
    return String(value ?? '').trim().replace(/\s+/g, ' ').toUpperCase();
}

function lcParseMoney(value) {
    if (value === undefined || value === null || String(value).trim() === '') return null;
    const raw = String(value).trim();
    const currency = raw.includes('$') ? 'USD' : 'INR';
    const numeric = raw.replace(/,/g, '').replace(/[^0-9.\-]/g, '');
    const amount = parseFloat(numeric);
    if (!Number.isFinite(amount)) return null;
    return { amount, currency };
}

function lcFormatMoney(val) {
    if (!val || val.amount === undefined || val.amount === null || val.amount === '') return '';
    const n = Number(val.amount);
    if (!Number.isFinite(n)) return '';
    return val.currency === 'USD' ? `$${n}` : `${n}`;
}

function lcDateOnly(value) {
    if (!value) return '';
    const d = new Date(value);
    if (Number.isNaN(d.getTime())) return String(value).slice(0, 10);
    return d.toISOString().slice(0, 10);
}

function lcValidateDates(row, rowNo, errors, warnings) {
    const from = String(row['VALID FROM'] ?? '').trim();
    const to = String(row['VALID TO'] ?? '').trim();
    if (!from) warnings.push(`Row ${rowNo}: VALID FROM is missing.`);
    if (!to) warnings.push(`Row ${rowNo}: VALID TO is missing.`);
    if (from && Number.isNaN(new Date(from).getTime())) errors.push(`Row ${rowNo}: invalid VALID FROM.`);
    if (to && Number.isNaN(new Date(to).getTime())) errors.push(`Row ${rowNo}: invalid VALID TO.`);
    if (from && to && new Date(from) > new Date(to)) errors.push(`Row ${rowNo}: VALID FROM is after VALID TO.`);
}

function lcDefaultColumns(mode) {
    if (mode === 'sea') {
        return ['CFS','CLEARANCE','HAZ STCKER','LASHING & CHOKING','LOLO','ON WHEEL','OTHER LOCALS','TOLL','VGM'];
    }
    // AIR/LCL use the existing charge master names so no existing charge is lost.
    const arr = getDefaultChargeTypes(mode) || [];
    return [...new Set(arr.map(String))];
}

function lcCarrierColumns(mode) {
    if (mode === 'sea') return ['SEAL','MUC','DOCS','SEAWAY BL','ETS','HAZ DOCS','AMS'];
    return getHorizontalChargeColumns(mode).slice();
}

function lcGetDefaultRecords(mode) {
    if (mode === 'sea') return db.defaultSeaCharges || [];
    if (mode === 'air') return db.defaultAirCharges || [];
    return db.defaultLclCharges || [];
}

function lcGetCarrierRecords(mode) {
    if (mode === 'air') return db.carrierChargesAir || [];
    return (db.carrierChargesSeaLcl || []).filter(r => r.mode === mode);
}

function lcDefaultValue(rec, charge, container) {
    const c = container === '20 GP' ? rec.charges?.[charge + '_20'] :
              container === '40 GP' || container === '40 HC' ? rec.charges?.[charge + '_40'] :
              rec.charges?.[charge];
    return c || null;
}

function lcContainerRowsForDefault(mode, rec) {
    if (mode !== 'sea') return [{ container: 'ALL', currency: null, charges: rec.charges || {} }];
    const explicit = String(rec.container || '').trim().toUpperCase();
    if (explicit && explicit !== 'ALL' && explicit !== 'ALL / GENERAL') {
        const container = explicit.includes('20') ? '20 GP' : explicit.includes('40 HC') || explicit === '40HQ' ? '40 HC' : explicit.includes('40 GP') ? '40 GP' : explicit;
        const charges = {};
        lcDefaultColumns(mode).forEach(col => {
            const direct = rec.charges?.[col];
            const suffixed = container === '20 GP' ? rec.charges?.[col + '_20'] : (container === '40 GP' || container === '40 HC') ? rec.charges?.[col + '_40'] : null;
            const v = direct || suffixed;
            if (v) charges[col] = v;
        });
        return [{ container, charges }];
    }
    const containers = [];
    const keys = Object.keys(rec.charges || {});
    if (keys.some(k => k.endsWith('_20'))) containers.push('20 GP');
    if (keys.some(k => k.endsWith('_40'))) containers.push('40 HC');
    if (!containers.length) containers.push('ALL');
    return containers.map(container => {
        const charges = {};
        lcDefaultColumns(mode).forEach(col => {
            const v = lcDefaultValue(rec, col, container);
            if (v) charges[col] = v;
        });
        return { container, charges };
    });
}

// --------------------------- STANDARDIZED LOCAL CHARGES IMPORT / EXPORT -------------------------------
// Two workbooks are used by the four buttons:
// 1) Export/Import Default  -> SEA - DEFAULT CHARGES, AIR - DEFAULT CHARGES, LCL - DEFAULT CHARGES
// 2) Export/Import Carrier  -> SEA - LOCAL CHARGES, SEA - THC, AIR - LOCAL CHARGES, LCL - LOCAL CHARGES
// Exported workbooks are directly reusable as import templates with identical sheet/column structures.

function lcEnsureXLSX(){
    if(typeof XLSX==='undefined'){ alert('XLSX library not loaded. Please refresh and try again.'); return false; }
    return true;
}
function lcMoneyForCurrency(v,currency){
    if(!v) return '';
    const cur=String(v.currency||'INR').toUpperCase();
    return cur===currency ? lcFormatMoney(v) : '';
}
function lcCreateSheet(rows, fallback){
    return XLSX.utils.json_to_sheet(rows.length ? rows : [fallback]);
}

// ============================ DEFAULT EXPORT ============================
// Default Charges currency is determined PER CELL.
// A value containing "$" is USD; any numeric value without "$" is INR.
// No Currency column and no separate INR/USD rows are used.
function bulkExportDefaultCharges(){
    if(!lcEnsureXLSX()) return;
    const wb=XLSX.utils.book_new();
    ['sea','air','lcl'].forEach(mode=>{
        const records=lcGetDefaultRecords(mode)||[];
        const columns=lcDefaultColumns(mode);
        const rows=[];
        records.forEach(rec=>{
            lcContainerRowsForDefault(mode,rec).forEach(group=>{
                const row={
                    MODE:mode.toUpperCase(),
                    POL:rec.pol||'',
                    'HAZ / NON HAZ':rec.commodity||'',
                    CONTAINER:group.container||'ALL',
                    'VALID FROM':rec.validFrom||'',
                    'VALID TO':rec.validTo||''
                };
                columns.forEach(col=>{
                    const v=group.charges?.[col];
                    // Preserve the exact currency indicator in every individual cell.
                    row[col]=v ? lcFormatMoney(v) : '';
                });
                rows.push(row);
            });
        });
        const fallback={
            MODE:mode.toUpperCase(), POL:'', 'HAZ / NON HAZ':'',
            CONTAINER:mode==='sea'?'20 GP':'ALL', 'VALID FROM':'','VALID TO':''
        };
        columns.forEach(c=>fallback[c]='');
        XLSX.utils.book_append_sheet(
            wb,
            lcCreateSheet(rows,fallback),
            `${mode.toUpperCase()} - DEFAULT CHARGES`
        );
    });
    XLSX.writeFile(wb,`LOCAL_CHARGES_DEFAULT_${new Date().toISOString().slice(0,10)}.xlsx`);
    alert('✅ Default Charges exported with 3 separate sheets.\n\nCurrency is cell-based: values containing $ are USD; values without $ are INR.\nNo Currency column or separate INR/USD rows are used.\n\nThe same workbook can be imported directly with Import Default.');
}

// ============================ DEFAULT IMPORT =============================
function bulkImportDefaultCharges(input){
    const file=input.files?.[0];
    if(!file)return alert('Please select an Excel file.');
    if(!lcEnsureXLSX())return;
    const reader=new FileReader();
    reader.onload=function(e){
        try{
            const wb=XLSX.read(new Uint8Array(e.target.result),{type:'array',cellDates:true});
            const sheetNames=['SEA - DEFAULT CHARGES','AIR - DEFAULT CHARGES','LCL - DEFAULT CHARGES'];
            const plan=[];
            const errors=[];
            const seen=new Set();
            sheetNames.forEach(sheetName=>{
                const sheet=wb.Sheets[sheetName]; if(!sheet)return;
                const mode=sheetName.startsWith('SEA')?'sea':sheetName.startsWith('AIR')?'air':'lcl';
                const rows=XLSX.utils.sheet_to_json(sheet,{defval:'',raw:false});
                const cols=lcDefaultColumns(mode);
                rows.forEach((row,i)=>{
                    const n=i+2, pol=lcNormalize(row.POL), haz=lcNormalize(row['HAZ / NON HAZ']);
                    const raw=lcNormalize(row.CONTAINER)||'ALL';
                    const container=mode==='sea'?(raw==='20GP'?'20 GP':raw==='40GP'?'40 GP':raw==='40HC'?'40 HC':raw):'ALL';
                    if(!pol||!['HAZ','NON HAZ'].includes(haz))return errors.push(`${sheetName} row ${n}: POL and HAZ/NON HAZ are required.`);
                    const key=`${mode}|${pol}|${haz}|${container}`;
                    if(seen.has(key))return errors.push(`${sheetName} row ${n}: duplicate key ${key}.`);
                    seen.add(key);
                    const charges={};
                    cols.forEach(col=>{
                        const rawVal=row[col];
                        if(rawVal!==undefined&&String(rawVal).trim()!==''){
                            const v=lcParseMoney(rawVal);
                            if(!v)errors.push(`${sheetName} row ${n}: invalid amount in ${col}.`);
                            else charges[col]=v;
                        }
                    });
                    plan.push({mode,pol,haz,container,charges,validFrom:String(row['VALID FROM']||''),validTo:String(row['VALID TO']||'')});
                });
            });
            if(!plan.length)throw new Error('No supported Default Charges rows found.');
            if(errors.length)throw new Error(errors.slice(0,30).join('\n'));
            if(!confirm(`Import ${plan.length} Default Charges row(s) into Local Charges? Existing matching records will be updated/merged.`))return;

            let added=0,updated=0;
            plan.forEach(item=>{
                const arr=item.mode==='sea'?db.defaultSeaCharges:item.mode==='air'?db.defaultAirCharges:db.defaultLclCharges;
                const itemContainer=item.mode==='sea'?item.container:'ALL';
                let rec=arr.find(r=>!r.deleted&&lcNormalize(r.pol)===item.pol&&lcNormalize(r.commodity)===item.haz&&lcNormalize(r.container||'ALL')===itemContainer);
                if(!rec){rec={mode:item.mode,pol:item.pol,commodity:item.haz,container:itemContainer,charges:{},createdAt:new Date().toISOString()};arr.push(rec);added++;}
                else updated++;
                // Excel import is authoritative for the matched record.
                // Do not merge imported charges with existing/default charges.
                const importedCharges={};
                Object.entries(item.charges).forEach(([k,v])=>{
                    const suffix=item.mode==='sea'?(item.container==='20 GP'?'_20':item.container==='40 GP'||item.container==='40 HC'?'_40':''):'';
                    importedCharges[k+suffix]={...v,buyAmount:v.amount,buyCurrency:v.currency};
                });
                rec.charges=importedCharges;
                // Excel validity fields are authoritative; blank clears the old value.
                rec.validFrom=item.validFrom||'';
                rec.validTo=item.validTo||'';
                rec.deleted=false;delete rec.deletedAt;const now=new Date().toISOString();rec.updated=now;rec.updatedAt=now;
            });
            saveDB();renderDefaultChargesMaster(currentLocalTab||'sea');autoBackup();
            alert(`✅ Default Charges imported successfully.\nAdded: ${added}\nUpdated/Merged: ${updated}`);
        }catch(err){console.error(err);alert('❌ Default Charges import failed:\n'+err.message);}
        finally{input.value='';}
    };
    reader.readAsArrayBuffer(file);
}

// ============================ CARRIER EXPORT =============================
function bulkExportCarrierCharges(){
    if(!lcEnsureXLSX()) return;
    const wb=XLSX.utils.book_new();
    const modes=[
        {mode:'sea',sheet:'SEA - LOCAL CHARGES'},
        {mode:'air',sheet:'AIR - LOCAL CHARGES'},
        {mode:'lcl',sheet:'LCL - LOCAL CHARGES'}
    ];
    modes.forEach(({mode,sheet})=>{
        const records=(lcGetCarrierRecords(mode)||[]).filter(r=>!r.deleted);
        const columns=lcCarrierColumns(mode);
        const rows=[];
        records.forEach(rec=>{
            const row={
                MODE:mode.toUpperCase(),
                CARRIER:rec.carrier||'',
                POL:rec.pol||'',
                CARGO:rec.commodity||'',
                CONTAINER:rec.container||'ALL',
                KEY:rec.key||[rec.carrier||'',rec.pol||'',rec.commodity||'',rec.container||'ALL'].map(v=>String(v).trim().replace(/\s+/g,' ').toUpperCase()).join('|'),
                'VALID FROM':rec.validFrom||'',
                'VALID TO':rec.validTo||''
            };
            columns.forEach(col=>row[col]=rec.charges?.[col]?lcFormatMoney(rec.charges[col]):'');
            rows.push(row);
        });
        const fallback={MODE:mode.toUpperCase(),CARRIER:'',POL:'',CARGO:'NON HAZ',CONTAINER:'ALL',KEY:'','VALID FROM':'','VALID TO':''};
        columns.forEach(c=>fallback[c]='');
        XLSX.utils.book_append_sheet(wb,lcCreateSheet(rows,fallback),sheet);
    });
    const thcRows=(db.seaTHCRates||[]).filter(r=>!r.deleted).map(r=>({
        MODE:'SEA',CARRIER:r.carrier||'',POL:r.pol||'',CARGO:r.commodity||'',CONTAINER:r.container||'ALL',
        KEY:[r.carrier||'',r.pol||'',r.commodity||'',r.container||'ALL'].map(v=>String(v).trim().replace(/\s+/g,' ').toUpperCase()).join('|'),
        CURRENCY:r.currency||'INR','THC 20 GP':r.thc20??'','THC 40 HC':r.thc40??'','VALID FROM':r.validFrom||'','VALID TO':r.validTo||''
    }));
    XLSX.utils.book_append_sheet(wb,lcCreateSheet(thcRows,{MODE:'SEA',CARRIER:'',POL:'',CARGO:'HAZ',CONTAINER:'ALL',KEY:'',CURRENCY:'INR','THC 20 GP':'','THC 40 HC':'','VALID FROM':'','VALID TO':''}),'SEA - THC');
    XLSX.writeFile(wb,`LOCAL_CHARGES_CARRIER_${new Date().toISOString().slice(0,10)}.xlsx`);
    alert('✅ Carrier/Local Charges exported. The same workbook can be imported directly with Import Carrier.');
}

// ============================ CARRIER IMPORT =============================
function bulkImportCarrierCharges(input){
    if(!input.files||!input.files[0]) return alert('Please select an Excel file.');
    if(!lcEnsureXLSX()) return;
    const file=input.files[0];
    const reader=new FileReader();
    reader.onload=function(e){
        try{
            const wb=XLSX.read(new Uint8Array(e.target.result),{type:'array',cellDates:true});
            const errors=[],warnings=[],plan=[];
            const stats={new:0,merged:0,duplicates:0,values:0};
            const modeSheets={sea:'SEA - LOCAL CHARGES',air:'AIR - LOCAL CHARGES',lcl:'LCL - LOCAL CHARGES'};
            let sheetsProcessed=0;
            Object.entries(modeSheets).forEach(([mode,sheetName])=>{
                const sheet=wb.Sheets[sheetName];
                if(!sheet){warnings.push(`Missing sheet: ${sheetName}`);return;}
                sheetsProcessed++;
                const rows=XLSX.utils.sheet_to_json(sheet,{defval:'',raw:false});
                if(!rows.length){warnings.push(`${sheetName}: no data rows.`);return;}
                const required=['MODE','CARRIER','POL','CARGO','CONTAINER'];
                const headers=Object.keys(rows[0]);
                required.filter(h=>!headers.includes(h)).forEach(h=>errors.push(`${sheetName}: missing column ${h}`));
                if(required.some(h=>!headers.includes(h))) return;
                const columns=lcCarrierColumns(mode), seen=new Set();
                rows.forEach((row,i)=>{
                    const n=i+2, rowMode=lcNormalize(row.MODE).toLowerCase(), carrier=lcNormalize(row.CARRIER), pol=lcNormalize(row.POL), cargo=lcNormalize(row.CARGO), container=lcNormalize(row.CONTAINER)||'ALL';
                    if(rowMode!==mode) errors.push(`${sheetName} Row ${n}: MODE must be ${mode.toUpperCase()}.`);
                    if(!carrier) errors.push(`${sheetName} Row ${n}: CARRIER is missing.`);
                    if(!['HAZ','NON HAZ'].includes(cargo)) errors.push(`${sheetName} Row ${n}: CARGO must be HAZ or NON HAZ.`);
                    lcValidateDates(row,n,errors,warnings);
                    const parsed={};
                    columns.forEach(col=>{
                        const cell=row[col];
                        if(cell===undefined||cell===null||String(cell).trim()==='') return;
                        const v=lcParseMoney(cell);
                        if(!v) errors.push(`${sheetName} Row ${n}: invalid amount in ${col} (${cell}).`);
                        else {parsed[col]=v;stats.values++;}
                    });
                    const key=[mode,carrier,pol,cargo,container].join('|');
                    if(seen.has(key)) errors.push(`${sheetName} Row ${n}: duplicate import key ${key}.`);
                    seen.add(key);
                    const suppliedKey=String(row.KEY||'').trim();
                    if(suppliedKey){
                        const expected=[carrier,pol,cargo,container].join('|');
                        if(suppliedKey.toUpperCase().replace(/\s+/g,' ')!==expected.toUpperCase().replace(/\s+/g,' '))
                            errors.push(`${sheetName} Row ${n}: KEY does not match Carrier/POL/Cargo/Container.`);
                    }
                    plan.push({mode,carrier,pol,cargo,container,parsed,validFrom:String(row['VALID FROM']||'').trim(),validTo:String(row['VALID TO']||'').trim()});
                });
            });

            const thcSheet=wb.Sheets['SEA - THC'];
            if(thcSheet){
                sheetsProcessed++;
                const rows=XLSX.utils.sheet_to_json(thcSheet,{defval:'',raw:false});
                const seen=new Set();
                if(rows.length){
                    const required=['MODE','CARRIER','POL','CARGO','CONTAINER','CURRENCY','THC 20 GP','THC 40 HC'];
                    const headers=Object.keys(rows[0]);
                    required.filter(h=>!headers.includes(h)).forEach(h=>errors.push(`SEA - THC: missing column ${h}`));
                    rows.forEach((row,i)=>{
                        const n=i+2,mode=lcNormalize(row.MODE).toLowerCase(),carrier=lcNormalize(row.CARRIER),pol=lcNormalize(row.POL),cargo=lcNormalize(row.CARGO),container=lcNormalize(row.CONTAINER)||'ALL',currency=lcNormalize(row.CURRENCY);
                        if(mode!=='sea')errors.push(`SEA - THC Row ${n}: MODE must be SEA.`);
                        if(!carrier)errors.push(`SEA - THC Row ${n}: CARRIER is missing.`);
                        if(!pol)errors.push(`SEA - THC Row ${n}: POL is missing.`);
                        if(!['HAZ','NON HAZ'].includes(cargo))errors.push(`SEA - THC Row ${n}: CARGO must be HAZ or NON HAZ.`);
                        if(!['INR','USD'].includes(currency))errors.push(`SEA - THC Row ${n}: CURRENCY must be INR or USD.`);
                        const v20=lcParseMoney(row['THC 20 GP']),v40=lcParseMoney(row['THC 40 HC']);
                        if(!v20&&!v40)warnings.push(`SEA - THC Row ${n}: no THC value found.`);
                        if(v20&&v20.currency!==currency)errors.push(`SEA - THC Row ${n}: THC 20 GP currency mismatch.`);
                        if(v40&&v40.currency!==currency)errors.push(`SEA - THC Row ${n}: THC 40 HC currency mismatch.`);
                        lcValidateDates(row,n,errors,warnings);
                        const key=[carrier,pol,cargo,container,currency].join('|');
                        if(seen.has(key))errors.push(`SEA - THC Row ${n}: duplicate import key ${key}.`);
                        seen.add(key);
                        plan.push({thc:true,carrier,pol,cargo,container,currency,v20,v40,validFrom:String(row['VALID FROM']||'').trim(),validTo:String(row['VALID TO']||'').trim()});
                    });
                }else warnings.push('SEA - THC: no data rows.');
            }else warnings.push('Missing sheet: SEA - THC');

            if(!sheetsProcessed)throw new Error('No recognized Carrier/Local Charge sheets found.');
            if(errors.length){alert(`❌ Import Carrier validation failed.\n\n${errors.slice(0,30).join('\n')}${errors.length>30?'\n...more errors':''}`);return;}

            // Apply only after every sheet has validated successfully.
            plan.forEach(item=>{
                const now=new Date().toISOString();
                if(item.thc){
                    const arr=db.seaTHCRates||(db.seaTHCRates=[]);
                    let rec=arr.find(r=>!r.deleted&&normSafe(r.carrier)===item.carrier&&normSafe(r.pol)===item.pol&&normSafe(r.commodity)===item.cargo&&normSafe(r.container||'ALL')===item.container&&normSafe(r.currency)===item.currency);
                    if(!rec){rec={mode:'sea',carrier:item.carrier,pol:item.pol,commodity:item.cargo,container:item.container,currency:item.currency,thc20:null,thc40:null,validFrom:'',validTo:'',updated:now};arr.push(rec);stats.new++;}
                    else stats.merged++;
                    if(item.v20)rec.thc20=item.v20.amount;
                    if(item.v40)rec.thc40=item.v40.amount;
                    if(item.validFrom)rec.validFrom=item.validFrom;
                    if(item.validTo)rec.validTo=item.validTo;
                    rec.key=[item.carrier,item.pol,item.cargo,item.container].join('|');
                    rec.deleted=false; delete rec.deletedAt; rec.updated=now; rec.updatedAt=now;
                }else{
                    const arr=item.mode==='air'?(db.carrierChargesAir||(db.carrierChargesAir=[])):(db.carrierChargesSeaLcl||(db.carrierChargesSeaLcl=[]));
                    let rec=arr.find(r=>!r.deleted&&(item.mode==='air'||r.mode===item.mode)&&normSafe(r.carrier)===item.carrier&&normSafe(r.pol||'')===item.pol&&normSafe(r.commodity)===item.cargo&&normSafe(r.container||'ALL')===item.container);
                    if(!rec){rec={carrier:item.carrier,pol:item.pol,commodity:item.cargo,container:item.container,charges:{},updated:now,updatedAt:now};if(item.mode!=='air')rec.mode=item.mode;arr.push(rec);stats.new++;}
                    else stats.merged++;
                    if(item.validFrom)rec.validFrom=item.validFrom;
                    if(item.validTo)rec.validTo=item.validTo;
                    Object.entries(item.parsed).forEach(([k,v])=>{rec.charges[k]={amount:v.amount,currency:v.currency,buyAmount:v.amount,buyCurrency:v.currency};});
                    rec.key=[item.carrier,item.pol,item.cargo,item.container].join('|');
                    rec.deleted=false; delete rec.deletedAt; rec.updated=now; rec.updatedAt=now;
                }
            });
            saveDB();
            if(typeof ensureSharedCarrierCharges==='function')ensureSharedCarrierCharges();
            renderCarrierChargesMaster(currentLocalTab==='sea'?'sealcl':currentLocalTab||'air');
            if(currentLocalTab==='sea')renderSeaTHCMaster();
            autoBackup();
            alert(`✅ Import Carrier completed.\nSheets processed: ${sheetsProcessed}/4\nNew records: ${stats.new}\nMerged/updated: ${stats.merged}\nCharge values: ${stats.values}\nWarnings: ${warnings.length}${warnings.length?'\n\n'+warnings.slice(0,10).join('\n'):''}`);
        }catch(err){console.error(err);alert('❌ Import Carrier failed: '+err.message);}
        finally{input.value='';}
    };
    reader.readAsArrayBuffer(file);
}
function normSafe(v){return String(v??'').trim().replace(/\s+/g,' ').toUpperCase();}


