/* Original source preserved from 17-backup-sync.js; assigned to this functional module without code changes. */
// ===== 1. selectBackupFolder – select folder, then choose auto-backup format =====
async function selectBackupFolder() {
    try {
        // Electron uses the native folder picker/IPC bridge. Do not use the
        // browser File System Access API inside the EXE runtime.
        if (window.electronAPI && typeof window.electronAPI.selectBackupFolder === 'function') {
            const folderPath = await window.electronAPI.selectBackupFolder();
            if (!folderPath) return;

            const check = typeof window.electronAPI.checkBackupFolder === 'function'
                ? await window.electronAPI.checkBackupFolder(folderPath)
                : { success: true, writable: true };

            if (!check || check.success !== true || check.writable !== true) {
                throw new Error(check?.error || 'Selected folder is not writable.');
            }

            db.backupFolderPath = folderPath;
            saveDB();

            const displayEl = document.getElementById('backup-folder-path');
            if (displayEl) displayEl.textContent = `📁 ${folderPath} (authorized)`;
            const inputEl = document.getElementById('backup-folder-path-input');
            if (inputEl) inputEl.value = folderPath;

            showBackupFormatChoice({ name: folderPath, path: folderPath });
            return;
        }

        if (!window.showDirectoryPicker) {
            alert('Your browser does not support the File System Access API. Please use Chrome or Edge.');
            return;
        }

        const handle = await window.showDirectoryPicker({ mode: 'readwrite' });

        // Permission requests are allowed here because this function is
        // triggered directly by the user's Browse Folder click.
        if (typeof handle.requestPermission === 'function') {
            const permission = await handle.requestPermission({ mode: 'readwrite' });
            if (permission !== 'granted') {
                throw new Error('Backup folder permission was not granted.');
            }
        }

        backupFolderHandle = handle;
        window.backupFolderHandle = handle;
        await storeFolderHandle(handle);

        db.backupFolderPath = handle.name;
        saveDB();

        const displayEl = document.getElementById('backup-folder-path');
        if (displayEl) displayEl.textContent = `📁 ${handle.name} (authorized)`;
        const inputEl = document.getElementById('backup-folder-path-input');
        if (inputEl) inputEl.value = handle.name;

        showBackupFormatChoice(handle);
    } catch (err) {
        if (err.name !== 'AbortError') {
            console.error('Folder selection error:', err);
            const statusEl = document.getElementById('backup-status');
            if (statusEl) {
                statusEl.textContent = `❌ Backup folder authorization failed: ${err.message}`;
                statusEl.className = 'backup-status error';
            }
            alert('Failed to select/authorize folder: ' + err.message);
        }
    }
}

// ===== Backup format choice after folder selection =====
