// ===== REPLACE autoBackupToFolder with this =====
async function autoBackupToFolder() {
    try {
        const folderHandle = backupFolderHandle || window.backupFolderHandle;

        if (!folderHandle) {
            console.warn('No browser folder handle available – backup skipped.');
            const statusEl = document.getElementById('backup-status');
            if (statusEl) {
                statusEl.textContent =
                    '⚠️ Local backup folder is not selected. Click "Browse Folder" to select.';
                statusEl.className = 'backup-status error';
            }
            return false;
        }

        backupFolderHandle = folderHandle;
        window.backupFolderHandle = folderHandle;

        const opts = { mode: 'readwrite' };
        // Automatic/background backups cannot call requestPermission(); the
        // File System Access API requires a user activation for that method.
        // Folder selection is responsible for obtaining permission.
        if (typeof folderHandle.queryPermission === 'function') {
            const permission = await folderHandle.queryPermission(opts);
            if (permission !== 'granted') {
                const statusEl = document.getElementById('backup-status');
                if (statusEl) {
                    statusEl.textContent = '⚠️ Backup authorization required. Click BROWSE FOLDER to re-authorize access.';
                    statusEl.className = 'backup-status error';
                }
                return false;
            }
        }

        const format = (db.backupFormat || 'json').toLowerCase();

        if (format === 'sqlite') {
            return await window.SHAHID_RUN_IMPORT_MERGE_EXPORT_NOW();
        }

        const fileName = 'SHAHID_ERP.json';
        const backupData = { timestamp: new Date().toISOString(), data: db };
        const jsonStr = JSON.stringify(backupData, null, 2);

        const fileHandle = await backupFolderHandle.getFileHandle(fileName, { create: true });
        const writable = await fileHandle.createWritable({ keepExistingData: false });
        await writable.write(jsonStr);
        await writable.close();

        db.lastBackup = new Date().toISOString();
        saveDB();

        const statusEl = document.getElementById('backup-status');
        if (statusEl) {
            statusEl.textContent = `✅ Last backup: ${new Date().toLocaleString('en-IN')} (saved to ${backupFolderHandle.name}/${fileName})`;
            statusEl.className = 'backup-status success';
        }
    } catch (e) {
        console.error('Folder backup failed:', e);
        const statusEl = document.getElementById('backup-status');
        if (statusEl) {
            statusEl.textContent = `❌ Backup failed: ${e.message}`;
            statusEl.className = 'backup-status error';
        }
    }
}



// ==== REPLACE fallbackBackupDownload ====
async function fallbackBackupDownload() {
    try {
        const backupData = { timestamp: new Date().toISOString(), data: db };
        const json = JSON.stringify(backupData, null, 2);
        const blob = new Blob([json], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'SHAHID_ERP.json';
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
        db.lastBackup = new Date().toISOString();
        saveDB();
        const statusEl = document.getElementById('backup-status');
        statusEl.textContent = `✅ Last backup: ${new Date().toLocaleString('en-IN')} (download fallback)`;
        statusEl.className = 'backup-status success';
    } catch (e) {
        console.error('Fallback download failed:', e);
        const statusEl = document.getElementById('backup-status');
        statusEl.textContent = `❌ Backup failed: ${e.message}`;
        statusEl.className = 'backup-status error';
    }
}

// ==== REPLACE autoBackup (the manual trigger) ====
async function autoBackup() {
    // Auto-backup is optional. If the user has not selected a backup
    // folder, silently skip the backup without affecting database operations.
    if (!backupFolderHandle) {
        return false;
    }

    const format = String(db?.backupFormat || 'json').toLowerCase();

    if (format === 'sqlite' && typeof window.SHAHID_RUN_IMPORT_MERGE_EXPORT_NOW === 'function') {
        return await window.SHAHID_RUN_IMPORT_MERGE_EXPORT_NOW();
    }

    return await autoBackupToFolder();
}


// ============ INDEXEDDB HELPERS (Robust) ============
function storeFolderHandle(handle) {
    return new Promise((resolve, reject) => {
        const request = indexedDB.open('GatewayEximBackup', 2); // version 2
        request.onupgradeneeded = function(e) {
            const db = e.target.result;
            if (!db.objectStoreNames.contains('handles')) {
                db.createObjectStore('handles', { keyPath: 'id' });
            }
        };
        request.onsuccess = function(e) {
            const db = e.target.result;
            try {
                const tx = db.transaction('handles', 'readwrite');
                const store = tx.objectStore('handles');
                const putReq = store.put({ id: 'folderHandle', handle: handle });
                putReq.onsuccess = () => resolve();
                putReq.onerror = () => reject(putReq.error);
                tx.oncomplete = () => db.close();
            } catch (err) {
                reject(err);
            }
        };
        request.onerror = () => reject(request.error);
    });
}

function getFolderHandle() {
    return new Promise((resolve) => {
        const request = indexedDB.open('GatewayEximBackup', 2);
        request.onupgradeneeded = function(e) {
            const db = e.target.result;
            if (!db.objectStoreNames.contains('handles')) {
                db.createObjectStore('handles', { keyPath: 'id' });
            }
        };
        request.onsuccess = function(e) {
            const db = e.target.result;
            // Check if the store exists before trying to access it
            if (!db.objectStoreNames.contains('handles')) {
                db.close();
                resolve(null);
                return;
            }
            try {
                const tx = db.transaction('handles', 'readonly');
                const store = tx.objectStore('handles');
                const getReq = store.get('folderHandle');
                getReq.onsuccess = () => {
                    db.close();
                    resolve(getReq.result ? getReq.result.handle : null);
                };
                getReq.onerror = () => {
                    db.close();
                    resolve(null);
                };
                tx.oncomplete = () => db.close();
            } catch (err) {
                db.close();
                resolve(null);
            }
        };
        request.onerror = () => resolve(null);
    });
}



// RATES REQUEST //

function parseRateRequestDisplayDate(value) {
    const raw = String(value || '').trim();
    if (!raw) return '';
    if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) return raw;
    const m = raw.match(/^(\d{1,2})\/([A-Za-z]{3})\/(\d{4})$/);
    if (!m) return raw;
    const months = {Jan:0,Feb:1,Mar:2,Apr:3,May:4,Jun:5,Jul:6,Aug:7,Sep:8,Oct:9,Nov:10,Dec:11};
    const mon = months[m[2].charAt(0).toUpperCase()+m[2].slice(1).toLowerCase()];
    const day = Number(m[1]), year = Number(m[3]);
    if (mon === undefined || day < 1 || day > 31) return raw;
    const d = new Date(Date.UTC(year, mon, day));
    if (d.getUTCFullYear() !== year || d.getUTCMonth() !== mon || d.getUTCDate() !== day) return raw;
    return `${year}-${String(mon+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;
}

function formatRateRequestDate(value) {
    const iso = parseRateRequestDisplayDate(value);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(iso)) return String(value || '').trim();
    const [y,m,d] = iso.split('-').map(Number);
    const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    return `${String(d).padStart(2,'0')}/${months[m-1]}/${y}`;
}

function formatRateRequestValidityField(el) {
    if (!el) return '';
    const formatted = formatRateRequestDate(el.value);
    if (formatted) {
        el.value = formatted;
        const m = String(el.id || '').match(/^rr-validity-(sea1|sea2|air)$/);
        if (m) {
            const picker = document.getElementById(`rr-validity-${m[1]}-picker`);
            if (picker) picker.value = parseRateRequestDisplayDate(formatted);
        }
    }
    return formatted;
}

function formatAllRateRequestValidityFields() {
    ['rr-validity-sea1','rr-validity-sea2','rr-validity-air'].forEach(id => {
        const el = document.getElementById(id);
        if (el && el.value) formatRateRequestValidityField(el);
    });
    syncAllRateRequestValidityPickers();
}

function getRateRequestValidityValue(id) {
    const el = document.getElementById(id);
    return el ? parseRateRequestDisplayDate(el.value) : '';
}

function syncRateRequestValidityPicker(suffix, picker) {
    if (!picker) return;
    const text = document.getElementById(`rr-validity-${suffix}`);
    if (!text) return;
    if (picker.value) {
        text.value = formatRateRequestDate(picker.value);
        text.dispatchEvent(new Event('change', { bubbles: true }));
    }
}

function syncAllRateRequestValidityPickers() {
    ['sea1','sea2','air'].forEach(suffix => {
        const text = document.getElementById(`rr-validity-${suffix}`);
        const picker = document.getElementById(`rr-validity-${suffix}-picker`);
        if (!text || !picker) return;
        const iso = parseRateRequestDisplayDate(text.value);
        if (/^\d{4}-\d{2}-\d{2}$/.test(iso)) picker.value = iso;
    });
}

function populateRateRequestDropdowns() {
    const master = getMasterDropdownLists();
    const hidden = db.hiddenItems || {};
    const pols = [...new Map((master.pol || []).filter(p => !(hidden.pol || []).includes(p)).map(v => [String(v).trim().toUpperCase(), v])).values()].sort();
    const pods = [...new Map((master.pod || []).filter(p => !(hidden.pod || []).includes(p)).map(v => [String(v).trim().toUpperCase(), v])).values()].sort();
    const containers = (master.containers || []).filter(c => !(hidden.containers || []).includes(c)).sort();
    const commodityOptions = ['NON HAZ', 'HAZ'];
    const inventoryOptions = [...new Set(['20 GP & 40 HC', '20 GP', '40 HC', ...containers])];
    const freeTimeOptions = ['14 Days', '21 Days'];
    const suffixes = ['sea1', 'sea2', 'air'];
    const setList = (id, values) => {
        const el = document.getElementById(id);
        if (el) el.innerHTML = [...new Set(values)].map(v => `<option value="${escapeHtml(v)}">`).join('');
    };
    suffixes.forEach(suffix => {
        setList(`rr-pol-list-${suffix}`, pols);
        setList(`rr-pod-list-${suffix}`, pods);
        setList(`rr-commodity-list-${suffix}`, commodityOptions);
        setList(`rr-inventory-list-${suffix}`, inventoryOptions);
        setList(`rr-freeTime-list-${suffix}`, freeTimeOptions);
    });
    const company = db.companyName || 'GATEWAY EXIM';
    ['rr-forwarder-sea1','rr-forwarder-sea2'].forEach(id => { const el=document.getElementById(id); if(el) el.value=company; });
    // Set the DEFAULT VALIDITY only when the field is empty.
    // Default follows the 30th / 14th validity-cycle schedule.
    // A manually selected date must never be overwritten during re-render,
    // format switching, or dropdown population.
    const defaultValidity = getRateRequestDefaultValidityDate();
    ['rr-validity-sea1','rr-validity-sea2'].forEach(id => {
        const el = document.getElementById(id);
        if (el && !el.value) el.value = defaultValidity;
    });
    ['rr-commodity-sea1','rr-commodity-sea2','rr-commodity-air'].forEach(id => { const el=document.getElementById(id); if(el && !el.value) el.value=''; });
    ['rr-inventory-sea1','rr-inventory-sea2'].forEach(id => { const el=document.getElementById(id); if(el && !el.value) el.value='20 GP & 40 HC'; });
    ['rr-freeTime-sea1','rr-freeTime-sea2'].forEach(id => { const el=document.getElementById(id); if(el && !el.value) el.value='14 Days'; });
    const clearance=document.getElementById('rr-clearance-air'); if(clearance && !clearance.value) clearance.value='INQUIRY';
    formatAllRateRequestValidityFields();
}

// Switch between formats
function switchRateRequestFormat(format) {
    currentRateRequestFormat = format;
    document.querySelectorAll('#raterequest .form-section[id^="rr-format-"]').forEach(el => el.style.display = 'none');
    const target = document.getElementById(`rr-format-${format}`);
    if (target) target.style.display = 'block';
    document.querySelectorAll('#raterequest .tab-heading .btn').forEach(btn => btn.classList.remove('active'));
    const btns = document.querySelectorAll('#raterequest .tab-heading .btn');
    const map = { 'seaWithShipper': 0, 'seaWithoutShipper': 1, 'air': 2 };
    if (map[format] !== undefined && btns[map[format]]) {
        btns[map[format]].classList.add('active');
    }
    populateRateRequestDropdowns();
}


function getRateRequestData(format) {
    // Determine mode based on format
    let mode = 'SEA';
    if (format === 'air') mode = 'AIR';

    const getVal = (id) => {
        const el = document.getElementById(id);
        const val = el ? el.value : '';
        return val;
    };
    const getSel = (id) => {
        const el = document.getElementById(id);
        const val = el ? el.value : '';
        return val;
    };

    let data = { format, mode };

    if (format === 'seaWithShipper') {
        data.shipper = getVal('rr-shipper');
        data.forwarder = getVal('rr-forwarder-sea1');
        data.pol = getVal('rr-pol-sea1');
        data.pod = getVal('rr-pod-sea1');
        data.commodity = getSel('rr-commodity-sea1');
        data.inventory = getSel('rr-inventory-sea1');
        data.weight = getVal('rr-weight-sea1');
        data.term = getSel('rr-term-sea1');
        data.validity = getRateRequestValidityValue('rr-validity-sea1');
        data.freeTime = getSel('rr-freeTime-sea1');
		data.remarks = getVal('rr-remarks-sea1');
    } else if (format === 'seaWithoutShipper') {
        data.forwarder = getVal('rr-forwarder-sea2');
        data.pol = getVal('rr-pol-sea2');
        data.pod = getVal('rr-pod-sea2');
        data.commodity = getSel('rr-commodity-sea2');
        data.inventory = getSel('rr-inventory-sea2');
        data.weight = getVal('rr-weight-sea2');
        data.term = getSel('rr-term-sea2');
        data.validity = getRateRequestValidityValue('rr-validity-sea2');
        data.freeTime = getSel('rr-freeTime-sea2');
		data.remarks = getVal('rr-remarks-sea2');
    } else if (format === 'air') {
        data.shipper = getVal('rr-shipper-air');
        data.pol = getVal('rr-pol-air');
        data.pod = getVal('rr-pod-air');
        data.clearance = getVal('rr-clearance-air');
        data.commodity = getVal('rr-commodity-air');
        data.inventory = getVal('rr-inventory-air');
        data.weight = getVal('rr-weight-air');
        data.validity = getRateRequestValidityValue('rr-validity-air');
        data.freeTime = getVal('rr-freeTime-air');
        data.packaging = getVal('rr-packaging-air');
        data.pallet = getSel('rr-pallet-air');
        data.dimension = getVal('rr-dimension-air');
        data.temp = getSel('rr-temp-air');
		data.remarks = getVal('rr-remarks-air');
    }
    return data;
}

function dedupeRateRequestRows(rows) {
    const seen = new Set();
    return (rows || []).filter(row => {
        const label = String(row?.[0] || '').trim().toUpperCase();
        if (!label) return true;
        if (seen.has(label)) return false;
        seen.add(label);
        return true;
    });
}

