(function () {
    if (window.__quoteRowPreviewBound) return;
    window.__quoteRowPreviewBound = true;

    document.addEventListener('click', function (event) {
        const row = event.target.closest('#rates-table tbody tr[data-quote]');
        if (!row) return;

        // Preserve existing controls/actions inside the row.
        if (event.target.closest('input, select, button, a, textarea, option')) return;

        let record;
        try {
            record = JSON.parse(row.getAttribute('data-quote') || '{}');
        } catch (_) {
            return;
        }

        const mode = record._mode;
        const idx = Number(record._idx);
        if (!mode || !Number.isInteger(idx) || typeof window.previewSavedRecord !== 'function') return;

        window.previewSavedRecord('rates', mode, idx);
    });
})();

