// ============================================================
// ELECTRON BACKUP OVERRIDE — NATIVE FOLDER ACCESS FIX
// ============================================================
(function() {
  if (typeof window.electronAPI === 'undefined') {
    console.log('Not running in Electron, using browser backup logic.');
    return;
  }

  console.log('✅ Electron detected. Using native backup bridge.');

  function setStatus(message, ok) {
    const el = document.getElementById('backup-status');
    if (!el) return;
    el.textContent = message;
    el.className = 'backup-status ' + (ok ? 'success' : 'error');
  }

  function setAutoStatus(message) {
    const el = document.getElementById('auto-backup-status');
    if (el) el.textContent = message;
  }

  function clearAutoBackupTimer() {
    if (window.autoBackupInterval) {
      clearInterval(window.autoBackupInterval);
      window.autoBackupInterval = null;
    }
    try { autoBackupInterval = null; } catch (_) {}
  }

  async function verifyNativeFolder(folderPath) {
    const path = String(folderPath || '').trim();
    if (!path) return { success: false, writable: false, error: 'Local backup folder is not configured.' };
    if (typeof window.electronAPI.checkBackupFolder !== 'function') {
      return { success: false, writable: false, error: 'Native backup bridge is incomplete. Restart/rebuild the EXE after updating the project.' };
    }
    return await window.electronAPI.checkBackupFolder(path);
  }

  window.selectBackupFolder = async function() {
    try {
      if (typeof window.electronAPI.selectBackupFolder !== 'function') {
        throw new Error('Native backup folder picker is unavailable.');
      }

      const folderPath = await window.electronAPI.selectBackupFolder();
      if (!folderPath) return false;

      const check = await verifyNativeFolder(folderPath);
      if (!check || check.success !== true || check.writable !== true) {
        throw new Error(check?.error || 'Selected folder is not writable.');
      }

      db.backupFolderPath = folderPath;
      saveDB();

      const inputEl = document.getElementById('backup-folder-path-input');
      const displayEl = document.getElementById('backup-folder-path');
      if (inputEl) inputEl.value = folderPath;
      if (displayEl) displayEl.textContent = `📁 ${folderPath} (authorized)`;

      // Keep the existing format choice workflow. Do not silently overwrite
      // the user's selected backup format.
      if (typeof showBackupFormatChoice === 'function') {
        await new Promise((resolve) => {
          const originalStatus = document.getElementById('backup-status');
          if (originalStatus) {
            originalStatus.textContent = `📁 ${folderPath} authorized — select backup format.`;
            originalStatus.className = 'backup-status success';
          }
          showBackupFormatChoice({ name: folderPath, path: folderPath });
          // The modal controls the actual backup start. Resolve on next tick so
          // this function never blocks the UI.
          setTimeout(resolve, 0);
        });
      } else {
        await startAutoBackup();
      }

      return true;
    } catch (err) {
      console.error('Native backup folder selection failed:', err);
      setStatus(`❌ Backup folder authorization failed: ${err.message}`, false);
      return false;
    }
  };

  window.saveBackupPath = async function() {
    const inputEl = document.getElementById('backup-folder-path-input');
    const folderPath = inputEl ? inputEl.value.trim() : '';
    if (!folderPath) {
      alert('Please enter or select a local backup folder.');
      return false;
    }

    try {
      const check = await verifyNativeFolder(folderPath);
      if (!check || check.success !== true || check.writable !== true) {
        setStatus(`⚠️ Backup folder is not accessible/writable: ${check?.error || 'authorization required'}`, false);
        clearAutoBackupTimer();
        setAutoStatus('⏸️ Auto backup paused — folder authorization required');
        return false;
      }

      db.backupFolderPath = folderPath;
      saveDB();
      const displayEl = document.getElementById('backup-folder-path');
      if (displayEl) displayEl.textContent = `📁 ${folderPath} (authorized)`;

      await startAutoBackup();
      alert('✅ Backup folder path verified and saved.');
      return true;
    } catch (error) {
      console.error('Saving backup path failed:', error);
      setStatus(`❌ Backup path validation failed: ${error.message}`, false);
      clearAutoBackupTimer();
      setAutoStatus('⏸️ Auto backup paused — folder authorization required');
      return false;
    }
  };

  window.autoBackupToFolder = async function() {
    if (window.__shahidBackupBusy) return false;

    const folderPath = String(db?.backupFolderPath || '').trim();
    const format = String(db?.backupFormat || 'json').toLowerCase() === 'sqlite' ? 'sqlite' : 'json';
    const fileName = format === 'sqlite' ? 'SHAHID_ERP.sqlite' : 'SHAHID_ERP.json';

    if (!folderPath && !(backupFolderHandle || window.backupFolderHandle)) {
      clearAutoBackupTimer();
      setAutoStatus('⏸️ Auto backup paused — select LOCAL backup folder');
      setStatus('⚠️ Local backup folder not selected. Click BROWSE FOLDER.', false);
      return false;
    }

    window.__shahidBackupBusy = true;
    try {
      // SQLite is the shared-database mode. It reads the existing shared
      // database, merges it with the current ERP state, then writes the
      // complete merged database back to the same fixed filename.
      if (format === 'sqlite') {
        if (typeof window.SHAHID_RUN_IMPORT_MERGE_EXPORT_NOW !== 'function') {
          throw new Error('SQLite shared-sync engine is unavailable.');
        }
        const ok = await window.SHAHID_RUN_IMPORT_MERGE_EXPORT_NOW();
        if (!ok) throw new Error('SQLite shared backup/sync failed.');
        setAutoStatus('✅ Running (every 1 min) – SQLite shared sync – SHAHID_ERP.sqlite');
        return true;
      }

      // JSON backup — single complete application snapshot.
      const timestamp = new Date().toISOString();
      const jsonPayload = {
        schema: 'SHAHID-ERP-COMPLETE-APPLICATION-BACKUP-V3',
        timestamp,
        backupType: 'FULL_APPLICATION_SNAPSHOT',
        backupFormat: 'json',
        data: JSON.parse(JSON.stringify(db))
      };
      const jsonText = JSON.stringify(jsonPayload, null, 2);

      // EXE/native mode.
      if (folderPath && window.electronAPI && typeof window.electronAPI.writeBackupFile === 'function') {
        const check = await verifyNativeFolder(folderPath);
        if (!check || check.success !== true || check.writable !== true) {
          clearAutoBackupTimer();
          setAutoStatus('⏸️ Auto backup paused — folder authorization required');
          setStatus('⚠️ Backup folder permission is not available. Click BROWSE FOLDER to re-authorize access.', false);
          return false;
        }

        const result = await window.electronAPI.writeBackupFile(folderPath, fileName, jsonText);
        if (!result || result.success !== true) {
          throw new Error(result?.error || 'Complete JSON backup write failed.');
        }

        db.lastBackup = timestamp;
        saveDB();
        setStatus(`✅ JSON BACKUP COMPLETE — ${fileName} — ${new Date().toLocaleString('en-IN')} — ${folderPath}`, true);
        setAutoStatus('✅ Running (every 1 min) – JSON backup – SHAHID_ERP.json');
        return true;
      }

      // Browser/File System Access mode.
      const folderHandle = backupFolderHandle || window.backupFolderHandle;
      if (!folderHandle) {
        throw new Error('Backup folder is not authorized in this browser.');
      }
      if (typeof folderHandle.queryPermission === 'function') {
        const permission = await folderHandle.queryPermission({mode:'readwrite'});
        if (permission !== 'granted') {
          throw new Error('Backup folder permission is not granted. Click BROWSE FOLDER to re-authorize access.');
        }
      }
      const fileHandle = await folderHandle.getFileHandle(fileName, {create:true});
      const writable = await fileHandle.createWritable({keepExistingData:false});
      try {
        await writable.write(jsonText);
      } finally {
        await writable.close();
      }

      db.lastBackup = timestamp;
      saveDB();
      setStatus(`✅ JSON BACKUP COMPLETE — ${fileName} — ${new Date().toLocaleString('en-IN')} — ${folderHandle.name}`, true);
      setAutoStatus('✅ Running (every 1 min) – JSON backup – SHAHID_ERP.json');
      return true;
    } catch (error) {
      console.error(`${format.toUpperCase()} backup failed:`, error);
      clearAutoBackupTimer();
      setAutoStatus('⏸️ Auto backup paused — backup error requires attention');
      setStatus(`❌ ${format.toUpperCase()} backup failed: ${error.message}`, false);
      return false;
    } finally {
      window.__shahidBackupBusy = false;
    }
  };

  window.autoBackup = async function() {
    return await window.autoBackupToFolder();
  };

  window.startAutoBackup = async function() {
    clearAutoBackupTimer();

    const folderPath = String(db?.backupFolderPath || '').trim();
    if (!folderPath) {
      setAutoStatus('⏸️ Auto backup paused — select LOCAL backup folder');
      return false;
    }

    const check = await verifyNativeFolder(folderPath);
    if (!check || check.success !== true || check.writable !== true) {
      setAutoStatus('⏸️ Auto backup paused — folder authorization required');
      setStatus('⚠️ Backup folder permission is not granted. Click BROWSE FOLDER to authorize it.', false);
      return false;
    }

    const run = async () => {
      if (window.__shahidBackupBusy) return;
      await window.autoBackup();
    };

    window.autoBackupInterval = setInterval(run, 60000);
    try { autoBackupInterval = window.autoBackupInterval; } catch (_) {}

    const activeFormat = String(db?.backupFormat || 'json').toLowerCase() === 'sqlite' ? 'SQLite shared sync – SHAHID_ERP.sqlite' : 'JSON backup – SHAHID_ERP.json';
    setAutoStatus(`✅ Running (every 1 min) – ${activeFormat}`);
    setStatus(`📁 ${folderPath} authorized — automatic ${activeFormat} enabled.`, true);
    return true;
  };

  window.stopAutoBackup = function() {
    clearAutoBackupTimer();
    setAutoStatus('⏸️ Auto backup stopped');
  };

  document.addEventListener('DOMContentLoaded', async function() {
    const savedPath = String(db?.backupFolderPath || '').trim();
    const inputEl = document.getElementById('backup-folder-path-input');
    const displayEl = document.getElementById('backup-folder-path');

    if (!savedPath) {
      setAutoStatus('⏸️ Auto backup paused — select LOCAL backup folder');
      return;
    }

    if (inputEl) inputEl.value = savedPath;
    if (displayEl) displayEl.textContent = `📁 ${savedPath}`;

    // A saved path is not automatically trusted. Verify it before starting
    // the timer so the UI never reports a false "Running" state.
    await startAutoBackup();
  });
})();

/* SHAHID ERP — CRITICAL SQLITE AUTO SYNC FIX V4
   Correct local-folder workflow:
   1) Read SHAHID_ERP.sqlite directly from the selected folder (no file input).
   2) Parse the complete erp_state table.
   3) Merge with the current ERP state.
   4) Persist current ERP state.
   5) Export the merged complete database back to the SAME file.
   This is used only when Backup Format = SQLite.
*/
(function(){
    'use strict';

    const SQLITE_FILE_NAME = 'SHAHID_ERP.sqlite';

    async function getReadyFolder(){
        // Browser/File System Access API: use the actual selected directory handle.
        // Support both legacy lexical reference and window reference.
        const folderHandle = backupFolderHandle || window.backupFolderHandle;

        if(!folderHandle){
            const statusEl = document.getElementById('backup-status');
            if(statusEl){
                statusEl.textContent =
                    '⚠️ Local backup folder is not selected. Click BROWSE FOLDER.';
                statusEl.className = 'backup-status error';
            }
            return null;
        }

        // Automatic/background calls must never invoke requestPermission(), because
        // the File System Access API requires a user activation for that operation.
        // The explicit Browse Folder action is responsible for obtaining permission.
        let permission = 'granted';
        if(typeof folderHandle.queryPermission === 'function'){
            permission = await folderHandle.queryPermission({mode:'readwrite'});
        }
        if(permission !== 'granted'){
            const statusEl = document.getElementById('backup-status');
            if(statusEl){
                statusEl.textContent = '⚠️ Backup folder permission is not granted. Click BROWSE FOLDER to authorize it.';
                statusEl.className = 'backup-status error';
            }
            return null;
        }

        // Keep both references synchronized for subsequent automatic cycles.
        backupFolderHandle = folderHandle;
        window.backupFolderHandle = folderHandle;

        return folderHandle;
    }

    async function readSQLiteStateFromFolder(folderHandle){
        let fileHandle;
        try{
            fileHandle = await folderHandle.getFileHandle(SQLITE_FILE_NAME, {create:false});
        }catch(error){
            // First run: no local SQLite exists yet. This is not an error.
            if(error && (error.name === 'NotFoundError' || error.code === 8)){
                return null;
            }
            throw error;
        }

        const file = await fileHandle.getFile();
        const buffer = await file.arrayBuffer();

        await initSQLite();
        if(!window.SQL) throw new Error('SQLite library failed to load.');

        const sqliteDb = new window.SQL.Database(new Uint8Array(buffer));

        try{
            const check = sqliteDb.prepare(
                "SELECT name FROM sqlite_master WHERE type='table' AND name='erp_state'"
            );
            const hasState = check.step();
            check.free();

            if(!hasState){
                throw new Error('SHAHID_ERP.sqlite does not contain the complete ERP state table.');
            }

            const stmt = sqliteDb.prepare('SELECT key, value_json FROM erp_state');
            const importedState = {};

            while(stmt.step()){
                const row = stmt.getAsObject();

                try{
                    importedState[row.key] = JSON.parse(row.value_json);
                }catch(error){
                    console.warn('Skipping invalid SQLite state key:', row.key, error);
                }
            }

            stmt.free();

            if(!Object.keys(importedState).length){
                throw new Error('SHAHID_ERP.sqlite contains no ERP state.');
            }

            return importedState;
        }finally{
            sqliteDb.close();
        }
    }

    async function exportMergedSQLiteToSameFile(folderHandle){
        const dbInstance = await buildCompleteSQLiteDatabase();

        try{
            const data = dbInstance.export();
            const fileHandle = await folderHandle.getFileHandle(
                SQLITE_FILE_NAME,
                {create:true}
            );

            const writable = await fileHandle.createWritable({
                keepExistingData:false
            });

            try{
                await writable.write(
                    new Blob([data], {type:'application/x-sqlite3'})
                );
            }finally{
                await writable.close();
            }
        }finally{
            dbInstance.close();
        }

        db.lastBackup = new Date().toISOString();
        if(typeof saveDB === 'function') saveDB();

        const statusEl = document.getElementById('backup-status');
        if(statusEl){
            statusEl.textContent =
                `✅ SQLite sync completed: IMPORT → MERGE → EXPORT ` +
                `(${new Date().toLocaleString('en-IN')}) ` +
                `— ${folderHandle.name}/${SQLITE_FILE_NAME}`;
            statusEl.className = 'backup-status success';
        }

        return true;
    }

    window.SHAHID_RUN_IMPORT_MERGE_EXPORT_NOW = async function(){
        if(String(db?.backupFormat || '').toLowerCase() !== 'sqlite'){
            return false;
        }

        // Electron: use one direct local SQLite path and verify the actual file.
        if(window.electronAPI && db?.backupFolderPath){
            try{
                const folderPath = String(db.backupFolderPath || '').trim();
                if(!folderPath){
                    throw new Error('Local backup folder is not configured.');
                }

                const result = await window.electronAPI.readBackupFile(
                    folderPath,
                    SQLITE_FILE_NAME
                );

                if(!result || result.success === false){
                    throw new Error(result?.error || 'Unable to read local SQLite backup.');
                }

                let incoming = null;

                if(result.exists && result.data){
                    await initSQLite();
                    if(!window.SQL) throw new Error('SQLite library failed to load.');

                    const sourceDb = new window.SQL.Database(new Uint8Array(result.data));
                    try{
                        const check = sourceDb.prepare(
                            "SELECT name FROM sqlite_master WHERE type='table' AND name='erp_state'"
                        );
                        const hasState = check.step();
                        check.free();

                        if(!hasState){
                            throw new Error(
                                'SHAHID_ERP.sqlite does not contain the complete ERP state table.'
                            );
                        }

                        const stmt = sourceDb.prepare(
                            'SELECT key, value_json FROM erp_state'
                        );
                        incoming = {};

                        while(stmt.step()){
                            const row = stmt.getAsObject();
                            try{
                                incoming[row.key] = JSON.parse(row.value_json);
                            }catch(parseError){
                                console.warn(
                                    'Skipping invalid SQLite state key:',
                                    row.key,
                                    parseError
                                );
                            }
                        }

                        stmt.free();

                        if(!Object.keys(incoming).length){
                            throw new Error(
                                'SHAHID_ERP.sqlite contains no ERP state.'
                            );
                        }
                    }finally{
                        sourceDb.close();
                    }
                }

                // If a previous local SQLite exists, merge it first.
                if(incoming){
                    if(typeof window.SHAHID_MERGE_LOCAL_SQLITE !== 'function'){
                        throw new Error('SQLite merge engine is not available.');
                    }

                    const merged = await window.SHAHID_MERGE_LOCAL_SQLITE(incoming);
                    if(!merged){
                        throw new Error(
                            'SQLite merge failed; current ERP data was preserved.'
                        );
                    }
                }

                // Persist merged/current ERP state before creating the SQLite file.
                if(typeof window.saveDB === 'function'){
                    await Promise.resolve(window.saveDB());
                }

                // Build the COMPLETE current ERP SQLite and write it directly
                // to the selected local folder.
                const outputDb = await buildCompleteSQLiteDatabase();

                let outputBytes;
                try{
                    outputBytes = outputDb.export();
                }finally{
                    outputDb.close();
                }

                if(!outputBytes || !outputBytes.length){
                    throw new Error('Generated SQLite backup is empty.');
                }

                const writeResult = await window.electronAPI.writeBackupFile(
                    folderPath,
                    SQLITE_FILE_NAME,
                    new Uint8Array(outputBytes)
                );

                if(!writeResult || writeResult.success !== true){
                    throw new Error(
                        writeResult?.error || 'Local SQLite write failed.'
                    );
                }

                // Verify the actual file on disk after the write.
                let verified = null;
                if(typeof window.electronAPI.statBackupFile === 'function'){
                    verified = await window.electronAPI.statBackupFile(
                        folderPath,
                        SQLITE_FILE_NAME
                    );
                }

                if(
                    verified &&
                    (
                        verified.success !== true ||
                        verified.exists !== true ||
                        Number(verified.size) !== Number(outputBytes.length)
                    )
                ){
                    throw new Error(
                        `Local SQLite verification failed: expected ${outputBytes.length} bytes.`
                    );
                }

                db.lastBackup = new Date().toISOString();
                if(typeof saveDB === 'function') saveDB();

                const statusEl = document.getElementById('backup-status');
                if(statusEl){
                    const modifiedText =
                        verified && verified.modifiedAt
                            ? new Date(verified.modifiedAt).toLocaleString('en-IN')
                            : new Date().toLocaleString('en-IN');

                    statusEl.textContent =
                        `✅ LOCAL SQLITE UPDATED — IMPORT → MERGE → EXPORT ` +
                        `(${modifiedText}) — ${folderPath}\\${SQLITE_FILE_NAME}`;

                    statusEl.className = 'backup-status success';
                }

                console.log(
                    'LOCAL SQLITE BACKUP VERIFIED:',
                    folderPath,
                    SQLITE_FILE_NAME,
                    'bytes=', outputBytes.length,
                    'modifiedAt=', verified?.modifiedAt || null
                );

                return true;

            }catch(error){
                console.error(
                    'Local SQLite backup failed. Current ERP database preserved:',
                    error
                );

                const statusEl = document.getElementById('backup-status');
                if(statusEl){
                    statusEl.textContent =
                        `❌ LOCAL SQLITE BACKUP FAILED: ${error.message}`;
                    statusEl.className = 'backup-status error';
                }

                return false;
            }
        }

        const folderHandle = await getReadyFolder();
        if(!folderHandle) return false;

        try{
            const incoming = await readSQLiteStateFromFolder(folderHandle);

            if(incoming){
                if(typeof window.SHAHID_MERGE_LOCAL_SQLITE !== 'function'){
                    throw new Error('SQLite merge engine is not available.');
                }

                const merged = await window.SHAHID_MERGE_LOCAL_SQLITE(incoming);

                if(!merged){
                    throw new Error('SQLite merge failed; current ERP data was preserved.');
                }

                if(typeof window.saveDB === 'function'){
                    await Promise.resolve(window.saveDB());
                }
            }

            // If no backup exists yet, export current ERP as the initial
            // complete SQLite file. If backup exists, this exports the merged state.
            return await exportMergedSQLiteToSameFile(folderHandle);

        }catch(error){
            console.error(
                'SQLite import/merge/export failed. Current database preserved:',
                error
            );

            const statusEl = document.getElementById('backup-status');
            if(statusEl){
                statusEl.textContent =
                    `❌ SQLite sync failed: ${error.message}`;
                statusEl.className = 'backup-status error';
            }

            return false;
        }
    };

    // Correct the adapters used by the old framework APIs so they cannot
    // accidentally invoke the manual <input type="file"> importer.
    window.SHAHID_LOCAL_SQLITE_IMPORT = async function(){
        const folderHandle = await getReadyFolder();
        if(!folderHandle) return null;
        return await readSQLiteStateFromFolder(folderHandle);
    };

    window.SHAHID_LOCAL_SQLITE_EXPORT = async function(){
        const folderHandle = await getReadyFolder();
        if(!folderHandle) return false;
        return await exportMergedSQLiteToSameFile(folderHandle);
    };
})();


/* SHAHID ERP — GOOGLE DRIVE LOCAL MIRROR BACKUP V1
   Google Drive Desktop/Drive-for-desktop folder is a local synced folder.
*/
(function(){
    'use strict';
    const DRIVE_SQLITE_NAME='SHAHID_ERP.sqlite';

    function setDriveStatus(message, ok){
        const el=document.getElementById('google-drive-backup-status');
        if(el){
            el.textContent=message;
            el.className='backup-status '+(ok?'success':'error');
        }
    }

    window.selectGoogleDriveFolder=async function(){
        try{
            if(!window.electronAPI || typeof window.electronAPI.selectBackupFolder!=='function'){
                alert('Google Drive folder selection is available in the EXE version.');
                return;
            }
            const path=await window.electronAPI.selectBackupFolder();
            if(!path) return;
            db.googleDriveFolderPath=path;
            if(typeof saveDB==='function') saveDB();
            const input=document.getElementById('google-drive-folder-path-input');
            const display=document.getElementById('google-drive-folder-path');
            if(input) input.value=path;
            if(display) display.textContent=`☁️ ${path}`;
            setDriveStatus('☁️ Google Drive folder selected — ready for SQLite mirror.',true);
        }catch(error){
            console.error('Google Drive folder selection failed:',error);
            setDriveStatus(`❌ Google Drive folder selection failed: ${error.message}`,false);
        }
    };

    window.saveGoogleDrivePath=function(){
        const input=document.getElementById('google-drive-folder-path-input');
        const path=input?input.value.trim():'';
        if(!path){alert('Please select or enter the Google Drive synced folder path.');return;}
        db.googleDriveFolderPath=path;
        if(typeof saveDB==='function') saveDB();
        const display=document.getElementById('google-drive-folder-path');
        if(display) display.textContent=`☁️ ${path}`;
        setDriveStatus('☁️ Google Drive folder path saved.',true);
    };

    window.SHAHID_EXPORT_CURRENT_SQLITE_TO_GOOGLE_DRIVE=async function(){
        const path=String(db?.googleDriveFolderPath||'').trim();
        if(!path){
            setDriveStatus('⚠️ Google Drive not configured — local SQLite backup completed only.',false);
            return false;
        }
        if(!window.electronAPI || typeof window.electronAPI.writeBackupFile!=='function'){
            setDriveStatus('⚠️ Google Drive mirror requires the EXE/native backup bridge.',false);
            return false;
        }
        try{
            const sqliteDb=await buildCompleteSQLiteDatabase();
            try{
                const result=await window.electronAPI.writeBackupFile(
                    path,DRIVE_SQLITE_NAME,new Uint8Array(sqliteDb.export())
                );
                if(!result || result.success!==true){
                    throw new Error(result?.error||'Unable to write SQLite backup to Google Drive folder.');
                }
            }finally{sqliteDb.close();}
            db.lastGoogleDriveBackup=new Date().toISOString();
            if(typeof saveDB==='function') saveDB();
            setDriveStatus(`☁️ Google Drive SQLite updated: ${new Date().toLocaleString('en-IN')} — ${path}\\${DRIVE_SQLITE_NAME}`,true);
            return true;
        }catch(error){
            console.error('Google Drive SQLite mirror failed:',error);
            setDriveStatus(`❌ Google Drive SQLite update failed: ${error.message}`,false);
            return false;
        }
    };

    window.SHAHID_RUN_LOCAL_AND_GOOGLEDRIVE_BACKUP_NOW=async function(){
        const status=document.getElementById('backup-status');
        try{
            if(status){
                status.textContent='⏳ Local SQLite: IMPORT → MERGE → EXPORT...';
                status.className='backup-status';
            }

            // LOCAL SQLITE — mandatory, offline capable.
            let localOk=false;
            if(typeof window.SHAHID_RUN_IMPORT_MERGE_EXPORT_NOW==='function'){
                localOk=await window.SHAHID_RUN_IMPORT_MERGE_EXPORT_NOW();
            }else if(typeof window.autoBackupToFolder==='function'){
                localOk=await window.autoBackupToFolder();
            }

            if(!localOk) throw new Error('Local SQLite backup failed.');

            // GOOGLE DRIVE — optional second destination.
            const drivePath=String(db?.googleDriveFolderPath||'').trim();

            if(!drivePath){
                if(status){
                    status.textContent=
                        `✅ Local SQLite updated — Google Drive not configured (${new Date().toLocaleString('en-IN')})`;
                    status.className='backup-status success';
                }
                return {localOk:true,driveOk:false,driveSkipped:true};
            }

            if(status){
                status.textContent='✅ Local SQLite updated. Updating Google Drive...';
                status.className='backup-status success';
            }

            let driveOk=false;
            if(typeof window.SHAHID_EXPORT_CURRENT_SQLITE_TO_GOOGLE_DRIVE==='function'){
                driveOk=await window.SHAHID_EXPORT_CURRENT_SQLITE_TO_GOOGLE_DRIVE();
            }

            if(status){
                status.textContent=driveOk
                    ? `✅ Local SQLite + Google Drive SQLite updated — ${new Date().toLocaleString('en-IN')}`
                    : `⚠️ Local SQLite updated. Google Drive update failed — ${new Date().toLocaleString('en-IN')}`;
                // Local backup succeeded; optional Drive failure does not invalidate it.
                status.className='backup-status success';
            }

            return {localOk:true,driveOk};
        }catch(error){
            console.error('Local + Google Drive backup failed:',error);
            if(status){
                status.textContent=`❌ Local SQLite backup failed: ${error.message}`;
                status.className='backup-status error';
            }
            return {localOk:false,driveOk:false,error:error.message};
        }
    };

    document.addEventListener('DOMContentLoaded',function(){
        const path=String(db?.googleDriveFolderPath||'').trim();
        const input=document.getElementById('google-drive-folder-path-input');
        const display=document.getElementById('google-drive-folder-path');
        if(path){
            if(input) input.value=path;
            if(display) display.textContent=`☁️ ${path}`;
            setDriveStatus('☁️ Google Drive folder configured.',true);
        }
    });
})();

// ===== PRODUCT KEY INPUT MASKING =====
// Product keys remain stored/validated exactly as before; only their visual
// representation is masked while the user types.
function maskProductKeyInputs() {
    document.querySelectorAll('input').forEach(input => {
        const idName = ((input.id || '') + ' ' + (input.name || '')).toLowerCase();
        const labelText = input.closest('label')?.textContent?.toLowerCase() || '';
        const contextText = input.parentElement?.textContent?.toLowerCase() || '';
        if (idName.includes('product') && idName.includes('key') ||
            idName.includes('productkey') ||
            labelText.includes('product key') ||
            contextText.includes('product key')) {
            input.type = 'password';
            input.autocomplete = 'off';
            input.spellcheck = false;
        }
    });
}

document.addEventListener('DOMContentLoaded', maskProductKeyInputs);



/* ============================================================================
   SHAHID ERP — ALL-TAB FUNCTION COMPLETENESS PATCH
   Restores missing tab initialization/refresh hooks without redesigning tabs.
   Existing tab renderers remain the single source of truth.
============================================================================ */
(function(){
    'use strict';

    const originalTabSwitch = window.switchToTab;
    if(typeof originalTabSwitch === 'function' && !originalTabSwitch.__SHAHID_ALL_TAB_COMPLETENESS){
        const patchedSwitch = function(targetTab){
            const result = originalTabSwitch.apply(this, arguments);
            try{
                switch(String(targetTab || '')){
                    case 'planner':
                        if(typeof initPlanner === 'function') initPlanner();
                        break;
                    case 'invoice':
                        if(typeof renderInvoiceTab === 'function') renderInvoiceTab();
                        break;
                    case 'localcharges':
                        if(typeof switchLocalTab === 'function') switchLocalTab(window.currentLocalTab || 'sea');
                        break;
                    case 'reporting':
                        if(typeof showReportingMenu === 'function') setTimeout(showReportingMenu, 50);
                        break;
                    case 'actioncenter':
                        if(typeof renderActionCenter === 'function') renderActionCenter();
                        break;
                    case 'measurement':
                        if(typeof showMeasurementMenu === 'function') showMeasurementMenu();
                        break;
                }
            }catch(e){ console.warn('All-tab initialization skipped:', e); }
            return result;
        };
        patchedSwitch.__SHAHID_ALL_TAB_COMPLETENESS = true;
        window.switchToTab = patchedSwitch;
    }

    const originalRefresh = window.refreshCurrentTab;
    if(typeof originalRefresh === 'function' && !originalRefresh.__SHAHID_ALL_TAB_COMPLETENESS){
        const patchedRefresh = function(){
            const result = originalRefresh.apply(this, arguments);
            try{
                const active = document.querySelector('.tab-panel.active')?.id || '';
                switch(active){
                    case 'invoice': if(typeof renderInvoiceTab === 'function') renderInvoiceTab(); break;
                    case 'planner': if(typeof refreshPlanner === 'function') refreshPlanner(); else if(typeof initPlanner === 'function') initPlanner(); break;
                    case 'reporting': {
                        const panel = document.querySelector('#reporting .report-panel.active');
                        const id = panel?.id || '';
                        const map = {
                            'report-panel-salesreport':'renderSalesReport',
                            'report-panel-opsreport':'renderOperationsReport',
                            'report-panel-dashboard':'renderDashboard',
                            'report-panel-profitreport':'renderProfitabilityReport',
                            'report-panel-customer360':'renderCustomer360',
                            'report-panel-dsr-exceptions':'renderDSRExceptions',
                            'report-panel-cutoff-calendar':'renderCutoffCalendar',
                            'report-panel-container-tracker':'renderContainerTracker',
                            'report-panel-carrierreport':'renderCarrierPerformance',
                            'report-panel-receivables':'renderReceivables'
                        };
                        const fn = map[id];
                        if(fn && typeof window[fn] === 'function') window[fn]();
                        break;
                    }
                    case 'localcharges': if(typeof switchLocalTab === 'function') switchLocalTab(window.currentLocalTab || 'sea'); break;
                    case 'actioncenter': if(typeof renderActionCenter === 'function') renderActionCenter(); break;
                    case 'measurement': if(typeof showMeasurementMenu === 'function') showMeasurementMenu(); break;
                }
            }catch(e){ console.warn('All-tab refresh skipped:', e); }
            return result;
        };
        patchedRefresh.__SHAHID_ALL_TAB_COMPLETENESS = true;
        window.refreshCurrentTab = patchedRefresh;
    }

    window.SHAHID_TAB_FUNCTION_AUDIT = function(){
        const requirements = {
            raterequest:['populateRateRequestDropdowns','switchRateRequestFormat','sendRateRequestEmail','previewRateRequest','saveRateRequestDraft','clearRateRequestForm'],
            sea:['buildChargesGrid','saveRecord','clearFormWithConfirm','downloadPDF','previewQuote','emailQuote'],
            air:['buildChargesGrid','saveRecord','clearFormWithConfirm','downloadPDF','previewQuote','emailQuote'],
            lcl:['buildChargesGrid','saveRecord','clearFormWithConfirm','downloadPDF','previewQuote','emailQuote'],
            drafts:['renderRecords','clearFilters'],
            rates:['renderRecords','ratesBulkAction','clearRatesFilters'],
            ratesheet:['renderRateSheet','openRateSheetModal','processBulkRateImport','exportRateSheetReport'],
            rrdrafts:['renderRecords','clearRRDraftsFilters'],
            dsr:['renderShipments','dsrAddNew','dsrRunSelectedAction','exportDSRToExcel'],
            bldraft:['renderBLDrafts','bldraftBulkAction','exportBLDraftsToExcel'],
            invoice:['renderInvoiceTab','invoiceActionPreview','invoiceActionEdit','invoiceActionCopyCompact','invoiceActionEmail','invoiceActionPDF','invoiceActionWhatsApp','invoiceActionDelete'],
            planner:['initPlanner','refreshPlanner','plannerAddTaskModal','plannerAddNote','plannerSaveNote'],
            reporting:['showReportingMenu','switchReportTab','renderSalesReport','renderCustomerFollowup','renderOperationsReport','renderProfitabilityReport','renderCustomer360','renderDSRExceptions','renderCutoffCalendar','renderContainerTracker','renderCarrierPerformance','renderReceivables'],
            measurement:['showMeasurementMenu','switchCalcTab','calcDuty','calcProduct','calcInsurance','calcUSDuty','renderFreightRecords'],
            database:['renderDatabase','saveCompanyInfo','saveDefaultCC','saveDefaultUser','exportToSQLite','importFromSQLite'],
            localcharges:['switchLocalTab','renderDefaultChargesMaster','renderCarrierChargesMaster','localChargesAction']
        };
        const result={};
        Object.entries(requirements).forEach(([tab,names])=>{
            const missing=names.filter(name=>typeof window[name] !== 'function');
            result[tab]={ok:missing.length===0,missing};
        });
        return result;
    };
})();

// ==================== EMBEDDED QUOTATION CALCULATORS ====================
// Non-invasive duplicates of the existing Measurement calculators.
// They use the same calculation rules and the existing saved-record arrays,
// but use unique DOM IDs so they cannot interfere with the original tools.
function calculateCBMEmbedded() {
    const length = parseFloat(document.getElementById('lcl-cbm-length')?.value) || 0;
    const width = parseFloat(document.getElementById('lcl-cbm-width')?.value) || 0;
    const height = parseFloat(document.getElementById('lcl-cbm-height')?.value) || 0;
    const unit = document.getElementById('lcl-cbm-unit')?.value || 'cm';
    const qty = parseFloat(document.getElementById('lcl-cbm-qty')?.value) || 1;
    let lengthM = length, widthM = width, heightM = height;
    if (unit === 'cm') { lengthM = length / 100; widthM = width / 100; heightM = height / 100; }
    else if (unit === 'inch') { lengthM = length * 0.0254; widthM = width * 0.0254; heightM = height * 0.0254; }
    else if (unit === 'mm') { lengthM = length / 1000; widthM = width / 1000; heightM = height / 1000; }
    const cbm = lengthM * widthM * heightM * qty;
    const result = document.getElementById('lcl-cbm-result');
    if (result) result.value = cbm.toFixed(4) + ' CBM';
    const saveBtn = document.getElementById('lcl-cbm-save-btn');
    if (saveBtn) {
        saveBtn.style.display = 'inline-block';
        saveBtn.dataset.length = length;
        saveBtn.dataset.width = width;
        saveBtn.dataset.height = height;
        saveBtn.dataset.unit = unit;
        saveBtn.dataset.qty = qty;
        saveBtn.dataset.cbm = cbm;
    }
    renderCBMRecordsEmbedded();
}

function saveCBMRecordEmbedded() {
    const btn = document.getElementById('lcl-cbm-save-btn');
    if (!btn) return;
    const length = parseFloat(btn.dataset.length) || 0;
    const width = parseFloat(btn.dataset.width) || 0;
    const height = parseFloat(btn.dataset.height) || 0;
    const unit = btn.dataset.unit || 'cm';
    const qty = parseFloat(btn.dataset.qty) || 1;
    const cbm = parseFloat(btn.dataset.cbm) || 0;
    if (length === 0 || width === 0 || height === 0) return alert('Please fill all dimensions first.');
    if (!db.cbmRecords) db.cbmRecords = [];
    db.cbmRecords.push({ id: 'CBM-' + Date.now().toString(36).toUpperCase(), length, width, height, unit, qty, cbm, timestamp: new Date().toISOString() });
    saveDB();
    renderCBMRecords();
    renderCBMRecordsEmbedded();
    alert('CBM record saved!');
}

function deleteCBMRecordEmbedded(id) {
    if (!confirm('Delete this CBM record?')) return;
    db.cbmRecords = (db.cbmRecords || []).filter(r => r.id !== id);
    saveDB();
    renderCBMRecords();
    renderCBMRecordsEmbedded();
}

function renderCBMRecordsEmbedded() {
    const container = document.getElementById('lcl-cbm-records-list');
    if (!container) return;
    const records = db.cbmRecords || [];
    if (!records.length) {
        container.innerHTML = '<p style="color:var(--text-light);padding:10px;text-align:center;">No CBM records saved.</p>';
        return;
    }
    container.innerHTML = `<table class="master-table"><thead><tr><th>#</th><th>L</th><th>W</th><th>H</th><th>Unit</th><th>Qty</th><th>CBM</th><th>Date</th><th>Action</th></tr></thead><tbody>${records.map((r,i)=>`<tr><td>${i+1}</td><td>${r.length}</td><td>${r.width}</td><td>${r.height}</td><td>${r.unit}</td><td>${r.qty}</td><td><strong>${Number(r.cbm||0).toFixed(4)}</strong></td><td>${new Date(r.timestamp).toLocaleDateString('en-IN')}</td><td><button class="btn btn-sm btn-clear" onclick="deleteCBMRecordEmbedded('${r.id}')">×</button></td></tr>`).join('')}</tbody></table>`;
}

function calculateAirChargeableEmbedded() {
    const length = parseFloat(document.getElementById('rr-aircalc-length')?.value) || 0;
    const width = parseFloat(document.getElementById('rr-aircalc-width')?.value) || 0;
    const height = parseFloat(document.getElementById('rr-aircalc-height')?.value) || 0;
    const unit = document.getElementById('rr-aircalc-unit')?.value || 'cm';
    const qty = parseFloat(document.getElementById('rr-aircalc-qty')?.value) || 1;
    let volumeCm3 = 0;
    if (unit === 'cm') volumeCm3 = length * width * height;
    else if (unit === 'inch') volumeCm3 = (length * 2.54) * (width * 2.54) * (height * 2.54);
    else if (unit === 'mm') volumeCm3 = (length / 10) * (width / 10) * (height / 10);
    const chargeableWeight = (volumeCm3 / 6000) * qty;
    const result = document.getElementById('rr-aircalc-result');
    if (result) result.value = chargeableWeight.toFixed(2) + ' KGS';
    const saveBtn = document.getElementById('rr-aircalc-save-btn');
    if (saveBtn) {
        saveBtn.style.display = 'inline-block';
        saveBtn.dataset.length = length;
        saveBtn.dataset.width = width;
        saveBtn.dataset.height = height;
        saveBtn.dataset.unit = unit;
        saveBtn.dataset.qty = qty;
        saveBtn.dataset.weight = chargeableWeight;
    }
    renderAirWeightRecordsEmbedded();
}

function saveAirWeightRecordEmbedded() {
    const btn = document.getElementById('rr-aircalc-save-btn');
    if (!btn) return;
    const length = parseFloat(btn.dataset.length) || 0;
    const width = parseFloat(btn.dataset.width) || 0;
    const height = parseFloat(btn.dataset.height) || 0;
    const unit = btn.dataset.unit || 'cm';
    const qty = parseFloat(btn.dataset.qty) || 1;
    const weight = parseFloat(btn.dataset.weight) || 0;
    if (length === 0 || width === 0 || height === 0) return alert('Please fill all dimensions first.');
    if (!db.airWeightRecords) db.airWeightRecords = [];
    db.airWeightRecords.push({ id: 'AIR-' + Date.now().toString(36).toUpperCase(), length, width, height, unit, qty, weight, timestamp: new Date().toISOString() });
    saveDB();
    renderAirWeightRecords();
    renderAirWeightRecordsEmbedded();
    alert('Air weight record saved!');
}

function deleteAirWeightRecordEmbedded(id) {
    if (!confirm('Delete this air weight record?')) return;
    db.airWeightRecords = (db.airWeightRecords || []).filter(r => r.id !== id);
    saveDB();
    renderAirWeightRecords();
    renderAirWeightRecordsEmbedded();
}

function renderAirWeightRecordsEmbedded() {
    const container = document.getElementById('rr-aircalc-records-list');
    if (!container) return;
    const records = db.airWeightRecords || [];
    if (!records.length) {
        container.innerHTML = '<p style="color:var(--text-light);padding:10px;text-align:center;">No air weight records saved.</p>';
        return;
    }
    container.innerHTML = `<table class="master-table"><thead><tr><th>#</th><th>L</th><th>W</th><th>H</th><th>Unit</th><th>Qty</th><th>Chargeable Wt (KGS)</th><th>Date</th><th>Action</th></tr></thead><tbody>${records.map((r,i)=>`<tr><td>${i+1}</td><td>${r.length}</td><td>${r.width}</td><td>${r.height}</td><td>${r.unit}</td><td>${r.qty}</td><td><strong>${Number(r.weight||0).toFixed(2)}</strong></td><td>${new Date(r.timestamp).toLocaleDateString('en-IN')}</td><td><button class="btn btn-sm btn-clear" onclick="deleteAirWeightRecordEmbedded('${r.id}')">×</button></td></tr>`).join('')}</tbody></table>`;
}

(function initEmbeddedQuotationCalculators(){
    const render = () => {
        if (typeof renderCBMRecordsEmbedded === 'function') renderCBMRecordsEmbedded();
        if (typeof renderAirWeightRecordsEmbedded === 'function') renderAirWeightRecordsEmbedded();
    };
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', render, { once:true });
    else render();
})();


// ============================================================
// LOCAL CHARGES — CANONICAL DATA-INTEGRITY PATCH
// ============================================================
(function(){
  'use strict';
  const LC_MODES = new Set(['sea','air','lcl']);
  const norm = v => String(v ?? '').trim().replace(/\s+/g,' ').toUpperCase();
  const modeNorm = v => { const x=norm(v); return x==='SEALCL'?'SEA':x.toLowerCase(); };
  const commodityNorm = v => {
    const x=norm(v);
    if(x==='HAZ' || x==='HAZARDOUS') return 'HAZ';
    return 'NON HAZ';
  };
  const containerNorm = v => {
    const x=norm(v);
    if(!x || x==='ALL' || x==='ALL / GENERAL') return 'ALL';
    if(/^20\s*(GP|DV|DC)?$/.test(x) || x.includes('20 GP')) return '20 GP';
    if(/^40\s*(HC|HQ)$/.test(x) || x.includes('40 HC')) return '40 HC';
    if(/^40\s*(GP|DV|DC)?$/.test(x) || x.includes('40 GP')) return '40 GP';
    return x;
  };
  const stamp = () => new Date().toISOString();
  const ensureArrays = () => {
    db.defaultSeaCharges ||= []; db.defaultAirCharges ||= []; db.defaultLclCharges ||= [];
    db.carrierChargesSeaLcl ||= []; db.carrierChargesAir ||= []; db.seaTHCRates ||= [];
  };
  const defaultKey = (mode,r) => {
    const m=modeNorm(mode);
    return `D|${m}|${norm(r.pol)}|${commodityNorm(r.commodity)}|${m==='sea'?containerNorm(r.container):'ALL'}`;
  };
  const carrierKey = (type,r) => {
    const m=type==='air'?'air':type==='lcl'?'lcl':'sea';
    return `C|${m}|${norm(r.carrier)}|${norm(r.pol)}|${commodityNorm(r.commodity)}|${m==='air'?'ALL':containerNorm(r.container)}`;
  };
  const thcKey = r => `T|SEA|${norm(r.carrier)}|${norm(r.pol)}|${commodityNorm(r.commodity)}|${norm(r.currency||'')}`;
  const active = r => r && r.deleted !== true;
  const markDeleted = r => { if(!r)return false; const t=stamp(); r.deleted=true; r.deletedAt=t; r.updated=t; r.updatedAt=t; return true; };
  const findIndexByKey = (arr,keyFn,rec,exclude=-1) => arr.findIndex((r,i)=>i!==exclude && active(r) && keyFn(r)===keyFn(rec));
  const reactivateIfFreshIncoming = (existing,incoming) => {
    if(existing?.deleted && incoming && incoming.deleted !== true){
      const eDel=Date.parse(existing.deletedAt||existing.updatedAt||existing.updated||0)||0;
      const iTime=Date.parse(incoming.updatedAt||incoming.updated||incoming.createdAt||0)||0;
      if(iTime >= eDel || !eDel) return true;
    }
    return false;
  };

  // Repair legacy records in-place without changing unrelated data.
  window.normalizeLocalChargesData = function(){
    ensureArrays();
    db.defaultSeaCharges.forEach(r=>{ r.mode='sea'; r.commodity=commodityNorm(r.commodity); r.container=containerNorm(r.container); r.updatedAt ||= r.updated || r.createdAt || stamp(); });
    db.defaultAirCharges.forEach(r=>{ r.mode='air'; r.commodity=commodityNorm(r.commodity); r.container='ALL'; r.updatedAt ||= r.updated || r.createdAt || stamp(); });
    db.defaultLclCharges.forEach(r=>{ r.mode='lcl'; r.commodity=commodityNorm(r.commodity); r.container='ALL'; r.updatedAt ||= r.updated || r.createdAt || stamp(); });
    db.carrierChargesSeaLcl.forEach(r=>{ r.mode=modeNorm(r.mode||'sea'); r.commodity=commodityNorm(r.commodity); r.container=containerNorm(r.container); r.updatedAt ||= r.updated || r.createdAt || stamp(); });
    db.carrierChargesAir.forEach(r=>{ r.mode='air'; r.commodity=commodityNorm(r.commodity); r.container='ALL'; r.updatedAt ||= r.updated || r.createdAt || stamp(); });
    db.seaTHCRates.forEach(r=>{ r.mode='sea'; r.commodity=commodityNorm(r.commodity); r.updatedAt ||= r.updated || r.createdAt || stamp(); });
    return db;
  };

  window.getLocalChargeBusinessKey = function(kind,type,record){
    if(kind==='default') return defaultKey(type,record);
    if(kind==='carrier') return carrierKey(type,record);
    if(kind==='thc') return thcKey(record);
    return '';
  };

  window.findDefaultChargeDuplicate = function(mode,record,excludeIndex){
    ensureArrays(); const arr=mode==='sea'?db.defaultSeaCharges:mode==='air'?db.defaultAirCharges:db.defaultLclCharges;
    return findIndexByKey(arr,r=>defaultKey(mode,r),record,excludeIndex)>=0;
  };
  window.findCarrierChargeDuplicate = function(type,record,excludeIndex){
    ensureArrays(); const arr=type==='air'?db.carrierChargesAir:db.carrierChargesSeaLcl;
    return findIndexByKey(arr,r=>carrierKey(type,r),record,excludeIndex)>=0;
  };

  window.deleteLocalChargeByKey = function(kind,type,key){
    ensureArrays(); let arr,keyFn;
    if(kind==='default'){ arr=type==='sea'?db.defaultSeaCharges:type==='air'?db.defaultAirCharges:db.defaultLclCharges; keyFn=r=>defaultKey(type,r); }
    else if(kind==='carrier'){ arr=type==='air'?db.carrierChargesAir:db.carrierChargesSeaLcl; keyFn=r=>carrierKey(type,r); }
    else { arr=db.seaTHCRates; keyFn=thcKey; }
    const idx=arr.findIndex(r=>active(r)&&keyFn(r)===key); if(idx<0)return false;
    markDeleted(arr[idx]); saveDB(); return true;
  };

  window.bulkDeleteSelectedLocal = function(){
    ensureArrays();
    const selected=[...document.querySelectorAll('.dc-checkbox:checked,.cc-checkbox:checked,.thc-checkbox:checked')];
    if(!selected.length) return alert('Please select at least one Local Charges record.');
    if(!confirm(`Delete ${selected.length} selected Local Charges record(s)?`)) return;
    let deleted=0;
    selected.forEach(el=>{
      const idx=Number(el.dataset.idx); if(!Number.isInteger(idx)||idx<0)return;
      let arr=null;
      if(el.classList.contains('dc-checkbox')){ const m=el.dataset.mode; arr=m==='sea'?db.defaultSeaCharges:m==='air'?db.defaultAirCharges:db.defaultLclCharges; }
      else if(el.classList.contains('cc-checkbox')){ const t=el.dataset.type||el.dataset.mode; arr=t==='air'?db.carrierChargesAir:db.carrierChargesSeaLcl; }
      else arr=db.seaTHCRates;
      if(arr?.[idx] && markDeleted(arr[idx])) deleted++;
    });
    saveDB();
    if(typeof renderDefaultChargesMaster==='function') renderDefaultChargesMaster(currentLocalTab||'sea');
    if(typeof renderCarrierChargesMaster==='function') renderCarrierChargesMaster(currentLocalTab==='sea'?'sealcl':currentLocalTab||'air');
    if(typeof renderSeaTHCMaster==='function') renderSeaTHCMaster();
    autoBackup();
    alert(`✅ Deleted ${deleted} Local Charges record(s).`);
  };

  // Canonical Local Charges merge: exact business key only; deleted records are
  // not allowed to block a genuinely new active import.
  const originalMerge = window.shahidMasterMergeDatabase;
  if(typeof originalMerge==='function'){
    window.shahidMasterMergeDatabase = function(current,incoming){
      const merged=originalMerge(current,incoming);
      // Reconcile critical Local Charges collections again using the canonical
      // keys, correcting legacy-key collisions from the older merge engine.
      const collections=[
        ['defaultSeaCharges','default','sea'],['defaultAirCharges','default','air'],['defaultLclCharges','default','lcl'],
        ['carrierChargesSeaLcl','carrier','sea'],['carrierChargesAir','carrier','air'],['seaTHCRates','thc','sea']
      ];
      const sourceCurrent=current||{}, sourceIncoming=incoming||{};
      collections.forEach(([name,kind,type])=>{
        const a=Array.isArray(sourceCurrent[name])?sourceCurrent[name]:[];
        const b=Array.isArray(sourceIncoming[name])?sourceIncoming[name]:[];
        const out=[]; const pos=new Map();
        const keyFn=kind==='default'?(r=>defaultKey(type,r)):kind==='carrier'?(r=>carrierKey(type==='air'?'air':type==='lcl'?'lcl':'sealcl',r)):thcKey;
        const put=(r,preferIncoming)=>{
          if(!r || typeof r!=='object')return;
          const x={...r};
          if(kind==='default'){x.mode=type;x.commodity=commodityNorm(x.commodity);x.container=type==='sea'?containerNorm(x.container):'ALL';}
          if(kind==='carrier'){x.mode=type;x.commodity=commodityNorm(x.commodity);x.container=type==='air'?'ALL':containerNorm(x.container);}
          const k=keyFn(x); if(!k || k.endsWith('|ALL') && kind==='default' && type!=='sea'){}
          const p=pos.get(k);
          if(p===undefined){pos.set(k,out.length);out.push(x);return;}
          const ex=out[p];
          if(reactivateIfFreshIncoming(ex,x)){ out[p]={...ex,...x,deleted:false,deletedAt:undefined}; return; }
          const et=Date.parse(ex.updatedAt||ex.updated||ex.createdAt||0)||0;
          const xt=Date.parse(x.updatedAt||x.updated||x.createdAt||0)||0;
          if(preferIncoming && xt>=et) out[p]={...ex,...x};
        };
        a.forEach(r=>put(r,false)); b.forEach(r=>put(r,true));
        merged[name]=out;
      });
      return merged;
    };
  }

  // Normalize once after all original scripts have loaded.
  setTimeout(()=>{ try{ window.normalizeLocalChargesData(); saveDB(); }catch(e){ console.error('Local Charges normalization failed',e); } },0);
})();

// ============================================================
// LOCAL CHARGES — MASTER UI SAVE / IMPORT OVERRIDES
// ============================================================
(function(){
  'use strict';
  const N=v=>String(v??'').trim().replace(/\s+/g,' ').toUpperCase();
  const C=v=>{const x=N(v);return x==='HAZ'||x==='HAZARDOUS'?'HAZ':'NON HAZ';};
  const CN=v=>{const x=N(v);if(!x||x==='ALL'||x==='ALL / GENERAL')return 'ALL';if(x.includes('20 GP')||x==='20GP')return '20 GP';if(x.includes('40 HC')||x==='40HC'||x==='40HQ')return '40 HC';if(x.includes('40 GP')||x==='40GP')return '40 GP';return x;};
  const now=()=>new Date().toISOString();
  const arrDefault=m=>m==='sea'?db.defaultSeaCharges:m==='air'?db.defaultAirCharges:db.defaultLclCharges;
  const arrCarrier=t=>t==='air'?db.carrierChargesAir:db.carrierChargesSeaLcl;
  const dKey=(m,r)=>`D|${N(m)}|${N(r.pol)}|${C(r.commodity)}|${m==='sea'?CN(r.container):'ALL'}`;
  const cKey=(t,r)=>`C|${N(t)}|${N(r.carrier)}|${C(r.commodity)}|${t==='air'?'ALL':CN(r.container)}`;
  const active=r=>r&&!r.deleted;
  const touch=r=>{const t=now();r.updated=t;r.updatedAt=t;if(!r.createdAt)r.createdAt=t;};
  const clearDeleted=r=>{r.deleted=false;delete r.deletedAt;};

  function collectDefaultCharges(mode){
    const charges={}; const rows=document.querySelectorAll('#modal-dc-charges-list [data-charge-key]');
    rows.forEach(row=>{
      const base=row.getAttribute('data-charge-key'); if(!base)return;
      if(mode==='sea'){
        const a20=parseFloat(row.querySelector('.modal-chg-amt20')?.value)||0,b20=parseFloat(row.querySelector('.modal-chg-buy20')?.value)||0,a40=parseFloat(row.querySelector('.modal-chg-amt40')?.value)||0,b40=parseFloat(row.querySelector('.modal-chg-buy40')?.value)||0,cur=row.querySelector('.modal-chg-cur')?.value||'INR';
        if(a20>0||b20>0)charges[base+'_20']={amount:a20,buyAmount:b20,currency:cur};
        if(a40>0||b40>0)charges[base+'_40']={amount:a40,buyAmount:b40,currency:cur};
      }else{
        const s=parseFloat(row.querySelector('.modal-chg-single-sell')?.value)||0,b=parseFloat(row.querySelector('.modal-chg-single-buy')?.value)||0,cur=row.querySelector('.modal-chg-cur')?.value||'INR';
        if(s>0||b>0)charges[base]={amount:s,buyAmount:b,currency:cur};
      }
    });
    return charges;
  }

  window.saveNewDefaultCharge=function(mode){
    const pol=document.getElementById('modal-dc-pol')?.value.trim()||'';
    const commodity=C(document.getElementById('modal-dc-commodity')?.value);
    if(!pol)return alert('POL is required.');
    const charges=collectDefaultCharges(mode); if(!Object.keys(charges).length)return alert('Please add at least one charge with a value.');
    const rec={mode,pol,commodity,container:'ALL',charges,createdAt:now(),updatedAt:now(),updated:now()};
    const arr=arrDefault(mode);
    if(arr.some(r=>active(r)&&dKey(mode,r)===dKey(mode,rec)))return alert(`Duplicate entry: ${dKey(mode,rec)}`);
    arr.push(rec); saveDB(); closeModal('previewModal'); renderDefaultChargesMaster(mode); autoBackup(); alert('✅ Default charge added successfully!');
  };

  window.saveEditDefaultCharge=function(mode,idx){
    const arr=arrDefault(mode), rec=arr?.[idx]; if(!rec)return alert('Record not found.');
    const pol=document.getElementById('modal-dc-pol-edit')?.value.trim()||''; if(!pol)return alert('POL is required.');
    const commodity=C(document.getElementById('modal-dc-commodity-edit')?.value);
    const charges=collectDefaultCharges(mode); if(!Object.keys(charges).length)return alert('Please add at least one charge with a value.');
    const candidate={...rec,mode,pol,commodity,container:mode==='sea'?CN(rec.container):'ALL',charges};
    const dup=arr.findIndex((r,i)=>i!==idx&&active(r)&&dKey(mode,r)===dKey(mode,candidate));
    if(dup>=0)return alert(`Duplicate entry: ${dKey(mode,candidate)}`);
    arr[idx]=candidate; clearDeleted(arr[idx]); touch(arr[idx]); saveDB(); closeModal('previewModal'); renderDefaultChargesMaster(mode); autoBackup(); alert('✅ Default charge updated successfully!');
  };

  function collectCarrierCharges(){
    const charges={};
    document.querySelectorAll('#modal-cc-charges-list [data-charge-key]').forEach(row=>{
      const key=row.getAttribute('data-charge-key'); if(!key)return;
      const s=parseFloat(row.querySelector('.modal-cc-sell-amt')?.value)||0,b=parseFloat(row.querySelector('.modal-cc-buy-amt')?.value)||0,sc=row.querySelector('.modal-cc-sell-cur')?.value||'INR',bc=row.querySelector('.modal-cc-buy-cur')?.value||sc;
      if(s>0||b>0)charges[key]={amount:s,currency:sc,buyAmount:b,buyCurrency:bc};
    }); return charges;
  }
  function carrierForm(type){
    const carrier=document.getElementById('modal-cc-carrier')?.value.trim()||'';
    const pol=document.getElementById('modal-cc-pol')?.value.trim()||'';
    const commodity=C(document.getElementById('modal-cc-commodity')?.value);
    const mode=type==='air'?'air':type==='lcl'?'lcl':'sea';
    return {mode,carrier,pol,commodity,container:mode==='air'?'ALL':CN(document.getElementById('modal-cc-container')?.value||'ALL')};
  }
  function carrierEditForm(type){
    const carrier=document.getElementById('modal-cc-carrier-edit')?.value.trim()||'';
    const pol=document.getElementById('modal-cc-pol-edit')?.value.trim()||'';
    const commodity=C(document.getElementById('modal-cc-commodity-edit')?.value);
    const mode=type==='air'?'air':type==='lcl'?'lcl':'sea';
    return {mode,carrier,pol,commodity,container:mode==='air'?'ALL':CN(document.getElementById('modal-cc-container-edit')?.value||'ALL')};
  }

  // Backward-compatible add: if old modal has no container selector, ALL is used.
  window.saveNewCarrierCharge=function(type){
    const f=carrierForm(type); if(!f.carrier)return alert('Carrier is required');
    const charges=collectCarrierCharges(); if(!Object.keys(charges).length)return alert('Please add at least one charge with a value.');
    const rec={...f,charges,createdAt:now(),updated:now(),updatedAt:now()}; const arr=arrCarrier(type);
    if(arr.some(r=>active(r)&&cKey(type,r)===cKey(type,rec)))return alert(`Duplicate entry: ${cKey(type,rec)}`);
    arr.push(rec); saveDB(); closeModal('previewModal'); renderCarrierChargesMaster(type==='sea'?'sealcl':type); autoBackup(); alert('✅ Carrier charge added successfully.');
  };

  window.saveEditCarrierCharge=function(type,idx){
    const arr=arrCarrier(type), rec=arr?.[idx]; if(!rec)return alert('Record not found.');
    const f=carrierEditForm(type); if(!f.carrier)return alert('Carrier is required.');
    const charges=collectCarrierCharges(); if(!Object.keys(charges).length)return alert('Please add at least one charge with a value.');
    const candidate={...rec,...f,charges}; const dup=arr.findIndex((r,i)=>i!==idx&&active(r)&&cKey(type,r)===cKey(type,candidate));
    if(dup>=0)return alert(`Duplicate entry: ${cKey(type,candidate)}`);
    arr[idx]=candidate;clearDeleted(arr[idx]);touch(arr[idx]);saveDB();closeModal('previewModal');renderCarrierChargesMaster(type==='sea'?'sealcl':type);autoBackup();alert('✅ Carrier charge updated.');
  };

  // Combined legacy Local Charges workbook importer. It now uses the same keys as
  // the dedicated importers and supports new records instead of only merging values.
  window.bulkImportLocalCharges=function(input){
    const file=input?.files?.[0]; if(!file)return;
    if(typeof XLSX==='undefined')return alert('XLSX library not loaded.');
    const reader=new FileReader();
    reader.onload=function(e){
      try{
        const wb=XLSX.read(new Uint8Array(e.target.result),{type:'array',cellDates:true});
        const plans=[]; const errors=[];
        const parseRows=(sheetName,mode,fields)=>{
          const sh=wb.Sheets[sheetName];if(!sh)return;
          const rows=XLSX.utils.sheet_to_json(sh,{defval:'',raw:false});
          const groups=new Map();
          rows.forEach((row,i)=>{
            const pol=N(row.POL),commodity=C(row.Commodity||row.CARGO),container=mode==='sea'?CN(row.Container||'ALL'):'ALL';
            if(!pol||!['HAZ','NON HAZ'].includes(commodity))return errors.push(`${sheetName} row ${i+2}: POL and HAZ/NON HAZ are required.`);
            const base={pol,commodity,container};
            if(mode!=='air'&&row.Carrier!==undefined)base.carrier=N(row.Carrier); else if(mode==='sea')base.carrier='ALL';
            const key=fields.map(k=>N(base[k])).join('|');
            if(!groups.has(key))groups.set(key,{...base,charges:{}});
            const ch=row['Charge Name']; if(ch){const amount=parseFloat(String(row['Sell Amount']||'').replace(/[^\d.-]/g,''))||0;const buy=parseFloat(String(row['Buy Amount']||'').replace(/[^\d.-]/g,''))||0;if(amount||buy)groups.get(key).charges[N(ch)]={amount,currency:N(row['Sell Currency'])||'INR',buyAmount:buy,buyCurrency:N(row['Buy Currency'])||N(row['Sell Currency'])||'INR',basis:row.Basis||'Normal'};}
          });
          groups.forEach(g=>plans.push({mode,default:true,...g}));
        };
        parseRows('Sea Default','sea',['carrier','pol','container','commodity']);
        parseRows('Air Default','air',['pol','commodity']);
        parseRows('Lcl Default','lcl',['pol','commodity']);
        const csl=wb.Sheets['Carrier Sea/Lcl']; if(csl){
          const groups=new Map(); XLSX.utils.sheet_to_json(csl,{defval:'',raw:false}).forEach((row,i)=>{const mode=N(row.Mode).toLowerCase()==='lcl'?'lcl':'sea',carrier=N(row.Carrier),pol=N(row.POL),commodity=C(row.Commodity),container=CN(row.Container||'ALL');if(!carrier)return errors.push(`Carrier Sea/Lcl row ${i+2}: Carrier is required.`);const key=[mode,carrier,container,commodity].join('|');if(!groups.has(key))groups.set(key,{mode,carrier,pol,commodity,container,charges:{}});const ch=row['Charge Name'];if(ch){const a=parseFloat(row['Sell Amount'])||0,b=parseFloat(row['Buy Amount'])||0;if(a||b)groups.get(key).charges[N(ch)]={amount:a,currency:N(row['Sell Currency'])||'INR',buyAmount:b,buyCurrency:N(row['Buy Currency'])||N(row['Sell Currency'])||'INR',basis:row.Basis||'Normal'};}});groups.forEach(g=>plans.push({carrier:true,...g}));
        }
        const ca=wb.Sheets['Carrier Air']; if(ca){const groups=new Map();XLSX.utils.sheet_to_json(ca,{defval:'',raw:false}).forEach((row,i)=>{const carrier=N(row.Carrier),pol=N(row.POL),commodity=C(row.Commodity);if(!carrier)return errors.push(`Carrier Air row ${i+2}: Carrier is required.`);const key=[carrier,commodity].join('|');if(!groups.has(key))groups.set(key,{mode:'air',carrier,pol,commodity,container:'ALL',charges:{}});const ch=row['Charge Name'];if(ch){const a=parseFloat(row['Sell Amount'])||0,b=parseFloat(row['Buy Amount'])||0;if(a||b)groups.get(key).charges[N(ch)]={amount:a,currency:N(row['Sell Currency'])||'INR',buyAmount:b,buyCurrency:N(row['Buy Currency'])||N(row['Sell Currency'])||'INR',basis:row.Basis||'Normal'};}});groups.forEach(g=>plans.push({carrier:true,...g}));}
        if(errors.length)return alert('❌ Import validation failed:\n\n'+errors.slice(0,30).join('\n'));
        if(!plans.length)return alert('No supported Local Charges records found.');
        if(!confirm(`Import ${plans.length} Local Charges record group(s)? Existing exact matches will be updated; new business keys will be added.`))return;
        let added=0,updated=0;
        plans.forEach(x=>{
          if(x.carrier){const arr=arrCarrier(x.mode);let idx=arr.findIndex(r=>active(r)&&cKey(x.mode,r)===cKey(x.mode,x));if(idx<0){arr.push({mode:x.mode,carrier:x.carrier,pol:x.pol,commodity:x.commodity,container:x.container,charges:{},createdAt:now()});idx=arr.length-1;added++;}else updated++;const r=arr[idx];Object.assign(r,{mode:x.mode,carrier:x.carrier,pol:x.pol,commodity:x.commodity,container:x.container});r.charges={...(r.charges||{}),...x.charges};clearDeleted(r);touch(r);
          }else{const m=x.mode,arr=arrDefault(m);let idx=arr.findIndex(r=>active(r)&&dKey(m,r)===dKey(m,x));if(idx<0){arr.push({mode:m,pol:x.pol,commodity:x.commodity,container:x.container,charges:{},createdAt:now()});idx=arr.length-1;added++;}else updated++;const r=arr[idx];Object.assign(r,{mode:m,pol:x.pol,commodity:x.commodity,container:x.container});r.charges={...(r.charges||{}),...x.charges};clearDeleted(r);touch(r);}
        });
        saveDB();renderDefaultChargesMaster(currentLocalTab||'sea');renderCarrierChargesMaster(currentLocalTab==='sea'?'sealcl':currentLocalTab||'air');autoBackup();alert(`✅ Local Charges import completed.\nNew records: ${added}\nUpdated records: ${updated}`);
      }catch(err){console.error(err);alert('❌ Local Charges import failed: '+err.message);}finally{input.value='';}
    };reader.readAsArrayBuffer(file);
  };
})();

// ============================================================
// FINAL LOCAL CHARGES CARRIER IMPORT/RENDER FIX
// Scope: Carrier-Specific Charges + Dedicated SEA THC + Import Carrier only
// Uses legacy persisted arrays as the single active UI source of truth.
// ============================================================
(function(){
  'use strict';
  const U=v=>String(v??'').trim().replace(/\s+/g,' ').toUpperCase();
  const cargo=v=>{const x=U(v); return x==='HAZ'||x==='HAZARDOUS'?'HAZ':'NON HAZ';};
  const cont=v=>{let x=U(v); if(!x||x==='ALL'||x==='ALL / GENERAL')return 'ALL'; if(/20\s*(GP|DV|DC)?/.test(x))return '20 GP'; if(/40\s*(HC|HQ)/.test(x))return '40 HC'; if(/40\s*(GP|DV|DC)?/.test(x))return '40 GP'; return x;};
  const mode=v=>{const x=U(v); return x==='LCL'?'lcl':x==='AIR'?'air':'sea';};
  const active=r=>r&&!r.deleted;
  const stamp=()=>new Date().toISOString();
  const esc2=v=>String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
  const arrFor=t=>t==='air'?(db.carrierChargesAir||(db.carrierChargesAir=[])):(db.carrierChargesSeaLcl||(db.carrierChargesSeaLcl=[]));
  // FINAL Carrier Local Charges identity: CARRIER + HAZ/NON HAZ.
  // Container is intentionally NOT a key because the same charges apply to ALL containers.
  const carrierKey2=(m,r)=>['C',m,U(r.carrier),cargo(r.commodity),'ALL'].join('|');
  const thcKey2=r=>['T','SEA',U(r.carrier),U(r.pol),cargo(r.commodity),U(r.currency)].join('|');
  // SEA Carrier Local Charges import columns. Keep this list locally scoped so
  // the final import engine never depends on a cols2 variable from another IIFE.
  const carrierSeaChargeColumns=['SEAL','MUC','DOCS','SEAWAY BL','ETS','HAZ DOCS','AMS'];
  const sheetByName=(wb,names)=>{const wanted=names.map(U); const k=Object.keys(wb.Sheets||{}).find(s=>wanted.includes(U(s))); return k?wb.Sheets[k]:null;};
  const parseNum=v=>{if(v===null||v===undefined||String(v).trim()==='')return null; const n=Number(String(v).replace(/,/g,'').replace(/[^0-9.+-]/g,'')); return Number.isFinite(n)?n:null;};
  // Local parser for this IIFE. Do not reference parse2 from another IIFE/scope.
  const parse2=v=>{
    if(v===undefined||v===null||String(v).trim()==='') return null;
    const raw=String(v).trim();
    const currency=raw.includes('$')?'USD':'INR';
    const amount=parseNum(raw);
    return amount===null?null:{amount,currency,buyAmount:amount,buyCurrency:currency};
  };
  const money=(amount,currency,buyAmount,buyCurrency,basis)=>({amount:Number(amount)||0,currency:U(currency)||'INR',buyAmount:Number(buyAmount)||0,buyCurrency:U(buyCurrency)||U(currency)||'INR',basis:basis||'Normal'});

  function normalizeCarrierRecord(r,m){
    r.mode=m; r.carrier=U(r.carrier); r.pol=String(r.pol??'').trim(); r.commodity=cargo(r.commodity); r.container='ALL'; r.charges=r.charges||{}; r.updatedAt=r.updatedAt||r.updated||r.createdAt||stamp(); r.updated=r.updated||r.updatedAt; return r;
  }
  function normalizeTHCRecord(r){
    r.mode='sea'; r.carrier=U(r.carrier); r.pol=String(r.pol??'').trim(); r.commodity=cargo(r.commodity); r.container='ALL'; r.currency=U(r.currency)||'INR'; r.updatedAt=r.updatedAt||r.updated||r.createdAt||stamp(); r.updated=r.updated||r.updatedAt; return r;
  }
  function touch2(r){const t=stamp();r.updated=t;r.updatedAt=t;if(!r.createdAt)r.createdAt=t;}

  // FINAL BUSINESS RULE: the same Carrier Local Charges apply to ALL containers.
  // Collapse legacy SEA container-specific records into one logical record per
  // CARRIER + HAZ/NON HAZ while preserving charge values and newest metadata.
  function reconcileAllContainerCarrierCharges(){
    const arr=Array.isArray(db.carrierChargesSeaLcl)?db.carrierChargesSeaLcl:[];
    const out=[]; const pos=new Map(); let changed=false;
    arr.forEach(src=>{
      if(!src||typeof src!=='object') return;
      const r={...src,mode:'sea',carrier:U(src.carrier),commodity:cargo(src.commodity),container:'ALL',charges:{...(src.charges||{})}};
      const key=`${r.carrier}|${r.commodity}`;
      const i=pos.get(key);
      if(i===undefined){pos.set(key,out.length);out.push(r);return;}
      const ex=out[i];
      const exTime=Date.parse(ex.updatedAt||ex.updated||ex.createdAt||0)||0;
      const rTime=Date.parse(r.updatedAt||r.updated||r.createdAt||0)||0;
      ex.charges={...(ex.charges||{}),...(r.charges||{})};
      if(rTime>=exTime) out[i]={...ex,...r,container:'ALL',charges:{...(ex.charges||{}),...(r.charges||{})}};
      changed=true;
    });
    if(out.length!==arr.length) changed=true;
    if(changed){db.carrierChargesSeaLcl=out;saveDB();}
    return db.carrierChargesSeaLcl;
  }

  // Render every Carrier table from the same persisted arrays used by Import/Save.
  window.renderCarrierChargesMaster=function(type){
    const t=type==='sealcl'?'sea':type==='lcl'?'lcl':'air';
    if(t==='sea') reconcileAllContainerCarrierCharges();
    const el=document.getElementById(`cc-${type}-master-table`); if(!el)return;
    const search=U(document.getElementById(`cc-${type}-search`)?.value||'');
    const arr=arrFor(t).map((r,i)=>({r,i})).filter(x=>active(x.r)).filter(x=>{
      const r=x.r; const text=[r.carrier,r.commodity].map(U).join(' '); return !search||text.includes(search);
    });
    // Carrier Local Charges table intentionally shows ONLY business-facing fields.
    // POL and Container are hidden from the row as requested. Container remains an
    // internal matching dimension and is automatically used by New Quote lookup.
    let html=`<table class="master-table"><thead><tr><th style="width:42px;text-align:center;"><input type="checkbox" class="select-all-cc" data-type="${type}" title="Select all"></th><th>Carrier</th><th>HAZ / NON HAZ</th><th>Charges</th><th>Updated</th></tr></thead><tbody>`;
    if(!arr.length) html+=`<tr><td colspan="5" style="text-align:center;padding:16px;color:var(--text-light);">No carrier-specific records.</td></tr>`;
    arr.forEach(({r,i})=>{
      const count=Object.keys(r.charges||{}).filter(k=>!/^THC(?:_|$)/i.test(k)).length;
      html+=`<tr><td style="text-align:center;"><input type="checkbox" class="cc-checkbox" data-type="${type}" data-idx="${i}"></td><td><strong>${esc2(r.carrier)}</strong></td><td>${esc2(r.commodity)}</td><td style="text-align:center"><strong>${count}</strong></td><td>${r.updated?new Date(r.updated).toLocaleDateString('en-IN'):'—'}</td></tr>`;
    });
    html+='</tbody></table>'; el.innerHTML=html;
    el.querySelectorAll('.select-all-cc').forEach(cb=>cb.addEventListener('change',function(){el.querySelectorAll('.cc-checkbox').forEach(c=>c.checked=this.checked);if(typeof updateSelectedCount==='function')updateSelectedCount();}));
    el.querySelectorAll('.cc-checkbox').forEach(cb=>cb.addEventListener('change',()=>{if(typeof updateSelectedCount==='function')updateSelectedCount();}));
    if(typeof updateLocalChargeToolbar==='function')updateLocalChargeToolbar('cc',type,arr.length);
  };

  window.findCarrierChargeDuplicate=function(type,record,excludeIndex){
    const t=type==='sealcl'?'sea':type==='lcl'?'lcl':'air'; const arr=arrFor(t); const key=carrierKey2(t,record);
    return arr.findIndex((r,i)=>i!==excludeIndex&&active(r)&&carrierKey2(t,r)===key)>=0;
  };
  window.getLocalChargeBusinessKey=function(kind,type,record){
    if(kind==='carrier')return carrierKey2(type==='sealcl'?'sea':type==='lcl'?'lcl':'air',record);
    if(kind==='thc')return thcKey2(record);
    if(typeof window.__getPreviousLocalChargeBusinessKey==='function')return window.__getPreviousLocalChargeBusinessKey(kind,type,record);
    return '';
  };

  // Robust Import Carrier. Supports the current exported workbook and legacy
  // sheet names. Carrier Local Charges identity = CARRIER + HAZ/NON HAZ + CONTAINER.
  // POL is preserved as metadata only and is NEVER used for Carrier Local Charge matching.
  window.bulkImportCarrierCharges=function(input){
    const file=input?.files?.[0];
    if(!file)return alert('Please select an Excel file.');
    if(typeof XLSX==='undefined')return alert('XLSX library not loaded.');

    const reader=new FileReader();
    reader.onload=function(e){
      try{
        const wb=XLSX.read(new Uint8Array(e.target.result),{type:'array',cellDates:true});
        reconcileAllContainerCarrierCharges();
        const plans=[];
        const errors=[];
        const warnings=[];
        let sheetsProcessed=0;

        const rowsOf=sh=>XLSX.utils.sheet_to_json(sh,{defval:'',raw:false});
        const headerMap=row=>Object.keys(row).reduce((m,k)=>{m[U(k)]=k;return m;},{});
        const getCell=(row,names)=>{
          const map=headerMap(row);
          for(const name of names){
            const k=map[U(name)];
            if(k!==undefined)return row[k];
          }
          return '';
        };
        const hasColumn=(row,names)=>{
          const map=headerMap(row);
          return names.some(n=>map[U(n)]!==undefined);
        };

        // Supports both approved horizontal exports:
        // SEAL | MUC | DOCS | SEAWAY BL | ETS | HAZ DOCS | AMS
        // and legacy vertical charge-row workbooks.
        const addChargesFromRow=(target,row,mode,rowNo)=>{
          let imported=0;
          const columns=mode==='sea'?carrierSeaChargeColumns:[];
          columns.forEach(col=>{
            if(!hasColumn(row,[col]))return;
            const raw=getCell(row,[col]);
            if(raw===undefined||raw===null||String(raw).trim()==='')return;
            const parsed=parse2(raw);
            if(!parsed){errors.push(`SEA - LOCAL CHARGES Row ${rowNo}: invalid amount in ${col} (${raw}).`);return;}
            target.charges[col]={...parsed};
            imported++;
          });

          // Legacy vertical format: one charge name + amount per row.
          const chargeName=getCell(row,['Charge Name','Charge','CHARGE','Charge Type']);
          if(chargeName){
            const name=U(chargeName);
            if(!/^THC(?:_|$)/i.test(name)){
              const rawSell=getCell(row,['Sell Amount','SELL AMOUNT','Amount','AMOUNT','Sell','SELL']);
              const rawBuy=getCell(row,['Buy Amount','BUY AMOUNT','Buy','BUY']);
              const rawCur=getCell(row,['Sell Currency','SELL CURRENCY','Currency','CURRENCY']);
              const rawBuyCur=getCell(row,['Buy Currency','BUY CURRENCY']);
              const sell=parse2(rawSell);
              const buy=parse2(rawBuy);
              if(sell||buy){
                const currency=U(rawCur)||sell?.currency||buy?.currency||'INR';
                const buyCurrency=U(rawBuyCur)||buy?.currency||currency;
                target.charges[name]={
                  amount:sell?.amount??0,
                  currency,
                  buyAmount:buy?.amount??sell?.amount??0,
                  buyCurrency,
                  basis:String(getCell(row,['Basis','BASIS'])||'Normal').trim()||'Normal'
                };
                imported++;
              }
            }
          }
          return imported;
        };

        function processCarrierSheet(names,fixedMode){
          const sheetName=names.find(n=>Object.keys(wb.Sheets||{}).some(k=>U(k)===U(n)));
          if(!sheetName)return;
          sheetsProcessed++;
          const rows=rowsOf(wb.Sheets[sheetName]);
          if(!rows.length){warnings.push(`${sheetName}: no data rows.`);return;}

          const first=rows[0];
          const groups=new Map();
          const seenRows=new Set();

          rows.forEach((row,i)=>{
            const rowNo=i+2;
            const m=fixedMode||mode(getCell(row,['MODE','Mode'])||'SEA');
            if(m!=='sea'&&m!=='air'&&m!=='lcl'){
              errors.push(`${sheetName} Row ${rowNo}: invalid MODE.`);return;
            }
            const carrier=U(getCell(row,['CARRIER','Carrier']));
            const pol=String(getCell(row,['POL','Port of Loading'])??'').trim();
            const hazRaw=getCell(row,['CARGO','HAZ / NON HAZ','HAZ/NON HAZ','Commodity']);
            const haz=cargo(hazRaw||'NON HAZ');
            const container='ALL';

            if(!carrier){errors.push(`${sheetName} Row ${rowNo}: Carrier is required.`);return;}
            if(!['HAZ','NON HAZ'].includes(haz)){errors.push(`${sheetName} Row ${rowNo}: CARGO must be HAZ or NON HAZ.`);return;}
            

            const base={mode:m,carrier,pol,commodity:haz,container,charges:{}};
            const key=carrierKey2(m,base);
            let target=groups.get(key);
            if(!target){target=base;groups.set(key,target);}
            else if(!target.pol&&pol)target.pol=pol;

            const before=Object.keys(target.charges).length;
            addChargesFromRow(target,row,m,rowNo);
            const after=Object.keys(target.charges).length;

            // If the row contains no recognized charge column, preserve it as a warning
            // rather than silently importing an empty rate record.
            if(after===before && !hasColumn(row,['Charge Name','Charge','CHARGE','Charge Type']) && m==='sea'){
              warnings.push(`${sheetName} Row ${rowNo}: no supported charge value found.`);
            }

            // Duplicate rows with the same canonical key are merged into one logical record.
            if(seenRows.has(key)){
              // Deliberately no error: multiple rows for one business key are supported
              // when they carry different charge columns/values.
            }
            seenRows.add(key);
          });

          groups.forEach(g=>{
            if(!Object.keys(g.charges||{}).length){
              warnings.push(`${sheetName}: ${g.carrier} / ${g.commodity} / ${g.container} contains no charge values.`);
            }
            plans.push({kind:'carrier',...g});
          });
        }

        processCarrierSheet(['SEA - LOCAL CHARGES'],'sea');
        processCarrierSheet(['AIR - LOCAL CHARGES'],'air');
        processCarrierSheet(['LCL - LOCAL CHARGES'],'lcl');
        processCarrierSheet(['Carrier Sea/Lcl'],'');
        processCarrierSheet(['Carrier Air'],'air');

        // Dedicated SEA THC import remains independent from Carrier Local Charges.
        const thcName=['SEA - THC','LC SEA THC'].find(n=>Object.keys(wb.Sheets||{}).some(k=>U(k)===U(n)));
        if(thcName){
          sheetsProcessed++;
          const rows=rowsOf(wb.Sheets[thcName]);
          const groups=new Map();
          rows.forEach((row,i)=>{
            const rowNo=i+2;
            const carrier=U(getCell(row,['CARRIER','Carrier']));
            const pol=String(getCell(row,['POL','Port of Loading'])??'').trim();
            const haz=cargo(getCell(row,['CARGO','HAZ / NON HAZ','HAZ/NON HAZ','Commodity'])||'NON HAZ');
            const currency=U(getCell(row,['CURRENCY','Currency'])||'INR');
            if(!carrier||!pol){errors.push(`${thcName} Row ${rowNo}: Carrier and POL are required.`);return;}
            if(!['HAZ','NON HAZ'].includes(haz)){errors.push(`${thcName} Row ${rowNo}: CARGO must be HAZ or NON HAZ.`);return;}
            if(!['INR','USD'].includes(currency)){errors.push(`${thcName} Row ${rowNo}: CURRENCY must be INR or USD.`);return;}
            const base={carrier,pol,commodity:haz,currency,thc20:null,thc40:null,validFrom:String(getCell(row,['VALID FROM'])||'').trim(),validTo:String(getCell(row,['VALID TO'])||'').trim()};
            const key=thcKey2(base);
            const g=groups.get(key)||base;
            const v20=parse2(getCell(row,['THC 20 GP']));
            const v40=parse2(getCell(row,['THC 40 HC']));
            if(v20)g.thc20=v20.amount;
            if(v40)g.thc40=v40.amount;
            if(getCell(row,['VALID FROM']))g.validFrom=String(getCell(row,['VALID FROM'])).trim();
            if(getCell(row,['VALID TO']))g.validTo=String(getCell(row,['VALID TO'])).trim();
            groups.set(key,g);
          });
          groups.forEach(g=>plans.push({kind:'thc',...g}));
        }

        if(!sheetsProcessed)throw new Error('No recognized Carrier/Local Charges sheets found.');
        if(errors.length){
          alert(`❌ Import Carrier validation failed.\n\n${errors.slice(0,30).join('\n')}${errors.length>30?'\n...more errors':''}`);
          return;
        }
        if(!plans.length)return alert('No supported Carrier records found in the selected workbook.');

        if(!confirm(`Import ${plans.length} Carrier/THC record group(s)?\n\nExact Carrier keys will be updated. New keys will be added.`))return;

        let added=0,updated=0,values=0;
        plans.forEach(p=>{
          const t=stamp();
          if(p.kind==='thc'){
            db.seaTHCRates ||= [];
            let rec=db.seaTHCRates.find(r=>!r.deleted&&thcKey2(r)===thcKey2(p));
            if(!rec){
              rec={mode:'sea',carrier:p.carrier,pol:p.pol,commodity:p.commodity,container:'ALL',currency:p.currency,thc20:null,thc40:null,validFrom:'',validTo:'',createdAt:t,updated:t,updatedAt:t};
              db.seaTHCRates.push(rec);added++;
            }else updated++;
            Object.assign(rec,{mode:'sea',carrier:p.carrier,pol:p.pol,commodity:p.commodity,container:'ALL',currency:p.currency});
            if(p.thc20!==null&&p.thc20!==undefined){rec.thc20=p.thc20;values++;}
            if(p.thc40!==null&&p.thc40!==undefined){rec.thc40=p.thc40;values++;}
            if(p.validFrom)rec.validFrom=p.validFrom;
            if(p.validTo)rec.validTo=p.validTo;
            rec.deleted=false;delete rec.deletedAt;rec.updated=t;rec.updatedAt=t;
          }else{
            const arr=arrFor(p.mode);
            // IMPORTANT: Carrier Local Charges key intentionally excludes POL.
            // POL is preserved as metadata from the first/available imported row.
            const key=carrierKey2(p.mode,p);
            let rec=arr.find(r=>!r.deleted&&carrierKey2(p.mode,r)===key);
            if(!rec)rec=arr.find(r=>carrierKey2(p.mode,r)===key); // allow reactivation of a deleted matching record
            if(!rec){
              rec={mode:p.mode,carrier:p.carrier,pol:p.pol||'',commodity:p.commodity,container:p.container,charges:{},createdAt:t,updated:t,updatedAt:t};
              arr.push(rec);added++;
            }else updated++;

            rec.mode=p.mode;
            rec.carrier=p.carrier;
            if(!rec.pol&&p.pol)rec.pol=p.pol; // metadata only; never used in matching
            rec.commodity=p.commodity;
            rec.container=p.container;
            rec.charges ||= {};

            Object.entries(p.charges||{}).forEach(([k,v])=>{
              if(/^THC(?:_|$)/i.test(k))return;
              rec.charges[k]={...v};
              values++;
            });
            rec.validFrom=p.validFrom||rec.validFrom||'';
            rec.validTo=p.validTo||rec.validTo||'';
            rec.deleted=false;delete rec.deletedAt;rec.updated=t;rec.updatedAt=t;
            rec.key=key;
          }
        });

        // Persist first, then render. Rendering must never be able to roll back a valid import.
        saveDB();
        try{ window.normalizeLocalChargesData?.(); saveDB(); }catch(e){console.warn('Carrier import post-save normalization warning:',e);}

        const tab=currentLocalTab||'sea';
        if(typeof renderCarrierChargesMaster==='function')renderCarrierChargesMaster(tab==='sea'?'sealcl':tab);
        if(tab==='sea'&&typeof renderSeaTHCMaster==='function')renderSeaTHCMaster();
        if(typeof autoBackup==='function')autoBackup();

        alert(`✅ Import Carrier completed.\nSheets processed: ${sheetsProcessed}\nNew records: ${added}\nUpdated records: ${updated}\nCharge/THC values imported: ${values}${warnings.length?'\n\nWarnings:\n'+warnings.slice(0,15).join('\n'):''}`);
      }catch(err){
        console.error('Final Carrier Import Error:',err);
        alert('❌ Import Carrier failed: '+(err?.message||err));
      }finally{
        try{input.value='';}catch(_e){}
      }
    };
    reader.readAsArrayBuffer(file);
  };

  // Make bulk delete use the same actual persisted index and ignore deleted rows.
  window.bulkDeleteSelectedLocal=function(){
    const selected=[...document.querySelectorAll('.cc-checkbox:checked,.dc-checkbox:checked,.thc-checkbox:checked')];
    if(!selected.length)return alert('Please select at least one Local Charges record.');
    if(!confirm(`Delete ${selected.length} selected Local Charges record(s)?`))return;
    let deleted=0;
    selected.forEach(el=>{
      const idx=Number(el.dataset.idx); if(!Number.isInteger(idx))return;
      let arr=null;
      if(el.classList.contains('cc-checkbox')){
        const t=el.dataset.type||el.dataset.mode;
        arr=t==='air'?db.carrierChargesAir:db.carrierChargesSeaLcl;
      }else if(el.classList.contains('thc-checkbox')){
        arr=db.seaTHCRates;
      }else{
        const m=el.dataset.mode;
        arr=m==='air'?db.defaultAirCharges:m==='lcl'?db.defaultLclCharges:db.defaultSeaCharges;
      }
      const r=arr?.[idx];
      if(r && r.deleted!==true){
        const isCarrier=el.classList.contains('cc-checkbox');
        const isSeaCarrier=isCarrier && (el.dataset.type||el.dataset.mode)==='sealcl';
        if(isSeaCarrier){
          const key=`${U(r.carrier)}|${cargo(r.commodity)}`;
          (db.carrierChargesSeaLcl||[]).forEach(x=>{if(x&&!x.deleted&&`${U(x.carrier)}|${cargo(x.commodity)}`===key){markDeleted(x);deleted++;}});
        }else{
          r.deleted=true;r.deletedAt=stamp();r.updated=stamp();r.updatedAt=r.updated;deleted++;
        }
      }
    });
    saveDB();
    const tab=currentLocalTab||'sea';
    if(typeof renderDefaultChargesMaster==='function')renderDefaultChargesMaster(tab);
    if(typeof renderCarrierChargesMaster==='function')renderCarrierChargesMaster(tab==='sea'?'sealcl':tab);
    if(tab==='sea'&&typeof renderSeaTHCMaster==='function')renderSeaTHCMaster();
    if(typeof autoBackup==='function')autoBackup();
    alert(`✅ Deleted ${deleted} Local Charges record(s).`);
  };

  // Normalize the legacy carrier collections on load without collapsing different keys.
  try{
    reconcileAllContainerCarrierCharges();
    (db.carrierChargesSeaLcl||[]).forEach(r=>normalizeCarrierRecord(r,r.mode==='lcl'?'lcl':'sea'));
    (db.carrierChargesAir||[]).forEach(r=>normalizeCarrierRecord(r,'air'));
    (db.seaTHCRates||[]).forEach(normalizeTHCRecord);
  }catch(e){console.error('Carrier Local Charges normalization failed:',e);}
})();

